                if (!moved) {
                    return;
                }
                this._suppressTouchZoneClickUntil = Date.now() + 350;

                // Flush exact final pixel height where the user stopped — zero snapping, stays fixed right here!
                const vh = cachedVh || window.innerHeight || 800;
