function getHintPlaceholder(token) {
    if (!token) return '';
    if (token.length <= 2) return token;
    return `${token[0]}  ${token[token.length - 1]}`;
}

function measureClozeWordWidth(word) {
    if (!word) return 56;
    const isMobile = (typeof window !== 'undefined' && (window.innerWidth <= 600 || document.body.classList.contains('pc-phone-frame-mode')));
    const isLandscape = (typeof document !== 'undefined') && (
        document.documentElement.getAttribute('data-toy-orientation') === 'landscape' ||
        document.body.classList.contains('is-landscape')
    );

    let fontSize = isLandscape ? 15.5 : (isMobile ? 26 : 30);
    let fontFamily = '"Inter", "Noto Sans SC", "Source Han Sans SC", "LXGW WenKai GB Screen", sans-serif';
    let fontWeight = '500';
    let letterSpacing = 'normal';

    const clozeCard = (typeof document !== 'undefined') ? document.getElementById('dict-cloze-card') : null;
    if (clozeCard && typeof window.getComputedStyle === 'function') {
        try {
            const cs = window.getComputedStyle(clozeCard);
            const parsedFs = parseFloat(cs.fontSize);
            if (parsedFs && parsedFs > 10) fontSize = parsedFs;
            if (cs.fontFamily) fontFamily = cs.fontFamily;
            if (cs.fontWeight) fontWeight = cs.fontWeight;
            if (cs.letterSpacing) letterSpacing = cs.letterSpacing;
        } catch (e) {}
    }

    // 1. Canvas measurement with "Inter" included
    const canvas = measureClozeWordWidth.canvas || (measureClozeWordWidth.canvas = document.createElement('canvas'));
    const ctx = canvas.getContext('2d');
    ctx.font = `${fontWeight} ${fontSize}px ${fontFamily}`;
    const canvasMeasured = ctx.measureText(word).width;

    // 2. Real DOM span measurement to capture exact webfont & subpixel advance widths
    let domMeasured = 0;
    if (typeof document !== 'undefined' && document.body) {
        try {
            let span = measureClozeWordWidth._span;
            if (!span || !document.body.contains(span)) {
                span = document.createElement('span');
                span.setAttribute('aria-hidden', 'true');
                span.style.cssText = 'position:fixed;top:-9999px;left:-9999px;visibility:hidden;pointer-events:none;white-space:nowrap;padding:0;margin:0;border:0;';
                document.body.appendChild(span);
                measureClozeWordWidth._span = span;
            }
            span.style.fontFamily = fontFamily;
            span.style.fontSize = `${fontSize}px`;
            span.style.fontWeight = fontWeight;
            span.style.letterSpacing = letterSpacing;
            span.textContent = word;
            domMeasured = span.getBoundingClientRect().width;
        } catch (e) {}
    }

    const measured = Math.max(canvasMeasured, domMeasured);
    // Extra safety buffer for compound/long words (e.g. "six-year-old") and answer/skeleton modes
    const charSafetyBuffer = Math.ceil(word.length * (isLandscape ? 0.6 : 1.0));
    const modeExtra = (dictAnswerModeActive || dictSkeletonModeActive) ? (isLandscape ? 6 : 10) : 0;
    const horizPadding = (isLandscape ? 18 : (isMobile ? 24 : 30)) + charSafetyBuffer + modeExtra;
    const minWidth = isLandscape ? 44 : (isMobile ? 54 : 64);
    return Math.max(minWidth, Math.ceil(measured) + horizPadding);
}

function fuseClozeInputIntoText(input, word) {
    try {
        const wrap = input.closest('.cloze-input-wrap');
        if (!wrap || !wrap.parentNode) return;

        const tokenIdx = parseInt(input.dataset.tokenIdx);
        const sentIdx = parseInt(input.dataset.sentIdx) || currentDictIndex;

        if (!window.currentSentenceSolvedTokens) {
            window.currentSentenceSolvedTokens = {};
        }
        if (!window.currentSentenceSolvedTokens[sentIdx]) {
            window.currentSentenceSolvedTokens[sentIdx] = new Set();
        }
        if (!isNaN(tokenIdx)) {
            window.currentSentenceSolvedTokens[sentIdx].add(tokenIdx);
        }

        const doneSpan = document.createElement('span');
        doneSpan.className = 'cloze-word-done';
        if (wrap.classList.contains('cloze-has-punct')) {
            doneSpan.classList.add('cloze-has-punct');
        }
        doneSpan.dataset.tokenIdx = String(tokenIdx);
        doneSpan.dataset.sentIdx = String(sentIdx);
        doneSpan.style.minWidth = `${measureClozeWordWidth(word)}px`;
        doneSpan.style.width = 'auto';
        doneSpan.style.whiteSpace = 'nowrap';
        if (typeof makeTextClickable === 'function') {
            doneSpan.innerHTML = makeTextClickable(word);
        } else {
            doneSpan.textContent = word;
        }

        wrap.parentNode.replaceChild(doneSpan, wrap);
    } catch(err) {
        console.error('[DictationEngine] fuseClozeInputIntoText error:', err);
    }
}

window.getHintPlaceholder = getHintPlaceholder;
window.measureClozeWordWidth = measureClozeWordWidth;
window.fuseClozeInputIntoText = fuseClozeInputIntoText;

function getActiveDictExamLevel() {
    let curLvl = null;
    if (currentDictExamTitle) {
        let meta = (typeof findExamMeta === 'function') ? findExamMeta(currentDictExamTitle) : null;
        curLvl = meta ? meta.level : null;
        if (!curLvl) {
            if (currentDictExamTitle.includes('雅思') || currentDictExamTitle.toLowerCase().includes('ielts')) curLvl = 'ielts';
            else if (currentDictExamTitle.includes('高考')) curLvl = 'gaokao';
            else if (currentDictExamTitle.includes('六级')) curLvl = 'cet6';
            else if (currentDictExamTitle.includes('四级')) curLvl = 'cet4';
        }
    }
    return curLvl || window.currentExamLevel || 'cet4';
}
window.getActiveDictExamLevel = getActiveDictExamLevel;


/* === js/dictation_lobby.js === */
// ==========================================================================
// Dictation & Daily Listening Lobby Grid, Filter Bar & Startup (js/dictation_lobby.js)
// ==========================================================================

// 1. Render Dictation Lobby Grid
function renderDictationLobbyGrid(filterRange, options = {}) {
    const grid = document.getElementById('dictation-exam-grid');
    if (!grid) return;
    
    const curLvlCheck = window.currentExamLevel || 'cet4';
    let activeFilter = filterRange || window.currentDictationFilter || 'ALL';
    if (curLvlCheck === 'ielts' && activeFilter !== 'ALL' && !activeFilter.startsWith('ielts_')) {
        activeFilter = 'ALL';
    } else if (curLvlCheck !== 'ielts' && activeFilter.startsWith('ielts_')) {
        activeFilter = 'ALL';
    } else if (curLvlCheck !== 'gaokao' && activeFilter === '2008-2014') {
        activeFilter = 'ALL';
    }
    window.currentDictationFilter = activeFilter;

    const manifestList = (typeof getActiveExamManifest === 'function')
        ? getActiveExamManifest()
        : (window.CLOZE_EXAMS_MAP ? Object.keys(window.CLOZE_EXAMS_MAP).map(t => ({ title: t })) : []);

    if (!manifestList || manifestList.length === 0) {
        const retryCount = (options && typeof options._retryCount === 'number') ? options._retryCount : 0;
        if (retryCount < 40) {
            setTimeout(() => renderDictationLobbyGrid(activeFilter, Object.assign({}, options, { _retryCount: retryCount + 1 })), 50);
        } else {
            grid.innerHTML = '<div style="grid-column: 1 / -1; text-align: center; padding: 36px 16px; color: var(--ink-sub); font-size: 13.5px;">暂无可用精听试卷，请检查网络后重试</div>';
        }
        return;
    }

    const dictFilterBar = document.getElementById('dictation-year-filter-bar');
    if (dictFilterBar) {
        dictFilterBar.querySelectorAll('.chip-year').forEach(c => {
            c.classList.toggle('active', (c.dataset.range || 'ALL') === activeFilter);
        });
        if (typeof updateSegmentedSlider === 'function') {
            updateSegmentedSlider(dictFilterBar, !!(options && options.animateSlider));
        }
    }

    grid.innerHTML = '';

    const tier = (window.ToyPermissions && typeof window.ToyPermissions.getTier === 'function')
        ? window.ToyPermissions.getTier()
        : 0;
    const hasSharedAndFollowed = (window.ToyPermissions && window.ToyPermissions.isFollowing && window.ToyPermissions.hasShared);

    const unlockedDictTitles = [];
    const activeDictLvl = window.currentExamLevel || 'cet4';
    manifestList.forEach((item, idx) => {
        if (!item || item.isWrittenOnly || item.dictationCount === 0 || item.examId === '2024_12_cet4_set3') return;
        const title = item.title;
        const yearMatch = title.match(/(\d{4})年/);
        const y = yearMatch ? parseInt(yearMatch[1]) : (item.year || 0);
        const b = item.book || (title.match(/真题(\d+)听力/) ? parseInt(title.match(/真题(\d+)听力/)[1]) : (item.year || 0));

        if (activeFilter === '2021-2026' && !(y >= 2021 && y <= 2026)) return;
        if (activeFilter === '2015-2020' && !(y >= 2015 && y <= 2020)) return;
        if (activeFilter === '2008-2014' && !(y >= 2008 && y <= 2014)) return;
        if (activeFilter === 'ielts_18_21' && !(b >= 18 && b <= 21)) return;
        if (activeFilter === 'ielts_14_17' && !(b >= 14 && b <= 17)) return;
        if (activeFilter === 'ielts_10_13' && !(b >= 10 && b <= 13)) return;
        if (activeFilter === 'ielts_4_9' && !(b >= 4 && b <= 9)) return;

        const isDone = window.completedExams && window.completedExams[title];
        const curLevel = window.currentExamLevel || 'cet4';
        const isCharged = !!(window.ToyPermissions && (window.ToyPermissions.isCharged || window.ToyPermissions.isAuthor));
        const hasTrackUnlocked = !!(window.ToyPermissions && window.ToyPermissions.hasUnlockedTrack(curLevel));
        let statusText = '未练习';
        let isCompleted = false;
        let isLocked = (idx > 0 && !isCharged);

        const totalCount = item.dictationCount || ((window.CLOZE_EXAMS_MAP && window.CLOZE_EXAMS_MAP[title]) ? window.CLOZE_EXAMS_MAP[title].length : 70);

        if (isLocked) {
            statusText = '包月充电解锁';
        } else if (idx === 0) {
            const doneDict = isDone && isDone.dictationCompleted ? Object.keys(isDone.dictationCompleted).length : 0;
            if (isCharged) {
                if (doneDict > 0) {
                    statusText = doneDict >= totalCount ? '已满分精听 🏆' : `已练 ${doneDict}/${totalCount} 句`;
                    isCompleted = true;
                } else {
                    statusText = '未练习';
                }
            } else if (hasTrackUnlocked) {
                const part1Count = (window.ToyPermissions && typeof window.ToyPermissions._getPart1EndIndex === 'function')
                    ? (window.ToyPermissions._getPart1EndIndex(curLevel, title) + 1)
                    : 28;
                statusText = doneDict > 0 ? (doneDict >= part1Count ? 'Part 1 已练完 🏆' : `Part 1 已练 ${doneDict}/${part1Count} 句`) : 'Part 1 已解锁';
                isCompleted = doneDict > 0;
            } else {
                statusText = doneDict > 0 ? '已试做' : '免费试做 (前2句)';
                isCompleted = doneDict > 0;
            }
        } else if (isDone && isDone.dictationCompleted) {
            const doneCount = Object.keys(isDone.dictationCompleted).length;
            if (doneCount > 0) {
                statusText = doneCount >= totalCount ? '已满分精听 🏆' : `已练 ${doneCount}/${totalCount} 句`;
                isCompleted = true;
            }
        }

        const card = document.createElement('div');
        card.className = `exam-card ${isLocked ? 'is-locked-card' : ''}`;
        card.dataset.examTitle = title;
        card.innerHTML = `
            <div class="exam-card-title">${title}</div>
            <div class="exam-card-meta">
                <span class="status-tag ${isLocked ? 'locked-tag' : (isCompleted ? 'completed' : '')}">${statusText}</span>
            </div>
        `;
        if (!isLocked) {
            unlockedDictTitles.push(title);
            if (typeof window.bindCardSpeculativePrefetch === 'function') {
                window.bindCardSpeculativePrefetch(card, title, curLevel, 'dictation');
            }
        }
        card.addEventListener('contextmenu', (e) => e.preventDefault());
        card.addEventListener('click', () => {
            const currentlyLocked = window.ToyPermissions ? !window.ToyPermissions.canAccessDictation(idx, 0, curLevel, title) : false;
            if (currentlyLocked) {
                window.ToyPermissions.showUnlockModal('dictation', { examIndex: idx, level: curLevel, examTitle: title });
                return;
            }
            if (card.classList.contains('is-activating')) return;
            card.classList.add('is-activating');
            setTimeout(() => card.classList.remove('is-activating'), 1000);
            startDictationExam(title);
        });

        grid.appendChild(card);
    });
    if (unlockedDictTitles.length > 0 && typeof window.scheduleLobbyTopPrefetch === 'function') {
        window.scheduleLobbyTopPrefetch(unlockedDictTitles, activeDictLvl, 'dictation');
    }
}

window.updateDictationLobbyGridState = function(filter) {
    const dFilter = filter || window.currentDictationFilter || 'ALL';
    renderDictationLobbyGrid(dFilter);
};

// 2. Start Dictation Exam
let _dictStartSeqId = 0;

async function startDictationExam(title, initialIndex = 0) {
    if (!title || typeof title !== 'string') return;
    const myStartSeq = ++_dictStartSeqId;
    const navSeq = window._navActionSeqId || 0;

    let meta = (typeof findExamMeta === 'function') ? findExamMeta(title) : null;
    let level = meta ? meta.level : null;
    if (!level) {
        if (title.includes('雅思') || title.toLowerCase().includes('ielts')) level = 'ielts';
        else if (title.includes('高考')) level = 'gaokao';
        else if (title.includes('六级')) level = 'cet6';
        else if (title.includes('四级')) level = 'cet4';
        else level = window.currentExamLevel || 'cet4';
    }
    window.currentExamLevel = level;

    const manifestList = (typeof getActiveExamManifest === 'function') ? getActiveExamManifest(level) : [];
    const examIdx = manifestList.findIndex(m => m.title === title || m.examId === title);
    const safeExamIdx = examIdx >= 0 ? examIdx : 0;
    if (window.ToyPermissions && !window.ToyPermissions.canAccessDictation(safeExamIdx, 0, level, title)) {
        if (typeof window.ToyPermissions.shouldAwaitInitialSync === 'function' && window.ToyPermissions.shouldAwaitInitialSync()) {
            await window.ToyPermissions.ensureSynced(1200);
        }
        if (!window.ToyPermissions.canAccessDictation(safeExamIdx, 0, level, title)) {
            window.ToyPermissions.showUnlockModal('dictation', { examIndex: safeExamIdx, sentenceIndex: 0, level: level, examTitle: title });
            return;
        }
    }

    // Stop any previous exam's audio or auto-advance timers before awaiting network
    if (typeof clearDictAutoAdvance === 'function') clearDictAutoAdvance();
    if (window.DictAudioEngine && typeof window.DictAudioEngine.stop === 'function') {
        window.DictAudioEngine.stop(false);
    }

    if (typeof ensureExamDataLoaded === 'function') {
        const loaded = await ensureExamDataLoaded(title, level, 'dictation');
        if (!loaded || myStartSeq !== _dictStartSeqId || (window._navActionSeqId || 0) !== navSeq) return;
    }

    let sents = (window.CLOZE_EXAMS_MAP && window.CLOZE_EXAMS_MAP[title]) ? window.CLOZE_EXAMS_MAP[title] : [];
    if (typeof window.deduplicateDictationSentences === 'function') {
        sents = window.deduplicateDictationSentences(sents);
        if (window.CLOZE_EXAMS_MAP) window.CLOZE_EXAMS_MAP[title] = sents;
    }

    if (!sents || sents.length === 0) {
        if (typeof showToyToast === 'function') {
            showToyToast('ℹ️ 该套真题与同场次共用听力，请练习第一/二套');
        }
        return;
    }

    currentDictExamTitle = title;
    window.currentDictExamTitle = title;
    window._isDailyListening = false;
    window._currentDailyDay = 0;
    currentDictSentences = sents;
    currentDictIndex = Math.max(0, Math.min(initialIndex, sents.length - 1));
    lastRenderedSentIdx = -1;
    currentSentenceChosenIndices = null;
    window.currentSentenceSolvedTokens = {};
    dictSkeletonModeActive = false;
    dictAnswerModeActive = false;
    dictationStreak = 0;
    isDictZhVisible = false;

    // Load Audio Source with Server HTTPS + Local Fallback
    const audioPlayer = document.getElementById('dictation-audio-player');
    if (audioPlayer) {
        const PRIMARY_BASE = (window.EXAM_OSS_CONFIG && window.EXAM_OSS_CONFIG.baseUrl)
            ? window.EXAM_OSS_CONFIG.baseUrl.replace(/\/$/, '') + '/'
            : 'https://bilibilitoyassets.top/';
        const BACKUP_BASE = (window.EXAM_OSS_CONFIG && window.EXAM_OSS_CONFIG.backupUrl)
            ? window.EXAM_OSS_CONFIG.backupUrl.replace(/\/$/, '') + '/'
            : 'https://bilibilitoyassets.top/';

        let examId = meta ? meta.examId : '';
        if (!examId && level === 'ielts') {
            const m = title.match(/(\d+).*?Test\s*(\d+)/i);
            if (m) examId = `ielts_${m[1]}_test${m[2]}`;
        }
        if (!examId) {
            examId = (window.EXAM_ID_MAP && window.EXAM_ID_MAP[title]) || title;
        }
        const cleanTitleNoLevel = title.replace('六级', '').replace('四级', '');
        const titleWithoutSet = title.replace(/\s*（第[一二三123]套\s*）|\s*\(第[一二三123]套\s*\)/g, '');
        const cleanNoLevelNoSet = cleanTitleNoLevel.replace(/\s*（第[一二三123]套\s*）|\s*\(第[一二三123]套\s*\)/g, '');
        
        let rawCandidates = [];
        if (level === 'cet4') {
            rawCandidates = [
                `${PRIMARY_BASE}cet4/audios/${encodeURIComponent(title)}.mp3`,
                `${PRIMARY_BASE}cet4/audios/${encodeURIComponent(titleWithoutSet)}.mp3`,
                `${PRIMARY_BASE}cet4/audios/${encodeURIComponent(cleanTitleNoLevel)}.mp3`,
                `${PRIMARY_BASE}cet4/audios/${encodeURIComponent(cleanNoLevelNoSet)}.mp3`,
                `${PRIMARY_BASE}cet4/audios/${encodeURIComponent(examId)}.mp3`,
                `${BACKUP_BASE}cet4/audios/${encodeURIComponent(title)}.mp3`,
                `${BACKUP_BASE}cet4/audios/${encodeURIComponent(titleWithoutSet)}.mp3`,
                `bucket_dist/cet4/audios/${title}.mp3`,
                `bucket_dist/cet4/audios/${titleWithoutSet}.mp3`,
                `bucket_dist/cet4/audios/${cleanTitleNoLevel}.mp3`
            ];
        } else if (level === 'gaokao') {
            rawCandidates = [
                `${PRIMARY_BASE}gaokao/audios/${encodeURIComponent(title)}.mp3`,
                `${PRIMARY_BASE}gaokao/audios/${encodeURIComponent(cleanTitleNoLevel)}.mp3`,
                `${PRIMARY_BASE}gaokao/audios/${encodeURIComponent(examId)}.mp3`,
                `${BACKUP_BASE}gaokao/audios/${encodeURIComponent(title)}.mp3`,
                `${BACKUP_BASE}gaokao/audios/${encodeURIComponent(cleanTitleNoLevel)}.mp3`,
                `bucket_dist/gaokao/audios/${title}.mp3`,
                `bucket_dist/gaokao/audios/${cleanTitleNoLevel}.mp3`,
                `bucket_dist/gaokao/audios/${examId}.mp3`
            ];
        } else if (level === 'ielts') {
            const rawFileBase = title.replace(/\s+/g, '').replace('Test', 'test');
            rawCandidates = [
                `${PRIMARY_BASE}ielts/audios/${examId}.mp3`,
                `${PRIMARY_BASE}ielts/audios/${encodeURIComponent(title)}.mp3`,
                `${PRIMARY_BASE}ielts/audios/${encodeURIComponent(rawFileBase)}.mp3`,
                `${BACKUP_BASE}ielts/audios/${examId}.mp3`,
                `${BACKUP_BASE}ielts/audios/${encodeURIComponent(title)}.mp3`,
                `${BACKUP_BASE}ielts/audios/${encodeURIComponent(rawFileBase)}.mp3`,
                `bucket_dist/ielts/audios/${examId}.mp3`,
                `bucket_dist/ielts/audios/${title}.mp3`,
                `bucket_dist/ielts/audios/${rawFileBase}.mp3`
            ];
        } else {
            rawCandidates = [
                `${PRIMARY_BASE}cet6/audios/${encodeURIComponent(title)}.mp3`,
                `${PRIMARY_BASE}cet6/audios/${encodeURIComponent(titleWithoutSet)}.mp3`,
                `${PRIMARY_BASE}cet6/audios/${encodeURIComponent(cleanTitleNoLevel)}.mp3`,
                `${PRIMARY_BASE}cet6/audios/${encodeURIComponent(cleanNoLevelNoSet)}.mp3`,
                `${PRIMARY_BASE}cet6/audios/${encodeURIComponent(cleanTitleNoLevel.replace('听力', '真题'))}.mp3`,
                `${PRIMARY_BASE}cet6/audios/${encodeURIComponent(cleanTitleNoLevel.replace('真题', '听力'))}.mp3`,
                `${PRIMARY_BASE}cet6/audios/${encodeURIComponent(examId)}.mp3`,
                `${BACKUP_BASE}cet6/audios/${encodeURIComponent(title)}.mp3`,
                `${BACKUP_BASE}cet6/audios/${encodeURIComponent(cleanTitleNoLevel)}.mp3`,
                `bucket_dist/cet6/audios/${title}.mp3`,
                `bucket_dist/cet6/audios/${cleanTitleNoLevel}.mp3`
            ];
        }
        // Deduplicate candidates so fallback never retries identical URLs
        const candidates = Array.from(new Set(rawCandidates));

        audioPlayer.onerror = null;
        audioPlayer.preload = 'metadata';
        audioPlayer.playbackRate = dictPlaybackRate;

        // Reset audio engine to active exam in on-demand streaming mode with candidates
        if (window.DictAudioEngine) {
            await window.DictAudioEngine.resetCurrentExam(title, candidates, level);
            if (myStartSeq !== _dictStartSeqId) return;
        }
    }

    const btnConfig = document.getElementById('btn-dict-audio-config');
    if (btnConfig) {
        btnConfig.classList.add('is-hidden');
        btnConfig.style.display = 'none';
    }

    const heroStageInit = document.querySelector('.dict-hero-stage');
    if (heroStageInit && heroStageInit.classList) {
        heroStageInit.classList.remove('sentence-anim-forward', 'sentence-anim-backward');
    }
    const clozeCardInit = document.getElementById('dict-cloze-card');
    if (clozeCardInit && clozeCardInit.classList) {
        clozeCardInit.classList.remove('swipe-slide-left', 'swipe-slide-right');
    }

    switchView('dictation-arena');
    renderDictationSentence(currentDictIndex, { isArenaEntry: true });
}

// 2.5 Start Daily Dictation
async function startDailyDictation(dayNum, initialIndex = 0) {
    const dayIdx = dayNum - 1;
    if (window.ToyPermissions && !window.ToyPermissions.canAccessDaily(dayIdx, initialIndex)) {
        if (typeof window.ToyPermissions.shouldAwaitInitialSync === 'function' && window.ToyPermissions.shouldAwaitInitialSync()) {
            await window.ToyPermissions.ensureSynced(1200);
        }
        if (!window.ToyPermissions.canAccessDaily(dayIdx, initialIndex)) {
            window.ToyPermissions.showUnlockModal('daily', { examIndex: dayIdx, sentenceIndex: initialIndex, dayNum: dayNum, level: 'daily' });
            return;
        }
    }

    const myStartSeq = ++_dictStartSeqId;
    const navSeq = window._navActionSeqId || 0;
    if (typeof clearDictAutoAdvance === 'function') clearDictAutoAdvance();
    if (window.DictAudioEngine && typeof window.DictAudioEngine.stop === 'function') {
        window.DictAudioEngine.stop(false);
    }

    const title = `每日英语听力（第五期）Day ${String(dayNum).padStart(2, '0')}`;

    let data = null;
    // ⚡ 0. Check bundled in-memory dataset first (0ms latency, 100% offline & instant)
    if (window.DAILY_LISTENING_ISSUE5_DATA && window.DAILY_LISTENING_ISSUE5_DATA[dayNum]) {
        data = { dictation: window.DAILY_LISTENING_ISSUE5_DATA[dayNum] };
    }

    // ⚡ 1. Check in-memory and permanent local IndexedDB cache (0-CDN repeat egress)
    const curVer = window.TOY_DATA_VERSION || 'v2.4';
    const dailyCacheKey = `toy_daily_${curVer}_issue5_day${dayNum}`;
    const legacyDailyCacheKey = `toy_daily_issue5_day${dayNum}`;

    if (!data && window.CLOZE_EXAMS_MAP && window.CLOZE_EXAMS_MAP[title]) {
        data = { dictation: window.CLOZE_EXAMS_MAP[title] };
    }

    if (!data && window.ToyAudioCacheDB && typeof window.ToyAudioCacheDB.getExamJson === 'function') {
        try {
            data = await window.ToyAudioCacheDB.getExamJson(dailyCacheKey) 
                || await window.ToyAudioCacheDB.getExamJson(legacyDailyCacheKey);
        } catch(e) {}
    }

    if (!data) {
        try {
            if (window.ToySecurity && typeof window.ToySecurity.getLocalExamJson === 'function') {
                data = window.ToySecurity.getLocalExamJson(dailyCacheKey) || window.ToySecurity.getLocalExamJson(legacyDailyCacheKey);
            } else {
                const rawStored = window.__toyLS.getItem(dailyCacheKey) || window.__toyLS.getItem(legacyDailyCacheKey);
                if (rawStored) data = JSON.parse(rawStored);
            }
        } catch(e) {}
    }

    if (!data) {
        // Load JSON data for this day from server
        const vTag = '?v=' + encodeURIComponent(curVer) + '_' + Date.now();
        const jsonUrl = `bucket_dist/daily/issue5/jsons/day${dayNum}.json`;
        const SERVER_BASE = (window.EXAM_OSS_CONFIG && window.EXAM_OSS_CONFIG.baseUrl)
            ? window.EXAM_OSS_CONFIG.baseUrl.replace(/\/$/, '') + '/'
            : 'https://bilibilitoyassets.top/';
        const serverJsonUrl = `${SERVER_BASE}daily/issue5/jsons/day${dayNum}.json${vTag}`;

        try {
            const res = await fetch(jsonUrl);
            if (res.ok) {
                const parsed = await res.json();
                if (parsed && Array.isArray(parsed.dictation) && parsed.dictation.length > 0) data = parsed;
            }
        } catch(e) {}

        if (!data) {
            try {
                const res = await fetch(serverJsonUrl);
                if (res.ok) {
                    const parsed = await res.json();
                    if (parsed && Array.isArray(parsed.dictation) && parsed.dictation.length > 0) data = parsed;
                }
            } catch(e) {}
        }

        if (myStartSeq !== _dictStartSeqId) return;

        if (data && data.dictation) {
            // Save to IndexedDB permanently (Encrypted TEJ1: payload); fallback to localStorage only if IDB unavailable
            let savedIdb = false;
            if (window.ToyAudioCacheDB && typeof window.ToyAudioCacheDB.saveExamJson === 'function') {
                try {
                    savedIdb = await window.ToyAudioCacheDB.saveExamJson(dailyCacheKey, data);
                } catch(e) {}
            }
            if (!savedIdb) {
                if (window.ToySecurity && typeof window.ToySecurity.setLocalExamJson === 'function') {
                    window.ToySecurity.setLocalExamJson(dailyCacheKey, data);
                } else {
                    try { window.__toyLS.setItem(dailyCacheKey, JSON.stringify(data)); } catch(e) {}
                }
            }
        }
    }

    if (myStartSeq !== _dictStartSeqId || (window._navActionSeqId || 0) !== navSeq) return;
    if (!data || !data.dictation || !Array.isArray(data.dictation) || data.dictation.length === 0) {
        if (typeof showToyToast === 'function') showToyToast('⚠️ 听力数据加载失败，请检查网络后重试');
        return;
    }

    window.currentExamLevel = 'daily';
    currentDictExamTitle = title;
    window.currentDictExamTitle = title;
    window._isDailyListening = true;
    window._currentDailyDay = dayNum;
    lastRenderedSentIdx = -1;
    currentSentenceChosenIndices = null;
    window.currentSentenceSolvedTokens = {};
    dictSkeletonModeActive = false;
    dictAnswerModeActive = false;

    if (!window.CLOZE_EXAMS_MAP) window.CLOZE_EXAMS_MAP = {};
    let sents = data.dictation;
    if (typeof window.deduplicateDictationSentences === 'function') {
        sents = window.deduplicateDictationSentences(sents);
    }
    window.CLOZE_EXAMS_MAP[title] = sents;
    currentDictSentences = sents;
    currentDictIndex = Math.max(0, Math.min(initialIndex, sents.length - 1));
    dictationStreak = 0;
    isDictZhVisible = false;

    // Show top-right audio settings button in arena
    const btnConfig = document.getElementById('btn-dict-audio-config');
    if (btnConfig) {
        btnConfig.classList.remove('is-hidden');
        btnConfig.style.removeProperty('display');
    }
    updateDailyAudioSettingsUI();

    const heroStageInit = document.querySelector('.dict-hero-stage');
    if (heroStageInit && heroStageInit.classList) {
        heroStageInit.classList.remove('sentence-anim-forward', 'sentence-anim-backward');
    }
    const clozeCardInit = document.getElementById('dict-cloze-card');
    if (clozeCardInit && clozeCardInit.classList) {
        clozeCardInit.classList.remove('swipe-slide-left', 'swipe-slide-right');
    }

    switchView('dictation-arena');
    renderDictationSentence(currentDictIndex, { isArenaEntry: true });
}
window.startDailyDictation = startDailyDictation;

function renderDailyLobbyGrid() {
    const grid = document.getElementById('daily-exam-grid');
    if (!grid) return;
    grid.innerHTML = '';

    const hasDailyUnlocked = !!(window.ToyPermissions && window.ToyPermissions.hasUnlockedTrack('daily'));

    const manifest = window.DAILY_LISTENING_ISSUE5_MANIFEST || [];
    manifest.forEach((item, idx) => {
        const dayNum = item.day;
        const title = item.title;
        const isDone = window.completedExams && window.completedExams[title];
        const doneCount = (isDone && isDone.dictationCompleted) ? Object.keys(isDone.dictationCompleted).length : 0;
        const isCharged = !!(window.ToyPermissions && (window.ToyPermissions.isCharged || window.ToyPermissions.isAuthor));
        let statusText = '未练习';
        let isCompleted = false;
        let isLocked = (idx > 0 && !isCharged);

        if (isLocked) {
            statusText = '包月充电解锁';
        } else if (idx === 0) {
            // Day 01
            if (hasDailyUnlocked || isCharged) {
                if (doneCount > 0) {
                    statusText = doneCount >= item.sentenceCount ? '已满分精听 🏆' : `已练 ${doneCount}/${item.sentenceCount} 句`;
                    isCompleted = true;
                } else {
                    statusText = '未练习';
                }
            } else {
                statusText = doneCount > 0 ? `已试做 ${doneCount}/2 句` : '免费试做 (前2句)';
                isCompleted = doneCount > 0;
            }
        } else if (isDone && isDone.dictationCompleted) {
            if (doneCount > 0) {
                statusText = doneCount >= item.sentenceCount ? '已满分精听 🏆' : `已练 ${doneCount}/${item.sentenceCount} 句`;
                isCompleted = true;
            }
        }

        const card = document.createElement('div');
        card.className = `exam-card ${isLocked ? 'is-locked-card' : ''}`;
        card.innerHTML = `
            <div class="exam-card-title">${item.dayTitle}</div>
            <div class="exam-card-meta">
                <span class="status-tag ${isLocked ? 'locked-tag' : (isCompleted ? 'completed' : '')}">${statusText}</span>
            </div>
        `;
        card.addEventListener('click', () => {
            const currentlyLocked = window.ToyPermissions ? !window.ToyPermissions.canAccessDaily(idx, 0) : false;
            if (currentlyLocked) {
                window.ToyPermissions.showUnlockModal('daily', { examIndex: idx, dayNum: dayNum, level: 'daily' });
                return;
            }
            if (card.classList.contains('is-activating')) return;
            card.classList.add('is-activating');
            const statusTag = card.querySelector('.status-tag');
            const oldStatusText = statusTag ? statusTag.textContent : '';
            if (statusTag) {
                statusTag.textContent = '进入中...';
            }
            setTimeout(() => {
                card.classList.remove('is-activating');
                if (statusTag && statusTag.textContent === '进入中...') {
                    statusTag.textContent = oldStatusText;
                }
            }, 1000);
            startDailyDictation(dayNum);
        });

        grid.appendChild(card);
    });
}
window.renderDailyLobbyGrid = renderDailyLobbyGrid;

// (Daily listening audio playback & pre-cache engine are modularized in js/dict_audio_engine.js)


// Lobby Year Filter Chips
function initDictationYearFilterBar(level) {
    const dictFilterBar = document.getElementById('dictation-year-filter-bar');
    if (!dictFilterBar) return;
    const curLevel = level || window.currentExamLevel || 'cet4';
    const isIelts = (curLevel === 'ielts');
    const isGaokao = (curLevel === 'gaokao');

    const hasIeltsChips = !!dictFilterBar.querySelector('.chip-year[data-range="ielts_18_21"]');
    if (isIelts && !hasIeltsChips) {
        dictFilterBar.innerHTML = `
            <span class="chip-year active" data-range="ALL">全部真题</span>
            <span class="chip-year" data-range="ielts_18_21">剑18–21</span>
            <span class="chip-year" data-range="ielts_14_17">剑14–17</span>
            <span class="chip-year" data-range="ielts_10_13">剑10–13</span>
            <span class="chip-year" data-range="ielts_4_9">剑4–9</span>
        `;
    } else if (!isIelts && (hasIeltsChips || !dictFilterBar.querySelector('.chip-year[data-range="2021-2026"]'))) {
        dictFilterBar.innerHTML = `
            <span class="chip-year active" data-range="ALL">全部年份</span>
            <span class="chip-year" data-range="2021-2026">2021–2026年</span>
            <span class="chip-year" data-range="2015-2020">2015–2020年</span>
            <span class="chip-year" data-range="2008-2014" style="display: ${isGaokao ? '' : 'none'};">2008–2014年</span>
        `;
    } else if (!isIelts) {
        const chip0814 = dictFilterBar.querySelector('.chip-year[data-range="2008-2014"]');
        if (chip0814) chip0814.style.display = isGaokao ? '' : 'none';
    }

    const chips = dictFilterBar.querySelectorAll('.chip-year');
    chips.forEach(chip => {
        const clone = chip.cloneNode(true);
        chip.parentNode.replaceChild(clone, chip);
        clone.addEventListener('click', () => {
            const nextRange = clone.dataset.range || 'ALL';
            const changed = (window.currentDictationFilter !== nextRange) || !clone.classList.contains('active');
            dictFilterBar.querySelectorAll('.chip-year').forEach(c => c.classList.remove('active'));
            clone.classList.add('active');
            window.currentDictationFilter = nextRange;
            renderDictationLobbyGrid(window.currentDictationFilter, { animateSlider: true });
            if (changed && typeof window.triggerExamGridFilterTransition === 'function') {
                window.triggerExamGridFilterTransition('dictation-exam-grid');
            }
        });
    });

    if (typeof updateSegmentedSlider === 'function') {
        updateSegmentedSlider(dictFilterBar, false);
    }
    if (window.enableHorizontalDragScroll) {
        window.enableHorizontalDragScroll(dictFilterBar);
    }
}
window.initDictationYearFilterBar = initDictationYearFilterBar;
window.renderDictationLobbyGrid = renderDictationLobbyGrid;
window.startDictationExam = startDictationExam;
window.startDailyDictation = startDailyDictation;
window.renderDailyLobbyGrid = renderDailyLobbyGrid;


/* === js/dictation_quiz.js === */
// ==========================================================================
// Dictation Sentence Renderer, Cloze Input Engine & Auto-Advance (js/dictation_quiz.js)
// ==========================================================================

// 3. Render Sentence & Smart Cloze Blanks
function renderDictationSentence(index, options = {}) {
    const isDaily = (typeof isDailyListeningActive === 'function' && isDailyListeningActive()) || !!window._isDailyListening;
    if (isDaily) {
        const dayIdx = (typeof window._currentDailyDay === 'number' && window._currentDailyDay > 0) ? (window._currentDailyDay - 1) : 0;
        if (window.ToyPermissions && !window.ToyPermissions.canAccessDaily(dayIdx, index)) {
            if (window.DictAudioEngine && typeof window.DictAudioEngine.pauseSentenceAudio === 'function') {
                window.DictAudioEngine.pauseSentenceAudio();
            }
            window.ToyPermissions.showUnlockModal('daily', { examIndex: dayIdx, sentenceIndex: index, dayNum: window._currentDailyDay || (dayIdx + 1), level: 'daily' });
            return;
        }
    } else {
        const curLvl = getActiveDictExamLevel();
        window.currentExamLevel = curLvl;
        const manifestList = (typeof getActiveExamManifest === 'function') ? getActiveExamManifest(curLvl) : [];
        const examIdx = manifestList.findIndex(m => m.title === currentDictExamTitle || m.examId === currentDictExamTitle);
        if (window.ToyPermissions && !window.ToyPermissions.canAccessDictation(examIdx >= 0 ? examIdx : 0, index, curLvl, currentDictExamTitle)) {
            if (window.DictAudioEngine && typeof window.DictAudioEngine.pauseSentenceAudio === 'function') {
                window.DictAudioEngine.pauseSentenceAudio();
            }
            window.ToyPermissions.showUnlockModal('dictation', { examIndex: examIdx >= 0 ? examIdx : 0, sentenceIndex: index, level: curLvl, examTitle: currentDictExamTitle });
            return;
        }
    }

    const isArenaEntry = !!(options && options.isArenaEntry);
    currentDictIndex = index;
    if (typeof hideContextualPopover === 'function') hideContextualPopover();
    if (typeof window.closeEnterNextHint === 'function') window.closeEnterNextHint(false);
    if (!options.preserveScroll && !isArenaEntry) {
        try {
            window.scrollTo({ top: 0, behavior: 'instant' });
        } catch (_) {
            try { window.scrollTo(0, 0); } catch (e) {}
        }
    }

    // Trigger smooth slide transition (never on initial arena entry, and auto-cleaned so it never replays on display:flex)
    const heroStage = document.querySelector('.dict-hero-stage');
    if (heroStage && !isArenaEntry && lastRenderedSentIdx !== -1 && lastRenderedSentIdx !== index && !options.preserveAudio && !options.preserveScroll) {
        heroStage.classList.remove('sentence-anim-forward', 'sentence-anim-backward');
        void heroStage.offsetWidth; // trigger reflow
        if (index > lastRenderedSentIdx) {
            heroStage.classList.add('sentence-anim-forward');
        } else {
            heroStage.classList.add('sentence-anim-backward');
        }
        if (typeof heroStage.addEventListener === 'function' && !heroStage._sentAnimEndBound) {
            heroStage._sentAnimEndBound = true;
            heroStage.addEventListener('animationend', (ev) => {
                if (!ev || ev.target === heroStage) {
                    heroStage.classList.remove('sentence-anim-forward', 'sentence-anim-backward');
                }
            });
        }
    }

    if (!currentDictSentences || currentDictSentences.length === 0) return;
    index = Math.max(0, Math.min(index, currentDictSentences.length - 1));
    const sent = currentDictSentences[index];
    if (!sent) return;

    // Pause any playing audio from previous sentence & release memory Blob URL (only when NOT preserving audio)
    if (!options.preserveAudio) {
        if (currentDailyTimeout) {
            clearTimeout(currentDailyTimeout);
            currentDailyTimeout = null;
        }
        removePauseBreathingToast();
        if (window.DictAudioEngine) {
            DictAudioEngine.playToken++;
            DictAudioEngine.isPlaying = false;
            DictAudioEngine.isBuffering = false;
        }
        updateZenAudioPlayState(false);

        const audioPlayer = document.getElementById('dictation-audio-player');
        if (audioPlayer) {
            if (!audioPlayer.paused) {
                try { audioPlayer.pause(); } catch(e) {}
            }
            if (isDaily) {
                audioPlayer.currentTime = 0;
            }
        }
        if (window.DictAudioEngine) {
            if (window.DictAudioEngine.activeBlobUrl) {
                try { URL.revokeObjectURL(window.DictAudioEngine.activeBlobUrl); } catch(e) {}
                window.DictAudioEngine.activeBlobUrl = null;
                window.DictAudioEngine.currentBlobCacheKey = null;
            }
            if (window.DictAudioEngine.activeDailyBlobUrl) {
                try { URL.revokeObjectURL(window.DictAudioEngine.activeDailyBlobUrl); } catch(e) {}
                window.DictAudioEngine.activeDailyBlobUrl = null;
                window.DictAudioEngine.activeDailyBlobKey = null;
            }
            window.DictAudioEngine.currentDailyKey = null;
        }
        clearDictAudioLoop();
    }

    // Update Difficulty Mode button text & styling
    updateDictModeButtonUI();

    // Top badges
    const seqBadge = document.getElementById('dict-seq-val');
    const secBadge = document.getElementById('dict-section-badge');
    const zhBox = document.getElementById('dict-zh-box');
    const btnZhHint = document.getElementById('btn-dict-hint-zh');
    const btnConfig = document.getElementById('btn-dict-audio-config');

    if (btnConfig) {
        if (isDaily) {
            btnConfig.classList.remove('is-hidden');
            btnConfig.style.removeProperty('display');
            updateDailyAudioSettingsUI();
        } else {
            btnConfig.classList.add('is-hidden');
            btnConfig.style.display = 'none';
        }
    }

    if (seqBadge) seqBadge.textContent = `${String(index + 1).padStart(2, '0')} / ${String(currentDictSentences.length).padStart(2, '0')}`;
    if (secBadge) {
        if (isDaily) {
            secBadge.textContent = `Day ${String(window._currentDailyDay || 1).padStart(2, '0')} · 第 ${index + 1} 句`;
        } else {
            secBadge.textContent = sent.group || sent.sec || ((window.currentExamLevel === 'cet6') ? 'Conversations 1' : 'News Report 1');
        }
    }

    // Cleaned Chinese text with proper punctuation
    let cleanZh = (sent.zh || '').trim().replace(/[,，、]$/, '。');
    if (cleanZh && !/[。？！…]$/.test(cleanZh)) cleanZh += '。';

    if (zhBox) {
        const canUseB = (window.ToyPermissions && typeof window.ToyPermissions.canUseBilingualMode === 'function')
            ? window.ToyPermissions.canUseBilingualMode()
            : false;
        zhBox.textContent = cleanZh || '原声听力例句精读';
        zhBox.classList.toggle('show', !!((canUseB && window.showDictBilingual) || dictAnswerModeActive));
    }
    if (!options.keepSkeleton && !options.keepModes) {
        dictSkeletonModeActive = false;
        dictAnswerModeActive = false;
    }

    const btnHintFirst = document.getElementById('btn-dict-hint-first');
    if (btnHintFirst) {
        btnHintFirst.innerHTML = dictSkeletonModeActive ? '💡 关闭' : '💡 提示';
        btnHintFirst.classList.toggle('active-toggle', !!dictSkeletonModeActive);
    }

    const btnRevealAnswer = document.getElementById('btn-dict-reveal-answer');
    if (btnRevealAnswer) {
        btnRevealAnswer.innerHTML = dictAnswerModeActive ? '📖 关闭' : '📖 答案';
        btnRevealAnswer.classList.toggle('active-toggle', !!dictAnswerModeActive);
    }

    if (typeof syncDictKbToolButtonsState === 'function') {
        syncDictKbToolButtonsState();
    }

    // Check if whole sentence was already fully completed previously
    const isAlreadyDone = !!window.completedExams?.[currentDictExamTitle]?.dictationCompleted?.[index];

    // Select Smart Target Blank Words (Proportional ~30% in basic, ~60% in advanced)
    const rawText = sent.text || '';
    if (index !== lastRenderedSentIdx || !options.keepModes || !currentSentenceChosenIndices) {
        lastRenderedSentIdx = index;
        currentSentenceChosenIndices = selectSmartBlankTokenIndices(rawText, dictDifficultyMode, true);
        if (!options.keepModes) {
            // Reset temporary partial inputs when navigating across different sentences
            if (!window.currentSentenceSolvedTokens) window.currentSentenceSolvedTokens = {};
            window.currentSentenceSolvedTokens[index] = new Set();
        }
    }
    const chosenIndices = currentSentenceChosenIndices;

    // Word completion state
    if (!window.currentSentenceSolvedTokens) window.currentSentenceSolvedTokens = {};
    if (!window.currentSentenceSolvedTokens[index]) window.currentSentenceSolvedTokens[index] = new Set();
    const sentenceDoneSet = window.currentSentenceSolvedTokens[index];
    const existingInputValues = {};

    const clozeCard = document.getElementById('dict-cloze-card');
    if (clozeCard) {
        if (options && (options.slideDirection === 'left' || options.slideDirection === 'right')) {
            if (clozeCard._swipeCleanTimer) {
                clearTimeout(clozeCard._swipeCleanTimer);
                clozeCard._swipeCleanTimer = null;
            }
            clozeCard.classList.remove('swipe-slide-left', 'swipe-slide-right');
            void clozeCard.offsetWidth;
            clozeCard.classList.add(options.slideDirection === 'left' ? 'swipe-slide-left' : 'swipe-slide-right');
            clozeCard._swipeCleanTimer = setTimeout(() => {
                clozeCard.classList.remove('swipe-slide-left', 'swipe-slide-right');
                clozeCard._swipeCleanTimer = null;
            }, 230);
        }

        if (options.keepModes) {
            clozeCard.querySelectorAll('.cloze-word-done, .cloze-input[disabled]').forEach(el => {
                const tIdx = parseInt(el.dataset.tokenIdx);
                if (!isNaN(tIdx)) sentenceDoneSet.add(tIdx);
            });
            clozeCard.querySelectorAll('.cloze-input:not([disabled])').forEach(inp => {
                const tIdx = parseInt(inp.dataset.tokenIdx);
                if (!isNaN(tIdx) && inp.value) {
                    existingInputValues[tIdx] = inp.value;
                }
            });
        }

        clozeCard.innerHTML = '';
        const tokens = rawText.split(/([a-zA-Z]+(?:[\'\-][a-zA-Z]+)*)/);

        tokens.forEach((token, idx) => {
            const lower = token.toLowerCase();
            if (chosenIndices.has(idx)) {
                // 🌟 Detect and bind trailing punctuation to prevent orphan punctuation or gaps
                let trailingPunct = '';
                if (idx + 1 < tokens.length && typeof tokens[idx + 1] === 'string') {
                    const punctMatch = tokens[idx + 1].match(/^([,\.?!;:\)\]\'\"”’—–…]+)([\s\S]*)$/);
                    if (punctMatch) {
                        trailingPunct = punctMatch[1];
                        tokens[idx + 1] = punctMatch[2]; // Consume punctuation so it won't be repeated
                    }
                }

                const isWordDone = isAlreadyDone || sentenceDoneSet.has(idx);
                if (isWordDone) {
                    const doneSpan = document.createElement('span');
                    doneSpan.className = 'cloze-word-done';
                    doneSpan.dataset.tokenIdx = String(idx);
                    doneSpan.dataset.sentIdx = String(index);
                    doneSpan.style.minWidth = `${measureClozeWordWidth(token)}px`;
                    doneSpan.style.width = 'auto';
                    doneSpan.style.whiteSpace = 'nowrap';
                    if (typeof makeTextClickable === 'function') {
                        doneSpan.innerHTML = makeTextClickable(token);
                    } else {
                        doneSpan.textContent = token;
                    }

                    if (trailingPunct) {
                        const atom = document.createElement('span');
                        atom.className = 'cloze-atom';
                        doneSpan.classList.add('cloze-has-punct');
                        atom.appendChild(doneSpan);
                        const pSpan = document.createElement('span');
                        pSpan.className = 'cloze-punct';
                        pSpan.textContent = trailingPunct;
                        atom.appendChild(pSpan);
                        clozeCard.appendChild(atom);
                    } else {
                        clozeCard.appendChild(doneSpan);
                    }
                } else {
                    const wrap = document.createElement('span');
                    wrap.className = 'cloze-input-wrap';
                    wrap.style.width = `${measureClozeWordWidth(token)}px`;

                    const input = document.createElement('input');
                    input.type = 'text';
                    input.className = 'cloze-input';
                    input.dataset.sentIdx = String(index);
                    input.dataset.tokenIdx = String(idx);
                    input.dataset.target = token;
                    input.dataset.targetLower = lower;

                    // 🌟 User-specified length limit: e.g. 6 letters allows max 8 letters (token.length + 2)
                    const maxAllowedChars = Math.max(3, token.length + 2);
                    input.maxLength = maxAllowedChars;

                    input.setAttribute('autocomplete', 'off');
                    input.setAttribute('autocorrect', 'off');
                    input.setAttribute('autocapitalize', 'none');
                    const useVirtualKb = (typeof isCustomKeyboardEnabled === 'function') ? isCustomKeyboardEnabled() : true;
                    if (useVirtualKb) {
                        input.setAttribute('inputmode', 'none'); // 'none' prevents mobile OS virtual IME popup
                    } else {
                        input.removeAttribute('inputmode'); // PC desktop: standard native input for physical keyboard
                    }
                    input.setAttribute('lang', 'en-US');

                    if (dictAnswerModeActive) {
                        input.placeholder = token;
                        input.classList.add('ghost-answer-mode');
                    } else if (dictSkeletonModeActive) {
                        if (token.length === 1) {
                            const ghostStart = document.createElement('span');
                            ghostStart.className = 'hint-ghost-start';
                            ghostStart.textContent = token[0];
                            wrap.appendChild(ghostStart);
                        } else {
                            const ghostStart = document.createElement('span');
                            ghostStart.className = 'hint-ghost-start';
                            ghostStart.textContent = token[0];
                            wrap.appendChild(ghostStart);

                            const ghostEnd = document.createElement('span');
                            ghostEnd.className = 'hint-ghost-end';
                            ghostEnd.textContent = token[token.length - 1];
                            wrap.appendChild(ghostEnd);
                        }
                    }

                    const updateValueState = () => {
                        const val = input.value || '';
                        if (val.trim().length > 0) {
                            wrap.classList.add('has-value');
                        } else {
                            wrap.classList.remove('has-value');
                        }

                        // 🌟 Dynamic Elastic Capsule ("随打随长"): accommodates maxAllowedChars with full visibility
                        const baseWidth = measureClozeWordWidth(token);
                        if (!val) {
                            wrap.style.width = `${baseWidth}px`;
                        } else {
                            const typedWidth = measureClozeWordWidth(val);
                            wrap.style.width = `${Math.max(baseWidth, typedWidth)}px`;
                        }
                    };

                    if (existingInputValues[idx]) {
                        input.value = existingInputValues[idx];
                        updateValueState();
                    }

                    const sanitizeAndProcess = () => {
                        const rawVal = String(input.value || '')
                            .replace(/[\u2018\u2019\u201B\u02BC\uFF07`]/g, "'")
                            .replace(/[\u2013\u2014\u2212\uFF0D]/g, '-');
                        let cleanVal = rawVal.replace(/[^a-zA-Z\'-]/g, '');
                        const maxLimit = input.maxLength || maxAllowedChars;
                        if (cleanVal.length > maxLimit) {
                            cleanVal = cleanVal.slice(0, maxLimit);
                        }
                        if (input.value !== cleanVal) {
                            input.value = cleanVal;
                        }
                        input._virtualCaretPos = input.value.length;
                        updateValueState();
                        handleClozeInput(input, token);
                        if (typeof updateCustomKeyboardStatus === 'function') {
                            updateCustomKeyboardStatus();
                        }
                    };

                    const moveCursorToEnd = () => {
                        try {
                            if (!input.disabled) {
                                const len = input.value.length;
                                input.setSelectionRange(len, len);
                                input._virtualCaretPos = len;
                                input._userExplicitlyAtZero = false;
                            }
                        } catch(e) {}
                    };

                    const activateBlank = (e) => {
                        if (window.isLookupMode) {
                            if ((dictAnswerModeActive || (input.value && input.value.trim())) && typeof showContextualPopover === 'function') {
                                const lookupWord = (input.value && input.value.trim()) ? input.value.trim() : (input.dataset.target || '');
                                if (lookupWord) {
                                    showContextualPopover(lookupWord, wrap);
                                }
                            }
                            return;
                        }
                        if (e && e.type === 'focus' && input._isProgrammaticFocus) {
                            return;
                        }
                        document.querySelectorAll('.cloze-input-wrap.has-focus').forEach(w => {
                            if (w !== wrap) w.classList.remove('has-focus');
                        });
                        wrap.classList.add('has-focus');
                        moveCursorToEnd();
                        if (typeof setActiveInputForCustomKeyboard === 'function') {
                            setActiveInputForCustomKeyboard(input, true);
                        }
                    };

                    input.addEventListener('focus', activateBlank);
                    input.addEventListener('pointerdown', (e) => {
                        e.stopPropagation();
                        if (window.isLookupMode) {
                            e.preventDefault();
                            activateBlank(e);
                            return;
                        }
                        activateBlank(e);
                    });
                    input.addEventListener('touchstart', (e) => {
                        e.stopPropagation();
                        activateBlank(e);
                    }, { passive: true });
                    input.addEventListener('click', (e) => {
                        e.stopPropagation();
                        activateBlank(e);
                    });
                    input.addEventListener('select', () => {
                        if (typeof input.selectionStart === 'number') {
                            input._virtualCaretPos = input.selectionStart;
                        }
                    });
                    input.addEventListener('keyup', (e) => {
                        if (typeof input.selectionStart === 'number') {
                            input._virtualCaretPos = input.selectionStart;
                            if (e.key === 'ArrowLeft' && input.selectionStart === 0) {
                                input._userExplicitlyAtZero = true;
                            } else if (input.selectionStart > 0) {
                                input._userExplicitlyAtZero = false;
                            }
                        }
                    });
                    input.addEventListener('blur', () => {
                        if (typeof isCustomKeyboardEnabled === 'function' && isCustomKeyboardEnabled() && !window.dictKeyboardCollapsed && window.activeCustomKeyboardInput === input) {
                            return;
                        }
                        wrap.classList.remove('has-focus');
                    });
                    wrap.addEventListener('pointerdown', (e) => {
                        if (window.isLookupMode) {
                            e.stopPropagation();
                            e.preventDefault();
                            activateBlank(e);
                            return;
                        }
                        if (!input.disabled) {
                            e.stopPropagation();
                            input.focus();
                            activateBlank(e);
                            moveCursorToEnd();
                        }
                    });
                    wrap.addEventListener('touchstart', (e) => {
                        if (window.isLookupMode) {
                            e.stopPropagation();
                            activateBlank(e);
                            return;
                        }
                        if (!input.disabled) {
                            e.stopPropagation();
                            input.focus();
                            activateBlank(e);
                            moveCursorToEnd();
                        }
                    }, { passive: true });
                    wrap.addEventListener('click', (e) => {
                        if (window.isLookupMode) {
                            e.stopPropagation();
                            activateBlank(e);
                            return;
                        }
                        if (!input.disabled) {
                            e.stopPropagation();
                            input.focus();
                            activateBlank(e);
                            moveCursorToEnd();
                        }
                    });
                    wrap.addEventListener('dblclick', (e) => {
                        if (!input.disabled) {
                            e.stopPropagation();
                            input.focus();
                            input.select();
                            input.setSelectionRange(0, input.value.length);
                        }
                    });
                    input.addEventListener('dblclick', (e) => {
                        e.stopPropagation();
                        input.select();
                        input.setSelectionRange(0, input.value.length);
                    });
                    input.addEventListener('beforeinput', (e) => {
                        if (e.isComposing) return;
                        if (e.data && e.data.length === 1) {
                            const normChar = e.data
                                .replace(/[\u2018\u2019\u201B\u02BC\uFF07`]/g, "'")
                                .replace(/[\u2013\u2014\u2212\uFF0D]/g, '-');
                            if (/[^a-zA-Z\'-]/.test(normChar) && normChar !== ' ') {
                                e.preventDefault();
                                return;
                            }
                            const curLen = input.value.length;
                            const selLen = (input.selectionEnd || curLen) - (input.selectionStart || curLen);
                            if ((curLen - selLen + normChar.length) > input.maxLength) {
                                e.preventDefault();
                            }
                        }
                    });
                    input.addEventListener('input', sanitizeAndProcess);
                    input.addEventListener('compositionend', sanitizeAndProcess);
                    input.addEventListener('paste', () => {
                        setTimeout(sanitizeAndProcess, 10);
                    });
                    input.addEventListener('keydown', (e) => {
                        // 🌟 0. If user is using Chinese/Pinyin IME composition, DO NOT intercept anything!
                        if (e.isComposing || e.keyCode === 229) {
                            return;
                        }

                        // 🌟 1. Ctrl+A / Cmd+A 全选当前空里的所有已输入字母
                        if ((e.ctrlKey || e.metaKey) && (e.key === 'a' || e.key === 'A')) {
                            e.preventDefault();
                            e.stopPropagation();
                            input.select();
                            input.setSelectionRange(0, input.value.length);
                            return;
                        }

                        const inputs = Array.from(document.querySelectorAll('#dict-cloze-card .cloze-input:not([disabled])'));
                        const i = inputs.indexOf(input);

                        if (e.key === ' ' || e.code === 'Space') {
                            if (token.includes(' ') && !input.value.endsWith(' ')) {
                                // Allow typing space character if target phrase contains a space
                                return;
                            }
                            e.preventDefault();
                            e.stopPropagation();
                            if (typeof window.handleCustomKeyboardNextBlank === 'function') {
                                window.handleCustomKeyboardNextBlank();
                            }
                        } else if (e.key === 'ArrowLeft') {
                            e.stopPropagation();
                            if (input.selectionStart === 0 && input.selectionEnd === 0) {
                                if (i > 0) {
                                    e.preventDefault();
                                    inputs[i - 1].focus();
                                    const prevLen = inputs[i - 1].value.length;
                                    inputs[i - 1].setSelectionRange(prevLen, prevLen);
                                    inputs[i - 1]._virtualCaretPos = prevLen;
                                    inputs[i - 1]._userExplicitlyAtZero = false;
                                    if (typeof setActiveInputForCustomKeyboard === 'function') {
                                        setActiveInputForCustomKeyboard(inputs[i - 1], true);
                                    }
                                } else {
                                    input._userExplicitlyAtZero = true;
                                }
                            }
                        } else if (e.key === 'ArrowRight') {
                            if (input.selectionEnd === input.value.length && input.selectionStart === input.value.length) {
                                if (i < inputs.length - 1) {
                                    e.preventDefault();
                                    inputs[i + 1].focus();
                                    const nextLen = inputs[i + 1].value.length;
                                    inputs[i + 1].setSelectionRange(nextLen, nextLen);
                                    inputs[i + 1]._virtualCaretPos = nextLen;
                                    inputs[i + 1]._userExplicitlyAtZero = false;
                                    if (typeof setActiveInputForCustomKeyboard === 'function') {
                                        setActiveInputForCustomKeyboard(inputs[i + 1], true);
                                    }
                                }
                            }
                        } else if (e.key === 'Backspace' && input.value.length === 0) {
                            if (i > 0) {
                                e.preventDefault();
                                inputs[i - 1].focus();
                                const prevLen = inputs[i - 1].value.length;
                                inputs[i - 1].setSelectionRange(prevLen, prevLen);
                                inputs[i - 1]._virtualCaretPos = prevLen;
                                inputs[i - 1]._userExplicitlyAtZero = false;
                                if (typeof setActiveInputForCustomKeyboard === 'function') {
                                    setActiveInputForCustomKeyboard(inputs[i - 1], true);
                                }
                            }
                        } else if (e.key === 'Enter') {
                            const nextUnsolved = inputs.slice(i + 1).find(inp => !inp.disabled);
                            if (nextUnsolved) {
                                e.preventDefault();
                                nextUnsolved.focus();
                                const nextLen = nextUnsolved.value.length;
                                try { nextUnsolved.setSelectionRange(nextLen, nextLen); } catch(err) {}
                                nextUnsolved._virtualCaretPos = nextLen;
                                nextUnsolved._userExplicitlyAtZero = false;
                                if (typeof setActiveInputForCustomKeyboard === 'function') {
                                    setActiveInputForCustomKeyboard(nextUnsolved, true);
                                }
                            } else {
                                const allUnsolved = document.querySelectorAll('#dict-cloze-card .cloze-input:not([disabled])');
                                if (allUnsolved.length <= 1) {
                                    e.preventDefault();
                                    if (typeof window.handleNextDictSentence === 'function') {
                                        window.handleNextDictSentence();
                                    } else if (typeof handleNextSentence === 'function') {
                                        handleNextSentence();
                                    }
                                }
                            }
                        }
                    });

                    wrap.appendChild(input);

                    if (trailingPunct) {
                        const atom = document.createElement('span');
                        atom.className = 'cloze-atom';
                        wrap.classList.add('cloze-has-punct');
                        atom.appendChild(wrap);
                        const pSpan = document.createElement('span');
                        pSpan.className = 'cloze-punct';
                        pSpan.textContent = trailingPunct;
                        atom.appendChild(pSpan);
                        atom.addEventListener('click', (e) => {
                            if (!input.disabled && e.target !== input) {
                                input.focus();
                                activateBlank(e);
                                moveCursorToEnd();
                            }
                        });
                        clozeCard.appendChild(atom);
                    } else {
                        clozeCard.appendChild(wrap);
                    }
                }
            } else {
                if (typeof makeTextClickable === 'function') {
                    const temp = document.createElement('span');
                    temp.innerHTML = makeTextClickable(token);
                    while (temp.firstChild) {
                        clozeCard.appendChild(temp.firstChild);
                    }
                } else {
                    clozeCard.appendChild(document.createTextNode(token));
                }
            }
        });

        // Sync capsule widths after DOM layout (and after webfont readiness) so long words like "six-year-old" never clip
        const syncAllClozeInputWidths = () => {
            const cardEl = document.getElementById('dict-cloze-card');
            if (!cardEl) return;
            cardEl.querySelectorAll('.cloze-input-wrap').forEach(w => {
                const inp = w.querySelector('.cloze-input');
                if (!inp) return;
                const targetText = inp.dataset.target || inp.placeholder || '';
                const curVal = inp.value || '';
                const baseW = measureClozeWordWidth(targetText);
                const valW = curVal ? measureClozeWordWidth(curVal) : 0;
                w.style.width = `${Math.max(baseW, valW)}px`;
            });
        };
        window.syncAllClozeInputWidths = syncAllClozeInputWidths;
        if (!window._clozeResizeWidthBound) {
            window._clozeResizeWidthBound = true;
            window.addEventListener('resize', () => {
                if (typeof window.syncAllClozeInputWidths === 'function') {
                    window.syncAllClozeInputWidths();
                }
            }, { passive: true });
            window.addEventListener('orientationchange', () => {
                setTimeout(() => {
                    if (typeof window.syncAllClozeInputWidths === 'function') {
                        window.syncAllClozeInputWidths();
                    }
                }, 120);
            }, { passive: true });
        }
        syncAllClozeInputWidths();
        if (typeof requestAnimationFrame === 'function') {
            requestAnimationFrame(syncAllClozeInputWidths);
        }
        if (typeof document !== 'undefined' && document.fonts && document.fonts.ready) {
            document.fonts.ready.then(syncAllClozeInputWidths).catch(() => {});
        }
    }

    // Sync Navigation Buttons State (both inside card and footer bar)
    const isFirst = (index === 0);
    const isLast = (index === currentDictSentences.length - 1);
    const nextBtnText = isLast ? '🎉 完成精听特训' : '下一句 →';

    const btnPrev = document.getElementById('btn-dict-prev');
    const btnNext = document.getElementById('btn-dict-next');
    const btnCardPrev = document.getElementById('btn-dict-card-prev');
    const btnCardNext = document.getElementById('btn-dict-card-next');
    const btnKbPrev = document.getElementById('btn-dict-kb-prev');
    const btnKbNext = document.getElementById('btn-dict-kb-next');

    if (btnPrev) { btnPrev.disabled = isFirst; }
    if (btnCardPrev) { btnCardPrev.disabled = isFirst; }
    if (btnKbPrev) { btnKbPrev.disabled = isFirst; }
    if (btnNext) {
        btnNext.textContent = nextBtnText;
        btnNext.classList.remove('pulse-next-guide');
    }
    if (btnCardNext) {
        btnCardNext.textContent = nextBtnText;
        btnCardNext.classList.remove('pulse-next-guide');
    }
    if (btnKbNext) {
        const kbNextText = document.getElementById('dict-kb-next-text');
        if (kbNextText) kbNextText.textContent = isLast ? '🎉 完成' : '下句 ➔';
        btnKbNext.classList.remove('pulse-next-guide');
    }

    // Audio Playback: If preserveAudio is true, do not interrupt playing audio or restart paused audio
    if (!options.preserveAudio) {
        playDictationAudioSegment(sent.start, sent.end);
    }

    // Set active input pointer to first unsolved blank
    if (clozeCard && !isAlreadyDone) {
        const firstUnsolvedInput = clozeCard.querySelector('.cloze-input:not([disabled])');
        if (firstUnsolvedInput) {
            setTimeout(() => {
                try {
                    // Do not override if user has already actively selected/focused a blank!
                    if (window.activeCustomKeyboardInput && 
                        !window.activeCustomKeyboardInput.disabled && 
                        document.body.contains(window.activeCustomKeyboardInput) && 
                        window.activeCustomKeyboardInput.closest('#dict-cloze-card')) {
                        return;
                    }
                    const isInPlaceRefresh = !!(options.keepModes || options.preserveScroll);
                    const shouldExpandKb = window.isLookupMode
                        ? false
                        : (isInPlaceRefresh
                            ? !window.dictKeyboardCollapsed
                            : ((typeof isPCDesktopDevice === 'function') ? !isPCDesktopDevice() : true));
                    if (typeof setActiveInputForCustomKeyboard === 'function' && !window.isLookupMode) {
                        setActiveInputForCustomKeyboard(firstUnsolvedInput, shouldExpandKb);
                    }
                    const len = firstUnsolvedInput.value.length;
                    firstUnsolvedInput.setSelectionRange(len, len);
                    firstUnsolvedInput._virtualCaretPos = len;
                    firstUnsolvedInput._userExplicitlyAtZero = false;
                } catch(e) {}
            }, 60);
        }
    }

    // Render candidate chips if Word Bank mode is active
    if (typeof renderWordBankChips === 'function') {
        renderWordBankChips();
    }

    if (typeof updateCustomKeyboardNextBtnState === 'function') {
        updateCustomKeyboardNextBtnState(isAlreadyDone);
    }
    if (typeof syncCustomVirtualKeyboardUI === 'function') {
        syncCustomVirtualKeyboardUI();
    }
    if (typeof syncDictKeyboardPreferenceUI === 'function') {
        syncDictKeyboardPreferenceUI();
    }
    if (typeof window.kickLiquidGlass === 'function') setTimeout(window.kickLiquidGlass, 60);
}

// 4. Handle Input Typing & Verification
function handleClozeInput(input, targetWord) {
    const wrap = input.closest('.cloze-input-wrap');
    const rawVal = input.value;
    const normalizedVal = String(rawVal || '')
        .replace(/[\u2018\u2019\u201B\u02BC\uFF07`]/g, "'")
        .replace(/[\u2013\u2014\u2212\uFF0D]/g, '-');
    const cleanVal = normalizedVal.replace(/[^a-zA-Z\'-]/g, '');
    if (rawVal !== cleanVal) {
        input.value = cleanVal;
    }
    const val = cleanVal.trim();
    const valLower = val.toLowerCase();
    const targetLower = targetWord.toLowerCase();

    const normVal = valLower.replace(/[\'-]/g, '');
    const normTarget = targetLower.replace(/[\'-]/g, '');

    const isMatch = (valLower === targetLower) || (normVal.length > 0 && normVal === normTarget);

    if (isMatch) {
        input.disabled = true;

        if (window.FeedbackEngine) {
            window.FeedbackEngine.playCorrect();
        }

        // Auto-format displayed value immediately to canonical targetWord (e.g. 'year-old', 'don\'t')
        input.value = targetWord;
        input.style.width = `${measureClozeWordWidth(targetWord)}px`;

        // Query all inputs in card and determine next forward unsolved blank
        const allCardInputs = Array.from(document.querySelectorAll('#dict-cloze-card .cloze-input'));
        const curIdx = allCardInputs.indexOf(input);
        const remainingInputs = allCardInputs.filter(inp => inp !== input && !inp.disabled);

        let nextInput = null;
        if (remainingInputs.length > 0) {
            nextInput = allCardInputs.slice(curIdx + 1).find(inp => !inp.disabled) || remainingInputs[0];
        }

        // 1. Immediately focus next input synchronously within user gesture event loop
        if (nextInput) {
            nextInput.focus();
            const nextWrap = nextInput.closest('.cloze-input-wrap');
            if (nextWrap) nextWrap.classList.add('has-focus');
            const nextLen = nextInput.value.length;
            try { nextInput.setSelectionRange(nextLen, nextLen); } catch(err) {}
            nextInput._virtualCaretPos = nextLen;
            nextInput._userExplicitlyAtZero = false;
            if (typeof setActiveInputForCustomKeyboard === 'function') {
                setActiveInputForCustomKeyboard(nextInput, true);
            }
        }

        // 2. Add green success pulse on current word
        if (wrap) {
            wrap.classList.add('correct-flash');
        }

        // 3. Smooth instantaneous transition to fuse into green done badge
        setTimeout(() => {
            if (!document.body.contains(input)) return;
            fuseClozeInputIntoText(input, targetWord);

            // Double check if any unsolved blanks remain in the current sentence
            const stillRemaining = document.querySelectorAll('#dict-cloze-card .cloze-input:not([disabled])');
            if (stillRemaining.length === 0) {
                triggerDictationSentenceSuccess();
            } else if (nextInput && !nextInput.disabled) {
                nextInput.focus();
                const nextLen = nextInput.value.length;
                try { nextInput.setSelectionRange(nextLen, nextLen); } catch(err) {}
                nextInput._virtualCaretPos = nextLen;
                nextInput._userExplicitlyAtZero = false;
                if (typeof setActiveInputForCustomKeyboard === 'function') {
                    setActiveInputForCustomKeyboard(nextInput, true);
                }
            }
        }, 60);
    }
}

// 5. Success Celebration & Continuous Auto-Advance Loop
let dictAutoAdvanceTimer = null;

function clearDictAutoAdvance() {
    if (dictAutoAdvanceTimer) {
        clearTimeout(dictAutoAdvanceTimer);
        dictAutoAdvanceTimer = null;
    }
    const btnNext = document.getElementById('btn-dict-next');
    if (btnNext) btnNext.classList.remove('auto-advancing');
    const btnKbNext = document.getElementById('btn-dict-kb-next');
    if (btnKbNext) btnKbNext.classList.remove('auto-advancing');
}
window.clearDictAutoAdvance = clearDictAutoAdvance;

function triggerDictationSentenceSuccess() {
    clearDictAutoAdvance();
    if (typeof playSuccessBellChime === 'function') {
        playSuccessBellChime();
    }

    // Save Progress
    if (currentDictExamTitle) {
        if (!window.completedExams[currentDictExamTitle]) {
            window.completedExams[currentDictExamTitle] = {};
        }
        if (!window.completedExams[currentDictExamTitle].dictationCompleted) {
            window.completedExams[currentDictExamTitle].dictationCompleted = {};
        }
        const nowDictTs = Date.now();
        window.completedExams[currentDictExamTitle].timestamp = nowDictTs;
        window.completedExams[currentDictExamTitle].dictUpdatedAt = nowDictTs;
        window.completedExams[currentDictExamTitle].dictationCompleted[currentDictIndex] = true;
        saveUserCloudData(currentDictExamTitle);

        if (typeof recordTodayQuestionAnswer === 'function') {
            recordTodayQuestionAnswer(currentDictExamTitle, 'dict_' + currentDictIndex, true);
        }
    }

    // Replay full audio slice once for complete listening immersion
    const sent = currentDictSentences[currentDictIndex];
    if (sent) {
        playDictationAudioSegment(sent.start, sent.end);
    }

    // Guide user with animated next button (No banner popup, no automatic jump)
    const isLast = (currentDictIndex === currentDictSentences.length - 1);
    const btnNext = document.getElementById('btn-dict-next');
    const btnCardNext = document.getElementById('btn-dict-card-next');
    if (btnNext) btnNext.classList.add('pulse-next-guide');
    if (btnCardNext) btnCardNext.classList.add('pulse-next-guide');
    if (typeof updateCustomKeyboardNextBtnState === 'function') {
        updateCustomKeyboardNextBtnState(true);
    }

    if (isLast) {
        if (typeof launchGrandConfettiShow === 'function') {
            launchGrandConfettiShow();
        }
    } else {
        // Continuous auto-advance loop: after audio segment completes, seamlessly glide to next sentence
        const audioPlayer = document.getElementById('dictation-audio-player');
        const hasValidSlice = sent && typeof sent.end === 'number' && typeof sent.start === 'number' && sent.end > sent.start;
        const rawDur = hasValidSlice
            ? (sent.end - sent.start)
            : ((audioPlayer && Number.isFinite(audioPlayer.duration) && audioPlayer.duration > 0) ? audioPlayer.duration : 2.8);
        const audioDurationSec = Math.max(1.8, Math.min(8.0, rawDur / (window.dictPlaybackRate || 1.0)));
        const autoAdvanceDelay = Math.round((audioDurationSec + 0.8) * 1000);
        const thisSentenceIdx = currentDictIndex;

        if (btnNext) btnNext.classList.add('auto-advancing');
        const btnKbNext = document.getElementById('btn-dict-kb-next');
        if (btnKbNext) btnKbNext.classList.add('auto-advancing');

        dictAutoAdvanceTimer = setTimeout(() => {
            dictAutoAdvanceTimer = null;
            if (window.activeView !== 'dictation-arena' || currentDictIndex !== thisSentenceIdx) return;
            const nextFn = window.handleNextDictSentence || window.handleNextSentence;
            if (typeof nextFn === 'function') {
                nextFn();
            }
        }, autoAdvanceDelay);
    }
}

window.showEnterNextHint = function() {
    const popover = document.getElementById('enter-next-popover');
    if (popover) {
        popover.style.display = 'none';
    }
};

window.closeEnterNextHint = function(isNever = false) {
    if (isNever) {
        try {
            window.__toyLS.setItem('toy_never_show_enter_hint', 'true');
            if (window.ToyStorage && typeof window.ToyStorage.setItem === 'function') {
                window.ToyStorage.setItem('toy_never_show_enter_hint', 'true');
            }
        } catch(e) {}
    }
    const popover = document.getElementById('enter-next-popover');
    if (popover) {
        popover.style.display = 'none';
    }
};


window.renderDictationSentence = renderDictationSentence;
window.handleClozeInput = handleClozeInput;
window.clearDictAutoAdvance = clearDictAutoAdvance;
window.triggerDictationSentenceSuccess = triggerDictationSentenceSuccess;


/* === js/dictation_controls.js === */
// ==========================================================================
// Dictation Transport Controls, Swipe Gestures & Sentence Drawer (js/dictation_controls.js)
// ==========================================================================

// 7. Initialize Dictation Control Listeners
function initDictationEventListeners() {
    if (window._dictControlsBound) return;
    window._dictControlsBound = true;
    const playBtn = document.getElementById('btn-dict-play') || document.getElementById('btn-zen-play-pause');
    const replayBtn = document.getElementById('btn-dict-replay');
    const speedBtn = document.getElementById('btn-dict-speed');
    const btnModeToggle = document.getElementById('btn-dict-mode-toggle');

    const btnPrev = document.getElementById('btn-dict-prev');
    const btnNext = document.getElementById('btn-dict-next');
    const btnCardPrev = document.getElementById('btn-dict-card-prev');
    const btnCardNext = document.getElementById('btn-dict-card-next');

    const btnHintFirst = document.getElementById('btn-dict-hint-first');
    const btnHintZh = document.getElementById('btn-dict-hint-zh');
    const btnRevealAnswer = document.getElementById('btn-dict-reveal-answer');

    const btnOpenDrawer = document.getElementById('btn-dict-drawer');
    const btnCardDrawer = document.getElementById('btn-dict-card-drawer');
    const drawerMask = document.getElementById('dict-drawer-mask');
    const btnCloseDrawer = document.getElementById('btn-dict-close-drawer');

    updateDictModeButtonUI();

    // Global Dictation Action Handlers
    function replayDictationAudio() {
        const sent = currentDictSentences[currentDictIndex];
        if (sent && window.DictAudioEngine) {
            DictAudioEngine.replay(sent.start, sent.end);
        }
    }
    window.replayDictationAudio = replayDictationAudio;
    window.replayDictSentence = replayDictationAudio;

    function cycleDictPlaybackSpeed() {
        const speedBtn = document.getElementById('btn-dict-speed');
        if (dictPlaybackRate === 1.0) {
            dictPlaybackRate = 1.25;
            if (speedBtn) speedBtn.textContent = '1.25X';
        } else if (dictPlaybackRate === 1.25) {
            dictPlaybackRate = 1.5;
            if (speedBtn) speedBtn.textContent = '1.5X';
        } else if (dictPlaybackRate === 1.5) {
            dictPlaybackRate = 0.75;
            if (speedBtn) speedBtn.textContent = '0.75X';
        } else {
            dictPlaybackRate = 1.0;
            if (speedBtn) speedBtn.textContent = '1.0X';
        }

        const audioPlayer = document.getElementById('dictation-audio-player');
        if (audioPlayer) {
            audioPlayer.preservesPitch = true;
            if ('webkitPreservesPitch' in audioPlayer) audioPlayer.webkitPreservesPitch = true;
            if ('mozPreservesPitch' in audioPlayer) audioPlayer.mozPreservesPitch = true;
            audioPlayer.playbackRate = dictPlaybackRate;
        }

        if (DictAudioEngine && typeof DictAudioEngine.updatePlaybackRate === 'function') {
            DictAudioEngine.updatePlaybackRate(dictPlaybackRate);
        }
    }
    window.cycleDictPlaybackSpeed = cycleDictPlaybackSpeed;
    window.cycleDictSpeed = cycleDictPlaybackSpeed;

    function toggleDictHint() {
        dictAnswerModeActive = false; // Mutually exclusive: close answer mode
        dictSkeletonModeActive = !dictSkeletonModeActive;

        renderDictationSentence(currentDictIndex, {
            preserveAudio: true,
            preserveScroll: true,
            keepModes: true
        });
    }
    window.toggleDictHint = toggleDictHint;

    function toggleDictAnswer() {
        dictSkeletonModeActive = false; // Mutually exclusive: close skeleton mode
        dictAnswerModeActive = !dictAnswerModeActive;

        renderDictationSentence(currentDictIndex, {
            preserveAudio: true,
            preserveScroll: true,
            keepModes: true
        });
    }
    window.toggleDictAnswer = toggleDictAnswer;

    function openDictationDrawer() {
        if (window.FeedbackEngine) window.FeedbackEngine.playTap();
        const drawerMask = document.getElementById('dict-drawer-mask');
        if (drawerMask) {
            drawerMask.style.display = 'flex';
            void drawerMask.offsetWidth;
            drawerMask.classList.add('active');
        }
        renderSentenceDrawer();
    }
    window.openDictationDrawer = openDictationDrawer;

    function closeDictationDrawer() {
        if (window.FeedbackEngine) window.FeedbackEngine.playTap();
        const drawerMask = document.getElementById('dict-drawer-mask');
        if (drawerMask) {
            drawerMask.classList.remove('active');
            setTimeout(() => {
                if (!drawerMask.classList.contains('active')) {
                    drawerMask.style.display = 'none';
                }
            }, 250);
        }
    }
    window.closeDictationDrawer = closeDictationDrawer;

    function handlePrevSentence() {
        if (window.FeedbackEngine) window.FeedbackEngine.playTap();
        clearDictAutoAdvance();
        if (currentDictIndex > 0) {
            renderDictationSentence(currentDictIndex - 1, { slideDirection: 'right' });
        }
    }

    function handleNextSentence() {
        if (window.FeedbackEngine) window.FeedbackEngine.playTap();
        clearDictAutoAdvance();
        if (currentDictIndex < currentDictSentences.length - 1) {
            const nextIdx = currentDictIndex + 1;
            if (isDailyListeningActive()) {
                const dayIdx = (window._currentDailyDay || 1) - 1;
                if (window.ToyPermissions && !window.ToyPermissions.canAccessDaily(dayIdx, nextIdx)) {
                    window.ToyPermissions.showUnlockModal('daily', { examIndex: dayIdx, sentenceIndex: nextIdx, dayNum: window._currentDailyDay, level: 'daily' });
                    return;
                }
            } else {
                const curLvl = getActiveDictExamLevel();
                const manifestList = (typeof getActiveExamManifest === 'function') ? getActiveExamManifest(curLvl) : [];
                const examIdx = manifestList.findIndex(m => m.title === currentDictExamTitle || m.examId === currentDictExamTitle);
                if (window.ToyPermissions && !window.ToyPermissions.canAccessDictation(examIdx >= 0 ? examIdx : 0, nextIdx, curLvl, currentDictExamTitle)) {
                    window.ToyPermissions.showUnlockModal('dictation', { examIndex: examIdx >= 0 ? examIdx : 0, sentenceIndex: nextIdx, examTitle: currentDictExamTitle, level: curLvl });
                    return;
                }
            }
            renderDictationSentence(nextIdx, { slideDirection: 'left' });
        } else {
            if (typeof launchGrandConfettiShow === 'function') launchGrandConfettiShow();
            if (isDailyListeningActive()) {
                switchView('daily-lobby');
            } else {
                switchView('dictation-lobby');
            }
        }
    }

    window.handleNextDictSentence = handleNextSentence;
    window.handlePrevDictSentence = handlePrevSentence;
    window.handleNextSentence = handleNextSentence;
    window.handlePrevSentence = handlePrevSentence;

    if (playBtn) {
        playBtn.addEventListener('click', () => {
            if (typeof window.toggleDictationPlayPause === 'function') {
                window.toggleDictationPlayPause();
            }
        });
    }

    if (replayBtn) {
        replayBtn.addEventListener('click', () => {
            clearDictAutoAdvance();
            replayDictationAudio();
        });
    }
    if (speedBtn) speedBtn.addEventListener('click', cycleDictPlaybackSpeed);

    if (btnPrev) btnPrev.addEventListener('click', handlePrevSentence);
    if (btnCardPrev) btnCardPrev.addEventListener('click', handlePrevSentence);
    if (btnNext) btnNext.addEventListener('click', handleNextSentence);
    if (btnCardNext) btnCardNext.addEventListener('click', handleNextSentence);

    if (btnHintFirst) btnHintFirst.addEventListener('click', toggleDictHint);
    if (btnRevealAnswer) btnRevealAnswer.addEventListener('click', toggleDictAnswer);

    if (btnOpenDrawer) {
        btnOpenDrawer.addEventListener('click', openDictationDrawer);
        btnOpenDrawer.addEventListener('pointerdown', (e) => { e.stopPropagation(); });
    }
    if (btnCardDrawer) {
        btnCardDrawer.addEventListener('click', openDictationDrawer);
        btnCardDrawer.addEventListener('pointerdown', (e) => { e.stopPropagation(); });
    }

    if (btnCloseDrawer) {
        btnCloseDrawer.addEventListener('click', closeDictationDrawer);
    }
    if (drawerMask) {
        drawerMask.addEventListener('click', (e) => {
            if (e.target === drawerMask) closeDictationDrawer();
        });
    }

    // 📱 Swipe Gesture for Switching Sentences (Swipe Left = Next, Swipe Right = Prev)
    const stageBody = document.getElementById('dict-stage-body') || document.getElementById('dict-canvas-main') || document.querySelector('#view-dictation-arena .dict-zen-canvas') || document.getElementById('view-dictation-arena');
    if (stageBody) {
        let touchStartX = 0;
        let touchStartY = 0;
        let touchStartTime = 0;

        stageBody.addEventListener('touchstart', (e) => {
            if (e.touches && e.touches.length === 1) {
                touchStartX = e.touches[0].clientX;
                touchStartY = e.touches[0].clientY;
                touchStartTime = Date.now();
            }
        }, { passive: true });

        stageBody.addEventListener('touchend', (e) => {
            if (e.changedTouches && e.changedTouches.length === 1) {
                const target = e.target;
                if (target && target.closest && (target.closest('#dict-virtual-keyboard') || target.closest('.drawer-panel') || target.closest('.dict-settings-modal') || target.closest('.dict-canvas-header') || target.closest('.btn-canvas-drawer'))) {
                    return;
                }

                const dx = e.changedTouches[0].clientX - touchStartX;
                const dy = e.changedTouches[0].clientY - touchStartY;
                const dt = Date.now() - touchStartTime;

                // Threshold: swipe duration < 500ms, dx >= 42px, horizontal dominant (|dx| > 1.35 * |dy|)
                if (dt < 500 && Math.abs(dx) >= 42 && Math.abs(dx) > Math.abs(dy) * 1.35) {
                    if (target && target.tagName === 'INPUT' && Math.abs(dx) < 70) {
                        return;
                    }
                    if (navigator.vibrate) try { navigator.vibrate(10); } catch(err) {}
                    if (dx < 0) {
                        handleNextSentence();
                    } else {
                        handlePrevSentence();
                    }
                }
            }
        }, { passive: true });

        // Tapping on card / sentence clears pending auto-advance timer
        stageBody.addEventListener('pointerdown', () => {
            clearDictAutoAdvance();
        }, { passive: true });
    }


    if (typeof initDictationYearFilterBar === 'function') {
        initDictationYearFilterBar(window.currentExamLevel);
    }

    if (typeof initCustomVirtualKeyboard === 'function') {
        initCustomVirtualKeyboard();
    }
}

// 8. Render Drawer for Quick Sentence Navigation
function renderSentenceDrawer() {
    try {
        const drawerGrid = document.getElementById('dict-drawer-grid') || document.getElementById('dict-drawer-sentence-grid');
        const drawerSecNav = document.getElementById('dict-drawer-section-nav');
        const drawerTitle = document.getElementById('dict-drawer-title');
        const drawerMask = document.getElementById('dict-drawer-mask');

        if (drawerTitle) {
            drawerTitle.textContent = currentDictExamTitle || '逐句精听索引';
        }

        if (!currentDictSentences || currentDictSentences.length === 0) {
            if (drawerGrid) drawerGrid.innerHTML = '<div style="color: #8e8e93; font-size: 13px; text-align: center; padding: 20px;">暂无句子索引</div>';
            return;
        }

        // 1. Group sentences into Categories/Sections
        const categories = [];
        let curCat = null;

        currentDictSentences.forEach((s, idx) => {
            const sec = s.sec || s.group || 'Section';
            let catKey = sec;
            let icon = '📝';

            if (/news/i.test(sec)) {
                icon = '📻';
            } else if (/conversation/i.test(sec)) {
                icon = '💬';
            } else if (/passage/i.test(sec)) {
                icon = '📜';
            } else if (/monologue/i.test(sec)) {
                icon = '🎙️';
            } else if (/discussion/i.test(sec)) {
                icon = '👥';
            } else if (/lecture/i.test(sec)) {
                icon = '🎓';
            } else if (/dictation|听写/i.test(sec)) {
                icon = '✍️';
            }

            if (!curCat || curCat.rawSec !== catKey) {
                if (curCat) {
                    curCat.endSeq = idx;
                    curCat.endIdx = idx - 1;
                    curCat.label = `${curCat.name} (${curCat.startSeq}-${curCat.endSeq})`;
                }
                curCat = {
                    key: `cat_${categories.length}`,
                    rawSec: catKey,
                    name: sec,
                    icon: icon,
                    startIdx: idx,
                    startSeq: idx + 1,
                    endIdx: idx,
                    endSeq: idx + 1
                };
                categories.push(curCat);
            } else {
                curCat.endIdx = idx;
                curCat.endSeq = idx + 1;
            }
        });

        if (curCat) {
            curCat.label = `${curCat.name} (${curCat.startSeq}-${curCat.endSeq})`;
        }

        // Determine currently active category (matches currentDictIndex)
        let activeCat = categories.find(c => currentDictIndex >= c.startIdx && currentDictIndex <= c.endIdx) || categories[0];

        // 2. Render only the chips belonging to the active category
        const renderCategoryChips = (cat) => {
            if (!drawerGrid) return;
            drawerGrid.innerHTML = '';
            const doneMap = window.completedExams?.[currentDictExamTitle]?.dictationCompleted || {};
            const curLvl = getActiveDictExamLevel();
            const manifestList = (typeof getActiveExamManifest === 'function') ? getActiveExamManifest(curLvl) : [];
            const examIdx = manifestList.findIndex(m => m.title === currentDictExamTitle || m.examId === currentDictExamTitle);

            for (let idx = cat.startIdx; idx <= cat.endIdx; idx++) {
                let isSentLocked = false;
                if (isDailyListeningActive()) {
                    const dayIdx = (window._currentDailyDay || 1) - 1;
                    isSentLocked = window.ToyPermissions && !window.ToyPermissions.canAccessDaily(dayIdx, idx);
                } else {
                    isSentLocked = window.ToyPermissions && !window.ToyPermissions.canAccessDictation(examIdx >= 0 ? examIdx : 0, idx, curLvl, currentDictExamTitle);
                }
                const chip = document.createElement('div');
                chip.className = `q-chip ${isSentLocked ? 'is-locked-chip' : ''}`;
                chip.textContent = String(idx + 1);

                // Strictly turn green ONLY if the whole sentence was completed
                if (doneMap[idx]) {
                    chip.classList.add('correct');
                }

                if (idx === currentDictIndex) {
                    chip.style.borderColor = '#111113';
                    chip.style.borderWidth = '2px';
                    chip.style.fontWeight = '800';
                    chip.style.color = '#111113';
                    chip.style.background = '#f5f5f7';
                }

                chip.addEventListener('click', () => {
                    if (isSentLocked) {
                        if (typeof window.closeDictationDrawer === 'function') {
                            window.closeDictationDrawer();
                        } else if (drawerMask) {
                            drawerMask.classList.remove('active');
                            drawerMask.style.display = 'none';
                        }
                        if (window.ToyPermissions) {
                            if (isDailyListeningActive()) {
                                const dayIdx = (window._currentDailyDay || 1) - 1;
                                window.ToyPermissions.showUnlockModal('daily', { examIndex: dayIdx, sentenceIndex: idx, dayNum: window._currentDailyDay, level: 'daily' });
                            } else {
                                window.ToyPermissions.showUnlockModal('dictation', { examIndex: examIdx >= 0 ? examIdx : 0, sentenceIndex: idx, examTitle: currentDictExamTitle, level: curLvl });
                            }
                        }
                        return;
                    }
                    renderDictationSentence(idx);
                    if (typeof window.closeDictationDrawer === 'function') {
                        window.closeDictationDrawer();
                    } else if (drawerMask) {
                        drawerMask.classList.remove('active');
                        drawerMask.style.display = 'none';
                    }
                });
                drawerGrid.appendChild(chip);
            }
        };

        // 3. Render Section Jump Pills in Dictation Drawer
        if (drawerSecNav) {
            const curLvl = getActiveDictExamLevel();
            const manifestList = (typeof getActiveExamManifest === 'function') ? getActiveExamManifest(curLvl) : [];
            const examIdx = manifestList.findIndex(m => m.title === currentDictExamTitle || m.examId === currentDictExamTitle);
            drawerSecNav.innerHTML = categories.map(c => {
                const isActive = (c.key === activeCat.key);
                const isSecLocked = isDailyListeningActive()
                    ? (window.ToyPermissions && !window.ToyPermissions.canAccessDaily((window._currentDailyDay || 1) - 1, c.startIdx))
                    : (window.ToyPermissions && !window.ToyPermissions.canAccessDictation(examIdx >= 0 ? examIdx : 0, c.startIdx, curLvl, currentDictExamTitle));
                return `<button class="drawer-sec-pill ${isActive ? 'active' : ''} ${isSecLocked ? 'is-sec-locked' : ''}" data-cat-key="${c.key}"><span>${c.icon}</span><span>${c.label}${isSecLocked ? ' 🔒' : ''}</span></button>`;
            }).join('');

            drawerSecNav.querySelectorAll('.drawer-sec-pill').forEach(btn => {
                btn.addEventListener('click', () => {
                    const catKey = btn.dataset.catKey;
                    const foundCat = categories.find(c => c.key === catKey);
                    if (foundCat) {
                        activeCat = foundCat;
                        drawerSecNav.querySelectorAll('.drawer-sec-pill').forEach(b => {
                            b.classList.toggle('active', b.dataset.catKey === catKey);
                        });
                        renderCategoryChips(activeCat);
                    }
                });
            });

            if (window.enableHorizontalDragScroll) {
                window.enableHorizontalDragScroll(drawerSecNav, document.getElementById('dict-drawer-section-nav-wrapper'));
            }
        }

        // 4. Initial render of the active category chips
        renderCategoryChips(activeCat);

        if (drawerMask) {
            drawerMask.style.display = '';
            drawerMask.classList.add('active');
        }
    } catch(err) {
        console.error('[Dictation] renderSentenceDrawer error:', err);
    }
}
window.renderSentenceDrawer = renderSentenceDrawer;

// Auto init event listeners when DOM ready
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initDictationEventListeners);
} else {
    initDictationEventListeners();
}
window.initDictationEventListeners = initDictationEventListeners;


/* === js/written_lobby.js === */
/**
 * ==========================================================================
 * Written Exam System Engine (Cloze, Matching, Reading, Translation, Writing)
 * Supports: 随刷随解 (Practice Mode) & 全真模考 (Exam Mode)
 * ==========================================================================
 */

var currentWrittenFilterRange = 'ALL';
var currentWrittenExamTitle = '';
var currentWrittenQuestions = [];
var currentWrittenQIndex = 0;
var userWrittenAnswers = {};
window.showWrittenBilingual = false;
var currentWrittenModule = 'careful';
var revealedModelKeys = {};

function getWrittenExamTrackIndex(title, level) {
    const curLvl = level || ((typeof window.getExamLevelFromId === 'function' && title)
        ? window.getExamLevelFromId(title)
        : (window.currentExamLevel || 'cet4'));
    let manifestList = (typeof getActiveExamManifest === 'function') ? getActiveExamManifest(curLvl) : [];
    if (curLvl === 'kaoyan' && title) {
        const isEng2 = title.includes('英语（二）') || title.includes('英语二') || title.toLowerCase().includes('eng2');
        manifestList = manifestList.filter(item => {
            const t = item.title || '';
            const id = item.examId || '';
            const itemIsEng2 = t.includes('英语（二）') || t.includes('英语二') || id.includes('eng2');
            return isEng2 ? itemIsEng2 : !itemIsEng2;
        });
    }
    const idx = manifestList.findIndex(m => m.title === title || m.examId === title);
    return idx >= 0 ? idx : 0;
}
window.getWrittenExamTrackIndex = getWrittenExamTrackIndex;

function initWrittenFilters() {
    const writtenYearFilterBar = document.getElementById('written-year-filter-bar');
    if (writtenYearFilterBar) {
        writtenYearFilterBar.querySelectorAll('.chip-year').forEach(chip => {
            chip.addEventListener('click', () => {
                const nextRange = chip.dataset.range || 'ALL';
                const changed = (currentWrittenFilterRange !== nextRange) || !chip.classList.contains('active');
                writtenYearFilterBar.querySelectorAll('.chip-year').forEach(c => c.classList.remove('active'));
                chip.classList.add('active');
                currentWrittenFilterRange = nextRange;
                window.currentWrittenFilterRange = currentWrittenFilterRange;
                renderWrittenLobbyGrid(currentWrittenFilterRange, { animateSlider: true });
                if (changed && typeof window.triggerExamGridFilterTransition === 'function') {
                    window.triggerExamGridFilterTransition('written-exam-grid');
                }
            });
        });
        if (typeof updateSegmentedSlider === 'function') {
            updateSegmentedSlider(writtenYearFilterBar, false);
        }
        if (window.enableHorizontalDragScroll) {
            window.enableHorizontalDragScroll(writtenYearFilterBar);
        }
    }

    const writtenModuleTabs = document.getElementById('written-module-tabs');
    if (writtenModuleTabs) {
        writtenModuleTabs.querySelectorAll('.written-tab-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                const sec = btn.dataset.sec;
                const idx = currentWrittenQuestions.findIndex(q => q.secKey === sec);
                if (idx >= 0) renderWrittenQuestion(idx);
            });
        });
        if (window.enableHorizontalDragScroll) {
            window.enableHorizontalDragScroll(writtenModuleTabs);
        }
    }

    const btnWrittenPrev = document.getElementById('btn-written-prev-q');
    const btnWrittenNext = document.getElementById('btn-written-next-q');
    const btnWrittenOpenDrawer = document.getElementById('btn-written-open-drawer');

    function handlePrevWrittenQuestion() {
        if (window.FeedbackEngine) window.FeedbackEngine.playTap();
        if (!Array.isArray(currentWrittenQuestions)) return;
        const curQ = currentWrittenQuestions[currentWrittenQIndex];
        if (curQ && curQ.type === 'proofread') {
            const pfIndices = currentWrittenQuestions.map((it, i) => it.type === 'proofread' ? i : -1).filter(i => i !== -1);
            const firstPf = pfIndices[0];
            if (firstPf > 0) {
                renderWrittenQuestion(firstPf - 1);
                return;
            }
        }
        if (currentWrittenQIndex > 0) renderWrittenQuestion(currentWrittenQIndex - 1);
    }
    window.handlePrevWrittenQuestion = handlePrevWrittenQuestion;

    function handleNextWrittenQuestion() {
        if (window.FeedbackEngine) window.FeedbackEngine.playTap();
        if (!Array.isArray(currentWrittenQuestions)) return;
        const curQ = currentWrittenQuestions[currentWrittenQIndex];
        if (curQ && curQ.type === 'proofread') {
            const pfIndices = currentWrittenQuestions.map((it, i) => it.type === 'proofread' ? i : -1).filter(i => i !== -1);
            const lastPf = pfIndices[pfIndices.length - 1];
            if (lastPf < currentWrittenQuestions.length - 1) {
                renderWrittenQuestion(lastPf + 1);
                return;
            } else {
                finishWrittenExam();
                return;
            }
        }
        if (currentWrittenQIndex < currentWrittenQuestions.length - 1) {
            renderWrittenQuestion(currentWrittenQIndex + 1);
        } else {
            finishWrittenExam();
        }
    }
    window.handleNextWrittenQuestion = handleNextWrittenQuestion;

    function openWrittenDrawer() {
        if (window.FeedbackEngine) window.FeedbackEngine.playTap();
        const titleText = document.getElementById('drawer-title-text');
        const drawerSecNav = document.getElementById('drawer-section-nav');
        const drawerMask = document.getElementById('drawer-mask');

        if (titleText && Array.isArray(currentWrittenQuestions)) {
            titleText.textContent = `笔试真题答题卡 (共 ${currentWrittenQuestions.length} 题)`;
        }

        // Render section jump pills in drawer (自适应动态提取)
        if (drawerSecNav && Array.isArray(currentWrittenQuestions)) {
            const currentSec = (currentWrittenQuestions && currentWrittenQuestions[currentWrittenQIndex]) ? currentWrittenQuestions[currentWrittenQIndex].secKey : '';
            const secMap = {};
            (currentWrittenQuestions || []).forEach(q => {
                const k = q.secKey || 'other';
                if (!secMap[k]) {
                    let icon = '📖';
                    let label = q.section ? q.section.split('·')[0].trim() : k;
                    if (k === 'banked_cloze') { icon = '🧩'; label = '选词填空'; }
                    else if (k === 'cloze' || k === 'cloze_choice') { icon = '🧩'; label = '完形填空'; }
                    else if (k === 'matching') { icon = '📑'; label = '长篇匹配'; }
                    else if (k === 'careful') { icon = '📖'; label = '阅读理解'; }
                    else if (k === 'seven_out_of_five') { icon = '📑'; label = q.subSection || '七选五'; }
                    else if (k === 'dialogue_completion') { icon = '💬'; label = '补全对话'; }
                    else if (k === 'phonetics') { icon = '🎯'; label = '语音知识'; }
                    else if (k === 'multiple_choice') { icon = '🎯'; label = '单项填空'; }
                    else if (k === 'grammar_fill_in' || k === 'fill_in') { icon = '✍️'; label = '语法填空'; }
                    else if (k === 'word_spelling') { icon = '✍️'; label = '单词拼写'; }
                    else if (k === 'error_correction' || k === 'proofread') { icon = '🛠️'; label = '短文改错'; }
                    else if (k === 'translation') { icon = '🌐'; label = (q.type === 'translation_en_zh') ? '英译汉' : '汉译英'; }
                    else if (k === 'writing') { icon = '📝'; label = '短文写作'; }
                    secMap[k] = { key: k, label: label, icon: icon, firstId: q.id, lastId: q.id };
                }
                secMap[k].lastId = q.id;
            });
            const curLvl = (typeof window.getExamLevelFromId === 'function' && currentWrittenExamTitle)
                ? window.getExamLevelFromId(currentWrittenExamTitle)
                : (window.currentExamLevel || 'cet4');
            const examIdx = getWrittenExamTrackIndex(currentWrittenExamTitle, curLvl);
            const sections = Object.values(secMap).map(s => {
                const targetIdx = currentWrittenQuestions.findIndex(q => q.secKey === s.key);
                const isSecLocked = window.ToyPermissions && !window.ToyPermissions.canAccessWrittenExam(examIdx >= 0 ? examIdx : 0, targetIdx >= 0 ? targetIdx : 0, curLvl);
                const baseLabel = (s.key === 'writing' && s.firstId !== s.lastId) ? '写作' : s.label;
                const rangeStr = (s.firstId === s.lastId) ? `${s.firstId}` : `${s.firstId}-${s.lastId}`;
                return {
                    key: s.key,
                    label: `${baseLabel} (${rangeStr})`,
                    icon: s.icon,
                    isSecLocked: isSecLocked
                };
            });
            drawerSecNav.innerHTML = sections.map(s => {
                const isActive = s.key === currentSec;
                return `<button class="drawer-sec-pill ${isActive ? 'active' : ''} ${s.isSecLocked ? 'is-sec-locked' : ''}" data-sec="${s.key}"><span>${s.icon}</span><span>${s.label}${s.isSecLocked ? ' 🔒' : ''}</span></button>`;
            }).join('');

            drawerSecNav.querySelectorAll('.drawer-sec-pill').forEach(btn => {
                btn.addEventListener('click', () => {
                    const sec = btn.dataset.sec;
                    const targetIdx = currentWrittenQuestions.findIndex(q => q.secKey === sec);
                    if (targetIdx >= 0) {
                        renderWrittenQuestion(targetIdx);
                        if (drawerMask) drawerMask.classList.remove('active');
                    }
                });
            });

            if (window.enableHorizontalDragScroll) {
                window.enableHorizontalDragScroll(drawerSecNav, document.getElementById('drawer-section-nav-wrapper'));
            }
        }

        if (typeof window.renderWrittenDrawerGrid === 'function') {
            window.renderWrittenDrawerGrid();
        }
        if (drawerMask) {
            drawerMask.style.display = '';
            drawerMask.classList.add('active');
        }
    }
    window.openWrittenDrawer = openWrittenDrawer;

    if (btnWrittenPrev) {
        btnWrittenPrev.addEventListener('click', handlePrevWrittenQuestion);
    }

    if (btnWrittenNext) {
        btnWrittenNext.addEventListener('click', handleNextWrittenQuestion);
    }

    if (btnWrittenOpenDrawer) {
        btnWrittenOpenDrawer.addEventListener('click', openWrittenDrawer);
    }

    // 顶部题号胶囊与题型胶囊点击均可直接呼出答题卡/大题切换面板
    const writtenTopBar = document.querySelector('#written-stage-card .quiz-card-top-bar');
    if (writtenTopBar) {
        const seqBadge = writtenTopBar.querySelector('.sequence-badge');
        const secBadge = document.getElementById('written-section-badge');
        [seqBadge, secBadge].forEach(el => {
            if (el) {
                el.style.cursor = 'pointer';
                el.title = '点击快速切换题号或大题模块';
                el.addEventListener('click', openWrittenDrawer);
            }
        });
    }
}

window.renderWrittenDrawerGrid = function() {
    const drawerQGrid = document.getElementById('drawer-q-grid');
    const drawerMask = document.getElementById('drawer-mask');
    if (!drawerQGrid || !Array.isArray(currentWrittenQuestions)) return;
    drawerQGrid.innerHTML = '';

    const curLvl = (typeof window.getExamLevelFromId === 'function' && currentWrittenExamTitle)
        ? window.getExamLevelFromId(currentWrittenExamTitle)
        : (window.currentExamLevel || 'cet4');
    const examIdx = getWrittenExamTrackIndex(currentWrittenExamTitle, curLvl);

    currentWrittenQuestions.forEach((q, idx) => {
        const ans = userWrittenAnswers[currentWrittenExamTitle]?.[q.id];
        const isLocked = window.ToyPermissions && !window.ToyPermissions.canAccessWrittenExam(examIdx >= 0 ? examIdx : 0, idx, curLvl);
        const isSubjectiveRevealed = (
            (q.type === 'writing' && !!(revealedModelKeys['writing_' + currentWrittenExamTitle + '_' + q.id] || revealedModelKeys['writing_' + currentWrittenExamTitle])) ||
            ((q.type === 'translation' || q.type === 'translation_en_zh') && !!(revealedModelKeys['trans_' + currentWrittenExamTitle + '_' + q.id] || revealedModelKeys['trans_' + currentWrittenExamTitle]))
        );

        const chip = document.createElement('div');
        chip.className = `q-chip ${isLocked ? 'is-locked-chip' : ''}`;
        chip.textContent = q.id;

        if (window.isExamMode) {
            if (ans || isSubjectiveRevealed) {
                chip.style.background = '#f0f6ff';
                chip.style.borderColor = '#007aff';
                chip.style.color = '#007aff';
                chip.style.fontWeight = '700';
            }
        } else {
            if (ans) {
                chip.classList.add(ans.isCorrect ? 'correct' : 'wrong');
            } else if (isSubjectiveRevealed) {
                chip.style.background = '#f0f6ff';
                chip.style.borderColor = '#007aff';
                chip.style.color = '#007aff';
                chip.style.fontWeight = '700';
            }
        }

        if (idx === currentWrittenQIndex) {
            chip.style.borderColor = '#007aff';
            chip.style.borderWidth = '2px';
            chip.style.fontWeight = '800';
            if (!ans) {
                chip.style.color = '#007aff';
            }
        }

        chip.addEventListener('click', () => {
            if (isLocked) {
                if (drawerMask) drawerMask.classList.remove('active');
                if (window.ToyPermissions) window.ToyPermissions.showUnlockModal('written', { examIndex: examIdx >= 0 ? examIdx : 0, questionIndex: idx, level: curLvl });
                return;
            }
            renderWrittenQuestion(idx);
            if (drawerMask) drawerMask.classList.remove('active');
        });
        drawerQGrid.appendChild(chip);
    });
};

function renderWrittenLobbyGrid(filterRange, options = {}) {
    const writtenExamGrid = document.getElementById('written-exam-grid');
    if (!writtenExamGrid) return;
    
    const activeLvl = window.currentExamLevel || 'cet4';
    let activeFilter = filterRange || (typeof currentWrittenFilterRange !== 'undefined' ? currentWrittenFilterRange : 'ALL');
    if (activeFilter === '2008-2014' && activeLvl !== 'gaokao' && activeLvl !== 'kaoyan') {
        activeFilter = 'ALL';
    }
    currentWrittenFilterRange = activeFilter;
    window.currentWrittenFilterRange = activeFilter;
    window.currentWrittenFilter = activeFilter;

    const writtenFilterBar = document.getElementById('written-year-filter-bar');
    if (writtenFilterBar) {
        const chips = writtenFilterBar.querySelectorAll('.chip-year');
        chips.forEach(c => {
            c.classList.toggle('active', c.dataset.range === activeFilter);
        });
        if (typeof window.updateSegmentedSlider === 'function') {
            window.updateSegmentedSlider(writtenFilterBar, !!(options && options.animateSlider));
        }
    }

    const manifestList = (typeof getActiveExamManifest === 'function')
        ? getActiveExamManifest()
        : (window.WRITTEN_EXAMS_MAP ? Object.keys(window.WRITTEN_EXAMS_MAP).map(t => ({ title: t })) : []);

    if (!manifestList || manifestList.length === 0) {
        const retryCount = (options && typeof options._retryCount === 'number') ? options._retryCount : 0;
        if (retryCount < 40) {
            setTimeout(() => renderWrittenLobbyGrid(activeFilter, Object.assign({}, options, { _retryCount: retryCount + 1 })), 50);
        } else {
            writtenExamGrid.innerHTML = '<div style="grid-column: 1 / -1; text-align: center; padding: 36px 16px; color: var(--ink-sub); font-size: 13.5px;">暂无可用笔试试卷，请检查网络后重试</div>';
        }
        return;
    }
    writtenExamGrid.innerHTML = '';

    const tier = (window.ToyPermissions && typeof window.ToyPermissions.getTier === 'function')
        ? window.ToyPermissions.getTier()
        : 2;

    const subjFilter = (window.currentExamLevel === 'kaoyan')
        ? (window.currentKaoyanSubjectFilter || 'ENG1')
        : 'ALL';

    let visibleIdx = 0;
    const unlockedVisibleTitles = [];
    manifestList.forEach((item, idx) => {
        const title = item.title;
        const yearMatch = title.match(/(\d{4})年/);
        const y = yearMatch ? parseInt(yearMatch[1]) : (item.year || 0);

        if ((activeFilter === 'ENG1' || subjFilter === 'ENG1') && !title.includes('英语（一）') && !title.includes('英语一') && !(item.examId && item.examId.includes('eng1'))) return;
        if ((activeFilter === 'ENG2' || subjFilter === 'ENG2') && !title.includes('英语（二）') && !title.includes('英语二') && !(item.examId && item.examId.includes('eng2'))) return;
        if (activeFilter === '2021-2026' && !(y >= 2021 && y <= 2026)) return;
        if (activeFilter === '2015-2020' && !(y >= 2015 && y <= 2020)) return;
        if (activeFilter === '2008-2014' && !(y >= 2008 && y <= 2014)) return;

        visibleIdx++;
        const cardIdx = getWrittenExamTrackIndex(title, activeLvl);
        const isDone = window.completedExams && window.completedExams[title];
        let statusText = '未练习';
        let isCompleted = false;

        const currentLvl = window.currentExamLevel || 'cet4';
        const isCharged = !!(window.ToyPermissions && (window.ToyPermissions.isCharged || window.ToyPermissions.isAuthor));
        const hasTrackUnlocked = !!(window.ToyPermissions && window.ToyPermissions.hasUnlockedTrack(currentLvl));
        let isLocked = (cardIdx > 0 && !isCharged);

        if (cardIdx === 0) {
            const ansCount = (isDone && isDone.writtenAnswers)
                ? Object.values(isDone.writtenAnswers).filter(v => v && !v._deleted).length
                : 0;
            if (hasTrackUnlocked || isCharged) {
                if (isDone && typeof isDone.writtenScore === 'number' && !isNaN(isDone.writtenScore)) {
                    statusText = `已测 ${isDone.writtenScore}分`;
                    isCompleted = true;
                } else if (ansCount > 0) {
                    statusText = `已做 ${ansCount} 题`;
                    isCompleted = true;
                } else {
                    statusText = '未练习';
                }
            } else {
                const qTrialRange = (currentLvl === 'gaokao') ? 'Q21-22' : (currentLvl === 'kaoyan' ? 'Q1-2' : 'Q26-27');
                statusText = ansCount > 0 ? '已试做' : `免费试做 (${qTrialRange})`;
                isCompleted = ansCount > 0;
            }
            isLocked = false;
        } else {
            if (isLocked) {
                statusText = '包月充电解锁';
            } else if (isDone) {
                if (typeof isDone.writtenScore === 'number' && !isNaN(isDone.writtenScore)) {
                    statusText = `已测 ${isDone.writtenScore}分`;
                    isCompleted = true;
                } else if (isDone.writtenAnswers) {
                    const ansCount = Object.values(isDone.writtenAnswers).filter(v => v && !v._deleted).length;
                    if (ansCount > 0) {
                        statusText = `已做 ${ansCount} 题`;
                        isCompleted = true;
                    }
                }
            }
        }

        const card = document.createElement('div');
        card.className = `exam-card ${isLocked ? 'is-locked-card' : ''}`;
        card.dataset.examTitle = title;
        card.innerHTML = `
            <div class="exam-card-title">${title}</div>
            <div class="exam-card-meta">
                <span class="status-tag ${isLocked ? 'locked-tag' : (isCompleted ? 'completed' : '')}">${statusText}</span>
            </div>
        `;
        if (!isLocked) {
            unlockedVisibleTitles.push(title);
            if (typeof window.bindCardSpeculativePrefetch === 'function') {
                window.bindCardSpeculativePrefetch(card, title, currentLvl, 'written');
            }
        }
        card.addEventListener('contextmenu', (e) => e.preventDefault());
        card.addEventListener('click', () => {
            const currentlyLocked = window.ToyPermissions ? !window.ToyPermissions.canAccessWrittenExam(cardIdx, 0, currentLvl) : false;
            if (currentlyLocked) {
                window.ToyPermissions.showUnlockModal('written', { examIndex: cardIdx, level: currentLvl });
                return;
            }
            if (card.classList.contains('is-activating')) return;
            card.classList.add('is-activating');
            setTimeout(() => card.classList.remove('is-activating'), 900);
            startWrittenExam(title);
        });
        writtenExamGrid.appendChild(card);
    });
    if (unlockedVisibleTitles.length > 0 && typeof window.scheduleLobbyTopPrefetch === 'function') {
        window.scheduleLobbyTopPrefetch(unlockedVisibleTitles, activeLvl, 'written');
    }
}

window.updateWrittenLobbyGridState = function(filter) {
    const wFilter = filter || (typeof currentWrittenFilterRange !== 'undefined' ? currentWrittenFilterRange : 'ALL');
    renderWrittenLobbyGrid(wFilter);
};

function buildWrittenQuestionsList(examData) {
    if (!examData) return [];
    if (Array.isArray(examData.questions) && examData.questions.length > 0) {
        return examData.questions;
    }
    const list = [];

    // 1. Banked Cloze (Q26-35)
    const cloze = examData.reading?.banked_cloze;
    if (cloze && cloze.questions) {
        const wordBank = cloze.word_bank || cloze.word_bank_map || {};

        cloze.questions.forEach(q => {
            const options = {};
            ['A','B','C','D','E','F','G','H','I','J','K','L','M','N','O'].forEach(l => {
                if (typeof wordBank[l] === 'string') {
                    options[l] = wordBank[l];
                } else if (wordBank[l] && wordBank[l].word) {
                    options[l] = wordBank[l].word;
                } else if (wordBank[l] && wordBank[l].en) {
                    options[l] = wordBank[l].en;
                }
            });

            list.push({
                id: q.id,
                secKey: 'cloze',
                section: '选词填空 · Section A',
                type: 'cloze',
                passage: cloze.passage || '',
                translation_zh: cloze.passage_zh || cloze.translation_zh || '',
                question_text: `Question ${q.id}. 请选择填入空格 [ ${q.id} ] 的单词：`,
                question_text_zh: '',
                options: options,
                answer: q.answer,
                word: q.word,
                evidence_en: q.evidence || q.evidence_en || '',
                evidence_zh: q.evidence_zh || '',
                analysis: q.analysis || ''
            });
        });
    }

    // 2. Matching (Q36-45)
    const matching = examData.reading?.matching;
    if (matching && matching.questions) {
        const paragraphs = matching.paragraphs || {};
        const paragraphsZh = matching.paragraphs_zh || {};
        const paraKeys = Object.keys(paragraphs);

        matching.questions.forEach(q => {
            const options = {};
            const optionsZh = {};
            paraKeys.forEach(k => {
                options[k] = paragraphs[k] || '';
                optionsZh[k] = paragraphsZh[k] || '';
            });

            list.push({
                id: q.id,
                secKey: 'matching',
                section: '长篇匹配 · Section B',
                type: 'matching',
                passage_title: matching.title || '',
                statement: q.statement || '',
                question_text: `Question ${q.id}. ${q.statement || ''}`,
                question_text_zh: q.statement_zh || q.question_text_zh || (matching.title ? `文章主题: ${matching.title}` : '段落匹配'),
                options: options,
                options_zh: optionsZh,
                answer: q.answer,
                evidence_en: q.evidence || q.evidence_en || '',
                evidence_zh: q.evidence_zh || '',
                synonym_pairs: q.synonym_pairs || [],
                analysis: q.analysis || ''
            });
        });
    }

    // 3. Careful Reading (Q46-55)
    const careful = examData.reading?.careful_reading;
    if (careful && Array.isArray(careful)) {
        careful.forEach((passageObj, pIdx) => {
            (passageObj.questions || []).forEach(q => {
                let rawQText = (q.question || q.question_text || '').replace(/^Question\s*\d*[\.:\s]*/i, '').trim();
                const zhText = (q.question_zh || q.question_text_zh || '').trim();
                list.push({
                    id: q.id,
                    secKey: 'careful',
                    section: `阅读理解 · Passage ${pIdx + 1}`,
                    type: q.type || 'careful',
                    insert_sentence: q.insert_sentence || q.sentence || '',
                    passage: passageObj.passage || passageObj.content || '',
                    translation_zh: passageObj.passage_zh || passageObj.translation_zh || '',
                    question_text: rawQText ? `Question ${q.id}. ${rawQText}` : `Question ${q.id}.`,
                    question_text_zh: zhText,
                    options: q.options || {},
                    options_zh: q.options_zh || {},
                    answer: q.answer,
                    evidence_en: q.evidence || q.evidence_en || '',
                    evidence_zh: q.evidence_zh || '',
                    synonym_pairs: q.synonym_pairs || [],
                    analysis: q.analysis || ''
                });
            });
        });
    }

    // 3.35 Phonetics (语音知识辨音, 2008-2010全国卷等)
    const phonetics = examData.language_use?.phonetics;
    const phoneticsQs = Array.isArray(phonetics) ? phonetics : (phonetics && Array.isArray(phonetics.questions) ? phonetics.questions : null);
    if (phoneticsQs && phoneticsQs.length > 0) {
        phoneticsQs.forEach(q => {
            let rawQText = (q.question_text || q.word || '').replace(/^Question\s*\d*[\.:\s]*/i, '').trim();
            list.push({
                id: q.id,
                secKey: 'phonetics',
                section: '语音知识 · Phonetics',
                type: 'multiple_choice',
                passage: '',
                question_text: rawQText ? `Question ${q.id}. 请选出划线部分发音相同的一项：${rawQText}` : `Question ${q.id}.`,
                question_text_zh: q.question_zh || '辨别划线部分发音',
                options: q.options || {},
                options_zh: q.options_zh || {},
                answer: q.answer,
                analysis: q.analysis || ''
            });
        });
    }

    // 3.4 Multiple Choice (单项选择 / 单项填空, 2008-2013高考等)
    const mc = examData.language_use?.multiple_choice;
    const mcQuestions = Array.isArray(mc) ? mc : (mc && Array.isArray(mc.questions) ? mc.questions : null);
    if (mcQuestions && mcQuestions.length > 0) {
        mcQuestions.forEach(q => {
            let rawQText = (q.question_text || q.question || '').replace(/^Question\s*\d*[\.:\s]*/i, '').trim();
            list.push({
                id: q.id,
                secKey: 'multiple_choice',
                section: '单项填空',
                type: 'multiple_choice',
                passage: '',
                question_text: rawQText ? `Question ${q.id}. ${rawQText}` : `Question ${q.id}.`,
                question_text_zh: q.question_zh || '',
                options: q.options || {},
                options_zh: q.options_zh || {},
                answer: q.answer,
                analysis: q.analysis || ''
            });
        });
    }

    // 3.5 Seven out of Five (七选五, Q36-40)
    const seven = examData.reading?.seven_out_of_five;
    if (seven && seven.questions) {
        seven.questions.forEach(q => {
            list.push({
                id: q.id,
                secKey: 'seven_out_of_five',
                section: '阅读七选五',
                type: 'seven_out_of_five',
                passage: seven.passage || seven.dialogue || seven.content || '',
                translation_zh: seven.passage_zh || seven.dialogue_zh || seven.translation_zh || '',
                question_text: `Question ${q.id}. 请选择填入空格 [ ${q.id} ] 的最佳选项：`,
                options: seven.options || {},
                options_zh: seven.options_zh || {},
                answer: q.answer,
                analysis: q.analysis || ''
            });
        });
    }

    // 3.55 Dialogue Completion (补全对话)
    const dc = examData.reading?.dialogue_completion;
    if (dc && dc.questions && Array.isArray(dc.questions)) {
        dc.questions.forEach(q => {
            list.push({
                id: q.id,
                secKey: 'dialogue_completion',
                section: '补全对话',
                type: 'seven_out_of_five',
                passage: dc.dialogue || dc.passage || '',
                translation_zh: dc.dialogue_zh || dc.passage_zh || '',
                question_text: `Question ${q.id}. 请选择填入对话空格 [ ${q.id} ] 的最佳选项：`,
                options: dc.options || {},
                options_zh: dc.options_zh || {},
                answer: q.answer,
                analysis: q.analysis || ''
            });
        });
    }

    // 3.6 Cloze Choice (完形填空, Q41-60)
    const clozeChoice = examData.language_use?.cloze || examData.cloze;
    if (clozeChoice && clozeChoice.questions) {
        clozeChoice.questions.forEach(q => {
            list.push({
                id: q.id,
                secKey: 'cloze',
                section: '完形填空',
                type: 'cloze_choice',
                passage: clozeChoice.passage || '',
                translation_zh: clozeChoice.passage_zh || '',
                question_text: `Question ${q.id}. 请选择填入完形空格 [ ${q.id} ] 的最佳词汇：`,
                options: q.options || {},
                options_zh: q.options_zh || {},
                answer: q.answer,
                word: q.word,
                analysis: q.analysis || ''
            });
        });
    }

    // 3.7 Grammar Fill-in (语法填空, Q61-70)
    const grammar = examData.language_use?.grammar_fill_in || examData.grammar_fill_in;
    if (grammar && grammar.questions) {
        grammar.questions.forEach(q => {
            const pw = q.prompt_word || q.prompt || '';
            list.push({
                id: q.id,
                secKey: 'grammar_fill_in',
                section: '语法填空',
                type: 'fill_in',
                passage: grammar.passage || '',
                translation_zh: grammar.passage_zh || '',
                question_text: `Question ${q.id}.`,
                answer: q.answer || q.word || '',
                word: q.word || '',
                prompt_word: pw,
                analysis: q.analysis || ''
            });
        });
    }

    // 3.75 Word Spelling (单词拼写, 2008-2010全国卷等)
    const ws = examData.language_use?.word_spelling;
    const wsQs = Array.isArray(ws) ? ws : (ws && Array.isArray(ws.questions) ? ws.questions : null);
    if (wsQs && wsQs.length > 0) {
        wsQs.forEach(q => {
            let rawSentence = (q.question_text || q.sentence || '').replace(/^Question\s*\d*[\.:\s]*/i, '').trim();
            list.push({
                id: q.id,
                secKey: 'word_spelling',
                section: '单词拼写 · Spelling',
                type: 'fill_in',
                passage: '',
                question_text: rawSentence ? `Question ${q.id}. ${rawSentence}` : `Question ${q.id}.`,
                question_text_zh: q.question_zh || (q.prompt_zh ? `中文提示: ${q.prompt_zh}` : ''),
                answer: q.answer || q.word || '',
                word: q.word || q.answer || '',
                prompt_word: q.prompt_zh || '',
                analysis: q.analysis || ''
            });
        });
    }

    // 3.8 Error Correction (短文改错, C1-C10)
    const ec = examData.language_use?.error_correction || examData.language_use?.proofreading || examData.error_correction || examData.writing?.proofreading;
    if (ec && (ec.corrections || ec.questions || ec.lines)) {
        let ecPassage = ec.passage || ec.content || '';
        if (!ecPassage && Array.isArray(ec.lines)) {
            ecPassage = ec.lines.map(l => (typeof l === 'string' ? l : (l.text || l.line || ''))).filter(Boolean).join('\n');
        } else if (!ecPassage && Array.isArray(ec.questions)) {
            ecPassage = ec.questions.map(q => (typeof q === 'string' ? q : (q.line || q.text || ''))).filter(Boolean).join('\n');
        }

        const rawList = ec.corrections || ec.questions || [];
        const CIRC_NUMS = ["", "①", "②", "③", "④", "⑤", "⑥", "⑦", "⑧", "⑨", "⑩", "⑪", "⑫"];
        rawList.forEach((c, idx) => {
            const cid = c.id !== undefined ? c.id : (idx + 1);
            const errorIndex = idx + 1;
            const circ = (errorIndex < CIRC_NUMS.length) ? CIRC_NUMS[errorIndex] : `[${cid}]`;
            list.push({
                id: `C${cid}`,
                numId: cid,
                errorIndex: errorIndex,
                circ_num: circ,
                secKey: 'error_correction',
                section: '短文改错',
                type: 'proofread',
                passage: ecPassage,
                translation_zh: ec.passage_zh || ec.translation_zh || '',
                annotated_html: ec.annotated_html || '',
                question_text: (c.type === 'correct' || c.corr_type === 'correct') ? `第 ${errorIndex} 处判断（${c.tag || '语法考点'}）：` : `第 ${errorIndex} 处错误修改（${c.tag || '语法考点'}）：`,
                corr_type: c.type || c.corr_type || 'modify',
                original: c.original || '',
                target: c.target || '',
                sentence: c.sentence || '',
                sentence_zh: c.sentence_zh || '',
                tag: c.tag || '语法考点',
                analysis: c.analysis || ''
            });
        });
    }

    // 4. Translation - Only add if actual content exists (CET-4/6 etc.)
    const trans = examData.translation;
    const hasTransContent = trans && typeof trans === 'object' && !Array.isArray(trans) && Boolean(
        (trans.source_zh && String(trans.source_zh).trim()) ||
        (trans.prompt_zh && String(trans.prompt_zh).trim()) ||
        (trans.passage_zh && String(trans.passage_zh).trim()) ||
        (trans.content && String(trans.content).trim()) ||
        (trans.target_en && String(trans.target_en).trim()) ||
        (trans.reference && String(trans.reference).trim())
    );
    if (hasTransContent) {
        const transQId = trans.id || 56;
        list.push({
            id: transQId,
            secKey: 'translation',
            section: '段落翻译',
            type: 'translation',
            question_text: `Question ${transQId}. 汉译英：请阅读下方中文段落，并在思考后查看参考译文与考点解析。`,
            question_text_zh: '段落翻译（中译英）',
            prompt_zh: trans.source_zh || trans.prompt_zh || trans.passage_zh || trans.content || '',
            reference: trans.target_en || trans.reference || '',
            vocabulary: trans.vocabulary || [],
            analysis: trans.analysis || ''
        });
    }

    // 5. Writing (支持新高考应用文 + 读后续写双大题独立切分)
    const writing = examData.writing;
    if (writing && typeof writing === 'object' && !Array.isArray(writing)) {
        const dirs = writing.directions || '';
        const essay = writing.essay || '';
        const essayZh = writing.essay_zh || '';
        const voc = writing.vocabulary || [];

        function cleanEssayText(txt) {
            if (!txt || typeof txt !== 'string') return '';
            return txt
                .replace(/^[【\[](?:practical_writing|applied_writing|continuation_writing|section_[12ab])[】\]](?:[:：\s]*(?:中文翻译|译文|范文))?\s*/gi, '')
                .replace(/^(?:第[一二两12]节|Section\s*[AB12]|Part\s*[AB12])[：:\s]*(?:应用文写作|读后续写|应用文|续写|短文写作|写作)?[：:\s]*\n*/gi, '')
                .replace(/^(?:读后续写|应用文写作|应用文|续写)[：:\s]*\n*/gi, '')
                .trim();
        }

        function cleanDirectionsText(d) {
            if (!d || typeof d !== 'string') return '';
            return d
                .replace(/^[【\[](?:practical_writing|applied_writing|continuation_writing|section_[12ab])[】\]]\s*/gi, '')
                .replace(/^第[一二三四1234]部分\s*[^\n]*\n+/i, '')
                .replace(/^(?:第[一二两12]节|Section\s*[AB12]|Part\s*[AB12])\s*[（\(]?(?:满分\s*\d+\s*分|共\d+小题|应用文写作|读后续写)?[）\)]?[：:\s]*\n*/gi, '')
                .replace(/^[（\(]?满分\s*\d+\s*分[）\)]?[：:\s]*\n*/gi, '')
                .replace(/^(?:应用文写作|读后续写)[（\(]?(?:满分\s*\d+\s*分)?[）\)]?[：:\s]*\n*/gi, '')
                .trim();
        }

        const subKeys = ['section_a', 'section_b', 'section_1', 'section_2', 'part_1', 'part_2', 'practical_writing', 'applied_writing', 'continuation_writing'].filter(
            k => writing[k] && typeof writing[k] === 'object'
        );

        const hasContinuation = !!(writing.continuation_writing && typeof writing.continuation_writing === 'object');

        // 识别双任务：通过 directions 分段或已有的 section 字典或 continuation_writing 或 section_2 标签
        const dirSplit = (dirs && typeof dirs === 'string')
            ? dirs.split(/\n*(?=(?:第二节|Section\s*B|Part\s*B|Part\s*2)[（\(：:\s]|\n+第二节\b|(?:【|\[)(?:continuation_writing|section_2|section_b)(?:】|\]))/i)
            : [];

        const hasSection2InEssay = /(?:【|\[)(?:continuation_writing|section_2|section_b)(?:】|\])/i.test(essay) || /(?:【|\[)(?:continuation_writing|section_2|section_b)(?:】|\])/i.test(essayZh);
        const isTwoPart = (dirSplit.length >= 2) || (subKeys.length >= 2) || hasContinuation || hasSection2InEssay;

        if (isTwoPart) {
            let d1 = '', d2 = '';
            if (dirSplit.length >= 2) {
                d1 = dirSplit[0].trim();
                d2 = dirSplit.slice(1).join('\n\n').trim();
            } else if (hasContinuation && writing.continuation_writing.directions) {
                d2 = writing.continuation_writing.directions;
                const pw = writing.practical_writing || writing.applied_writing;
                d1 = (pw && pw.directions) ? pw.directions : dirs;
            } else if (subKeys.length >= 2) {
                d1 = writing[subKeys[0]].directions || writing[subKeys[0]].prompt || dirs;
                d2 = writing[subKeys[1]].directions || writing[subKeys[1]].prompt || dirs;
            } else {
                d1 = dirs;
                d2 = dirs;
            }

            // 切分英文范文
            let e1 = '', e2 = '';
            let ez1 = '', ez2 = '';
            let v1 = voc, v2 = [];

            if (hasContinuation) {
                const cw = writing.continuation_writing;
                const pw = writing.practical_writing || writing.applied_writing;
                e2 = cw.essay || '';
                ez2 = cw.essay_zh || '';
                v2 = cw.vocabulary || [];
                e1 = (pw && pw.essay) ? pw.essay : essay;
                ez1 = (pw && pw.essay_zh) ? pw.essay_zh : essayZh;
                v1 = (pw && pw.vocabulary && pw.vocabulary.length > 0) ? pw.vocabulary : voc;
            } else if (subKeys.length >= 2 && writing[subKeys[0]].essay && writing[subKeys[1]].essay) {
                e1 = writing[subKeys[0]].essay;
                e2 = writing[subKeys[1]].essay;
                ez1 = writing[subKeys[0]].essay_zh || '';
                ez2 = writing[subKeys[1]].essay_zh || '';
                v1 = (Array.isArray(writing[subKeys[0]].vocabulary) && writing[subKeys[0]].vocabulary.length > 0) ? writing[subKeys[0]].vocabulary : voc;
                v2 = Array.isArray(writing[subKeys[1]].vocabulary) ? writing[subKeys[1]].vocabulary : [];
            } else if (essay.includes('***')) {
                const parts = essay.split('***');
                e1 = parts[0].trim();
                e2 = parts.slice(1).join('\n\n').trim();
            } else if (/(?:【(?:continuation_writing|section_2|section_b)】|\[(?:continuation_writing|section_2|section_b)\])/i.test(essay)) {
                const parts = essay.split(/(?:【(?:continuation_writing|section_2|section_b)】|\[(?:continuation_writing|section_2|section_b)\])/i);
                e1 = parts[0].trim();
                e2 = parts.slice(1).join('\n\n').trim();
            } else if (/(?=\n*(?:Paragraph\s*1:?|【第二节】|Section\s*B)\b)/i.test(essay)) {
                const parts = essay.split(/(?=\n*(?:Paragraph\s*1:?|【第二节】|Section\s*B)\b)/i);
                e1 = parts[0].trim();
                e2 = parts.slice(1).join('\n\n').trim();
            } else {
                e1 = essay;
                e2 = '';
            }

            // 切分范文中文翻译
            if (!ez1 && !ez2) {
                if (essayZh.includes('***')) {
                    const parts = essayZh.split('***');
                    ez1 = parts[0].trim();
                    ez2 = parts.slice(1).join('\n\n').trim();
                } else if (/(?:【(?:continuation_writing|section_2|section_b)】|\[(?:continuation_writing|section_2|section_b)\])/i.test(essayZh)) {
                    const parts = essayZh.split(/(?:【(?:continuation_writing|section_2|section_b)】|\[(?:continuation_writing|section_2|section_b)\])/i);
                    ez1 = parts[0].trim();
                    ez2 = parts.slice(1).join('\n\n').trim();
                } else if (/(?=\n*(?:第一段：?|段落\s*1:?|【第二节】|第二节[：:\s])\b)/i.test(essayZh)) {
                    const parts = essayZh.split(/(?=\n*(?:第一段：?|段落\s*1:?|【第二节】|第二节[：:\s])\b)/i);
                    ez1 = parts[0].trim();
                    ez2 = parts.slice(1).join('\n\n').trim();
                } else {
                    ez1 = essayZh;
                    ez2 = '';
                }
            }

            // 清洗所有范文与译文
            e1 = cleanEssayText(e1);
            ez1 = cleanEssayText(ez1);
            e2 = cleanEssayText(e2);
            ez2 = cleanEssayText(ez2);

            // 清洗题干
            d1 = cleanDirectionsText(d1);
            d2 = cleanDirectionsText(d2);

            const lastQ = list[list.length - 1];
            let baseId = 66;
            if (lastQ && typeof lastQ.id === 'number') {
                baseId = lastQ.id + 1;
            }
            const id1 = (subKeys.length >= 2 && writing[subKeys[0]].id) ? writing[subKeys[0]].id : baseId;
            const id2 = (subKeys.length >= 2 && writing[subKeys[1]].id) ? writing[subKeys[1]].id : (typeof id1 === 'number' ? id1 + 1 : `W2`);

            // 应用文写作
            list.push({
                id: id1,
                secKey: 'writing',
                section: '应用文写作',
                subSection: '应用文写作',
                score: 15,
                type: 'writing',
                question_text: `Question ${id1}. 应用文写作：请仔细阅读题目要求与提示，并在完成写作后查阅参考范文。`,
                question_text_zh: '应用文写作',
                directions: d1,
                directions_zh: (subKeys.length >= 2 && writing[subKeys[0]].directions_zh) || '',
                essay: e1,
                essay_zh: ez1,
                vocabulary: v1,
                analysis: (subKeys.length >= 2 && writing[subKeys[0]].analysis) || ''
            });

            // 读后续写
            list.push({
                id: id2,
                secKey: 'writing',
                section: '读后续写',
                subSection: '读后续写',
                score: 25,
                type: 'writing',
                question_text: `Question ${id2}. 读后续写：请仔细阅读故事材料与续写开头语，并在完成写作后查阅参考范文。`,
                question_text_zh: '读后续写',
                directions: d2,
                directions_zh: (subKeys.length >= 2 && writing[subKeys[1]].directions_zh) || '',
                essay: e2,
                essay_zh: ez2,
                vocabulary: v2,
                analysis: (subKeys.length >= 2 && writing[subKeys[1]].analysis) || ''
            });

        } else {
            const hasWritingContent = Boolean(
                (dirs && String(dirs).trim()) ||
                (essay && String(essay).trim()) ||
                (essayZh && String(essayZh).trim())
            );
            if (hasWritingContent) {
                const lastQ = list[list.length - 1];
                const defaultId = lastQ ? (typeof lastQ.id === 'number' ? lastQ.id + 1 : 57) : 57;
                const wId = writing.id || defaultId;
                list.push({
                    id: wId,
                    secKey: 'writing',
                    section: '短文写作',
                    subSection: '短文写作',
                    type: 'writing',
                    question_text: `Question ${wId}. 短文写作：请仔细阅读题目要求与提示，并在完成写作后查阅参考范文。`,
                    question_text_zh: '短文写作',
                    directions: cleanDirectionsText(dirs),
                    directions_zh: writing.directions_zh || '',
                    essay: cleanEssayText(essay),
                    essay_zh: cleanEssayText(essayZh),
                    vocabulary: voc,
                    analysis: writing.analysis || ''
                });
            }
        }
    }

    // Sort strictly by question ID to ensure chronological order across all years and exam formats
    list.sort((a, b) => {
        const idA = typeof a.id === 'number' ? a.id : parseInt(a.id, 10);
        const idB = typeof b.id === 'number' ? b.id : parseInt(b.id, 10);
        if (!isNaN(idA) && !isNaN(idB)) {
            return idA - idB;
        }
        return 0;
    });

    return list;
}

async function startWrittenExam(title, targetSecKey = 'cloze', opts = null) {
    let meta = (typeof findExamMeta === 'function') ? findExamMeta(title) : null;
    let level = meta ? meta.level : null;
    if (!level) {
        if (title.includes('雅思') || title.toLowerCase().includes('ielts')) level = 'ielts';
        else if (title.includes('考研') || title.toLowerCase().includes('kaoyan')) level = 'kaoyan';
        else if (title.includes('高考')) level = 'gaokao';
        else if (title.includes('六级')) level = 'cet6';
        else if (title.includes('四级')) level = 'cet4';
        else level = window.currentExamLevel || 'cet4';
    }
    const prevExamLevel = window.currentExamLevel;
    const prevKaoyanSubj = window.currentKaoyanSubjectFilter;
    const restoreLevelState = () => {
        window.currentExamLevel = prevExamLevel;
        if (prevKaoyanSubj) window.currentKaoyanSubjectFilter = prevKaoyanSubj;
        if (typeof window.syncLobbyLevelPillsUI === 'function') window.syncLobbyLevelPillsUI();
    };
    window.currentExamLevel = level;
    if (level === 'kaoyan' && title) {
        const isEng2 = title.includes('英语（二）') || title.includes('英语二') || title.toLowerCase().includes('eng2');
        const targetSubj = isEng2 ? 'ENG2' : 'ENG1';
        window.currentKaoyanSubjectFilter = targetSubj;
        try { window.__toyLS.setItem('toy_selected_kaoyan_subj', targetSubj); } catch(e) {}
        document.querySelectorAll('.level-tag-bind').forEach(el => {
            el.textContent = targetSubj === 'ENG2' ? '考研英语(二)' : '考研英语(一)';
        });
        if (typeof window.syncLobbyLevelPillsUI === 'function') {
            window.syncLobbyLevelPillsUI();
        }
    }
    const examIdx = getWrittenExamTrackIndex(title, level);
    const safeExamIdx = examIdx >= 0 ? examIdx : 0;
    if (window.ToyPermissions && !window.ToyPermissions.canAccessWrittenExam(safeExamIdx, 0, level)) {
        if (typeof window.ToyPermissions.shouldAwaitInitialSync === 'function' && window.ToyPermissions.shouldAwaitInitialSync()) {
            await window.ToyPermissions.ensureSynced(1200);
        }
        if (!window.ToyPermissions.canAccessWrittenExam(safeExamIdx, 0, level)) {
            restoreLevelState();
            window.ToyPermissions.showUnlockModal('written', { examIndex: safeExamIdx, questionIndex: 0, level: level });
            return;
        }
    }

    const reqId = (window._writtenStartSeqId = (window._writtenStartSeqId || 0) + 1);
    const navSeq = window._navActionSeqId || 0;

    if (typeof ensureExamDataLoaded === 'function') {
        const loaded = await ensureExamDataLoaded(title, null, 'written');
        if (!loaded) {
            restoreLevelState();
            return;
        }
        if (reqId !== window._writtenStartSeqId || (window._navActionSeqId || 0) !== navSeq) {
            restoreLevelState();
            return;
        }
    }

    currentWrittenExamTitle = title;
    window.currentWrittenExamTitle = title;
    const examData = (window.WRITTEN_EXAMS_MAP && window.WRITTEN_EXAMS_MAP[title]) ? window.WRITTEN_EXAMS_MAP[title] : null;
    currentWrittenQuestions = buildWrittenQuestionsList(examData);
    window.currentWrittenQuestions = currentWrittenQuestions;

    if (window.completedExams && window.completedExams[title] && window.completedExams[title].writtenAnswers) {
        const cleanWrittenAns = {};
        Object.entries(window.completedExams[title].writtenAnswers).forEach(([k, v]) => {
            if (v && !v._deleted) {
                cleanWrittenAns[k] = Object.assign({}, v);
            }
        });
        userWrittenAnswers[title] = cleanWrittenAns;
    } else if (!userWrittenAnswers[title]) {
        userWrittenAnswers[title] = {};
    }
    if (typeof window.hydrateWrittenArenaAnnotations === 'function') {
        window.hydrateWrittenArenaAnnotations(title);
    }

    let initialIndex = 0;
    if (opts && opts.initialQId !== undefined && opts.initialQId !== null) {
        const foundById = currentWrittenQuestions.findIndex(q => String(q.id) === String(opts.initialQId));
        if (foundById >= 0) initialIndex = foundById;
    } else if (targetSecKey && targetSecKey !== 'cloze') {
        const foundIdx = currentWrittenQuestions.findIndex(q => q.secKey === targetSecKey);
        if (foundIdx >= 0) initialIndex = foundIdx;
    }

    if (window.ToyPermissions) {
        const examIdx = getWrittenExamTrackIndex(title, level);
        const safeExamIdx = examIdx >= 0 ? examIdx : 0;
        if (!window.ToyPermissions.canAccessWrittenExam(safeExamIdx, 0, level)) {
            window.ToyPermissions.showUnlockModal('written', { examIndex: safeExamIdx, questionIndex: 0, level });
            return;
        }
        if (!window.ToyPermissions.canAccessWrittenExam(safeExamIdx, initialIndex, level)) {
            window.ToyPermissions.showUnlockModal('written', { examIndex: safeExamIdx, questionIndex: initialIndex, level });
            initialIndex = 0;
        }
    }

    const passageCardInit = document.getElementById('written-passage-card');
    if (passageCardInit) {
        passageCardInit._renderedPassageKey = '';
    }

    currentWrittenQIndex = initialIndex;
    window.currentWrittenQIndex = initialIndex;
    ['written-stage-card', 'written-q-h2', 'written-options-wrapper'].forEach(id => {
        const el = document.getElementById(id);
        if (el && el.classList) el.classList.remove('card-slide-forward', 'card-slide-backward');
    });
    const splitQuizEl = document.querySelector('.written-split-quiz');
    if (splitQuizEl && splitQuizEl.classList) {
        splitQuizEl.classList.remove('card-slide-forward', 'card-slide-backward');
    }

    switchView('written-arena');
    renderWrittenQuestion(initialIndex, { isArenaEntry: true });
}



/* === js/written_proofread.js === */
function showProofreadToast() {
    const toast = document.getElementById('proofread-toast');
    if (toast) {
        clearTimeout(toast._timer);
        toast.style.display = 'none';
    }
}

function getProofreadCircNum(cid, idx) {
    const CIRC_NUMS = ["", "①", "②", "③", "④", "⑤", "⑥", "⑦", "⑧", "⑨", "⑩", "⑪", "⑫"];
    const ord = (idx !== undefined && idx >= 0) ? idx + 1 : parseInt(cid);
    return (ord >= 1 && ord < CIRC_NUMS.length) ? CIRC_NUMS[ord] : `[${cid}]`;
}

function cleanProofreadRawPassage(p) {
    if (!p || typeof p !== 'string') return '';
    // 将行尾带的 [76], (76), 76. ______ 等题号标注与纯换行连接为自然英语段落
    let text = p.replace(/\s*(?:\[\d+\]|\(\d+\)|\b\d+[\.、]\s*_{2,}|\b\d+\.\s*_{2,})\s*(\r?\n|$)/g, ' ');
    // 清除正文中可能残留的孤立 [76] 或 (76)
    text = text.replace(/\[\d+\]|\(\d+\)/g, '');
    return text.replace(/[ \t]+/g, ' ').replace(/\n\s*\n/g, '\n\n').trim();
}

function computeProofreadSlices(passage, allProofread) {
    const sorted = [...allProofread].sort((a, b) => (parseInt(a.numId || a.id) || 0) - (parseInt(b.numId || b.id) || 0));
    let slices = [];
    let cursor = 0;

    sorted.forEach((item, idx) => {
        const cid = item.numId || parseInt(String(item.id).replace(/\D/g, '')) || 1;
        const ctype = item.corr_type || item.type || 'modify';
        const orig = item.original || '';
        const targ = item.target || '';
        const anal = item.analysis || '';
        const badge = getProofreadCircNum(cid, idx);

        if (ctype === 'add') {
            const mBetween = anal.match(/([a-zA-Z]+)\s*(?:与|和)\s*([a-zA-Z]+)\s*之间/);
            const mBefore = anal.match(/([a-zA-Z]+)\s*前/);
            const mAfter = anal.match(/([a-zA-Z]+)\s*后/);

            let insertPos = -1;
            if (mBetween) {
                const pat = new RegExp(`\\b${mBetween[1]}\\b\\s+\\b${mBetween[2]}\\b`, 'i');
                const sub = passage.slice(cursor);
                const m = sub.match(pat);
                if (m) insertPos = cursor + m.index + m[0].indexOf(' ') + 1;
            } else if (mBefore) {
                const pat = new RegExp(`\\b${mBefore[1]}\\b`, 'i');
                const sub = passage.slice(cursor);
                const m = sub.match(pat);
                if (m) insertPos = cursor + m.index;
            } else if (mAfter) {
                const pat = new RegExp(`\\b${mAfter[1]}\\b`, 'i');
                const sub = passage.slice(cursor);
                const m = sub.match(pat);
                if (m) insertPos = cursor + m.index + m[0].length;
            }
            if (insertPos === -1) insertPos = cursor;
            slices.push({ item, cid, ctype, start: insertPos, end: insertPos, orig: '', targ, badge });
            cursor = insertPos;
        } else if (ctype === 'delete' || ctype === 'modify') {
            const esc = orig.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const pat = new RegExp(`\\b${esc}\\b`, 'i');
            const sub = passage.slice(cursor);
            let m = sub.match(pat);
            let start, end;
            if (m) {
                start = cursor + m.index;
                end = start + m[0].length;
                cursor = end;
                slices.push({ item, cid, ctype, start, end, orig, targ, badge });
            }
        } else if (ctype === 'correct') {
            const rawSent = item.sentence || item.evidence || '';
            const sent = cleanProofreadRawPassage(rawSent).trim();
            if (sent) {
                const esc = sent.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/\s+/g, '\\s+');
                const pat = new RegExp(esc, 'i');
                const sub = passage.slice(cursor);
                let m = sub.match(pat);
                if (m) {
                    const start = cursor + m.index;
                    const end = start + m[0].length;
                    cursor = end;
                    slices.push({ item, cid, ctype: 'correct', start, end, orig: '', targ: '', badge });
                }
            }
        }
    });
    return slices;
}

function generateAnnotatedPassageClient(rawPassage, allProofread) {
    const passage = cleanProofreadRawPassage(rawPassage);
    if (!passage) return '';
    const slices = computeProofreadSlices(passage, allProofread);

    let htmlSlices = [];
    slices.forEach(sl => {
        if (sl.ctype === 'add') {
            const snippet = `<ruby class="corr-item corr-add" data-id="${sl.cid}"><span class="corr-caret">∧</span><rt class="corr-sub">${makeTextClickable(sl.targ)}</rt></ruby><sup class="corr-badge" data-id="${sl.cid}">${sl.badge}</sup> `;
            htmlSlices.push({ start: sl.start, end: sl.end, snippet });
        } else if (sl.ctype === 'delete') {
            const matched = passage.slice(sl.start, sl.end);
            const snippet = `<span class="corr-item corr-del" data-id="${sl.cid}"><del>${makeTextClickable(matched)}</del></span><sup class="corr-badge" data-id="${sl.cid}">${sl.badge}</sup>`;
            htmlSlices.push({ start: sl.start, end: sl.end, snippet });
        } else if (sl.ctype === 'modify') {
            const matched = passage.slice(sl.start, sl.end);
            const snippet = `<ruby class="corr-item corr-mod" data-id="${sl.cid}"><span class="corr-orig">${makeTextClickable(matched)}</span><rt class="corr-sub">${makeTextClickable(sl.targ)}</rt></ruby><sup class="corr-badge" data-id="${sl.cid}">${sl.badge}</sup>`;
            htmlSlices.push({ start: sl.start, end: sl.end, snippet });
        } else if (sl.ctype === 'correct') {
            const matched = passage.slice(sl.start, sl.end);
            const snippet = `<span class="corr-item corr-correct" data-id="${sl.cid}"><span class="corr-correct-text">${makeTextClickable(matched)}</span><sup class="corr-badge corr-badge-cor" data-id="${sl.cid}" title="正确行（原句无错）">${sl.badge} √</sup></span>`;
            htmlSlices.push({ start: sl.start, end: sl.end, snippet });
        }
    });

    htmlSlices.sort((a, b) => a.start - b.start || a.end - b.end);
    let result = '';
    let lastIdx = 0;
    for (const sl of htmlSlices) {
        result += makeTextClickable(passage.slice(lastIdx, sl.start));
        result += sl.snippet;
        lastIdx = sl.end;
    }
    result += makeTextClickable(passage.slice(lastIdx));
    return result;
}

function getProofreadStats(userAns, slices) {
    const editKeys = Object.keys(userAns || {}).filter(k =>
        (k.startsWith('C') || k.startsWith('custom_') || k.startsWith('add_')) &&
        userAns[k] && !userAns[k]._deleted
    );
    const total = editKeys.length;
    let correct = 0;

    editKeys.forEach(k => {
        const item = userAns[k];
        if (!item || item._deleted) return;
        if (k.startsWith('add_')) {
            const pos = (item.pos !== undefined) ? item.pos : parseInt(k.replace('add_', ''));
            const matched = slices.find(s => s.ctype === 'add' && Math.abs(s.start - pos) <= 4);
            if (matched && (item.selected || '').trim().toLowerCase() === (matched.targ || '').trim().toLowerCase()) {
                correct++;
            }
        } else if (k.startsWith('custom_')) {
            const pos = parseInt(k.replace('custom_', ''));
            const matched = slices.find(s => (s.ctype === 'modify' || s.ctype === 'delete') && Math.abs(s.start - pos) <= 1);
            if (matched) {
                if (item.userType === 'delete' && matched.ctype === 'delete') correct++;
                else if (item.userType === 'modify' && matched.ctype === 'modify' && (item.selected || '').trim().toLowerCase() === (matched.targ || '').trim().toLowerCase()) correct++;
            }
        } else {
            const matched = slices.find(s => s.item.id === k || `C${s.cid}` === k);
            if (matched) {
                if (item.userType === 'delete' && matched.ctype === 'delete') correct++;
                else if (item.userType === 'modify' && matched.ctype === 'modify' && (item.selected || '').trim().toLowerCase() === (matched.targ || '').trim().toLowerCase()) correct++;
                else if (item.userType === 'add' && matched.ctype === 'add' && (item.selected || '').trim().toLowerCase() === (matched.targ || '').trim().toLowerCase()) correct++;
            }
        }
    });

    return {
        total,
        correct,
        wrong: Math.max(0, total - correct)
    };
}

function buildActivePracticePassageHtml(passage, slices, userAns) {
    const isExam = !!window.isExamMode;

    // 收集所有补词项（包含匹配到考点题目的补词与自定义位置补词）
    const userAdds = [];
    slices.filter(s => s.ctype === 'add').forEach(s => {
        const key = `C${s.cid}`;
        const rawAns = userAns[key] || userAns[s.item.id];
        const ans = (rawAns && !rawAns._deleted) ? rawAns : null;
        if (ans && ans.userType === 'add' && ans.selected) {
            const isCor = (ans.selected || '').trim().toLowerCase() === (s.targ || '').trim().toLowerCase();
            userAdds.push({
                pos: s.start,
                key: s.item.id || key,
                selected: ans.selected,
                isCorrect: isCor
            });
        }
    });
    Object.keys(userAns).forEach(k => {
        if (k.startsWith('add_') && userAns[k] && !userAns[k]._deleted && userAns[k].selected) {
            const pos = (userAns[k].pos !== undefined) ? userAns[k].pos : parseInt(k.replace('add_', ''));
            const matchedAdd = slices.find(s => s.ctype === 'add' && Math.abs(s.start - pos) <= 4);
            const isCor = !!(matchedAdd && (userAns[k].selected || '').trim().toLowerCase() === (matchedAdd.targ || '').trim().toLowerCase());
            userAdds.push({
                pos: pos,
                key: k,
                selected: userAns[k].selected,
                isCorrect: isCor
            });
        }
    });

    let parts = [];
    let cur = 0;
    const wordRegex = /([a-zA-Z]+(?:['’\-][a-zA-Z]+)*)/g;
    let m;

    while ((m = wordRegex.exec(passage)) !== null) {
        if (m.index > cur) {
            parts.push({ type: 'text', content: passage.slice(cur, m.index) });
        }
        const wStart = m.index;
        const wEnd = m.index + m[0].length;
        const wText = m[0];

        // 检查当前词前是否有补词 (pos 在上个词末与当前词首之间)
        const addsBefore = userAdds.filter(a => a.pos >= cur && a.pos <= wStart);
        addsBefore.forEach(a => {
            if (!parts.some(p => p.type === 'user-add' && p.key === a.key)) {
                parts.push({
                    type: 'user-add',
                    key: a.key,
                    selected: a.selected,
                    isCorrect: a.isCorrect
                });
            }
        });

        // 检查该词是否匹配到参考考点
        const matchedSlice = slices.find(s => s.start === wStart && s.end === wEnd);
        const editKey = matchedSlice ? (matchedSlice.item.id || `C${matchedSlice.cid}`) : `custom_${wStart}`;
        const rawUserEdit = userAns[editKey];
        const userEdit = (rawUserEdit && !rawUserEdit._deleted) ? rawUserEdit : null;

        if (userEdit) {
            if (userEdit.userType === 'delete' || userEdit.selected === '') {
                const isCor = !!(matchedSlice && matchedSlice.ctype === 'delete');
                parts.push({
                    type: 'user-del',
                    key: editKey,
                    orig: wText,
                    isCorrect: isCor
                });
            } else {
                const isCor = !!(matchedSlice && matchedSlice.ctype === 'modify' && (userEdit.selected || '').trim().toLowerCase() === (matchedSlice.targ || '').trim().toLowerCase());
                parts.push({
                    type: 'user-mod',
                    key: editKey,
                    orig: wText,
                    selected: userEdit.selected,
                    isCorrect: isCor
                });
            }
        } else {
            parts.push({
                type: 'word',
                start: wStart,
                end: wEnd,
                word: wText,
                slice: matchedSlice
            });
        }

        // 检查当前词后紧随的补词 (pos 在当前词末附近)
        const addsAfter = userAdds.filter(a => a.pos > wStart && a.pos <= wEnd + 2);
        addsAfter.forEach(a => {
            if (!parts.some(p => p.type === 'user-add' && p.key === a.key)) {
                parts.push({
                    type: 'user-add',
                    key: a.key,
                    selected: a.selected,
                    isCorrect: a.isCorrect
                });
            }
        });

        cur = wEnd;
    }

    if (cur < passage.length) {
        parts.push({ type: 'text', content: passage.slice(cur) });
    }

    // 检查短文末尾是否有遗漏的补词
    const remainingAdds = userAdds.filter(a => a.pos >= cur);
    remainingAdds.forEach(a => {
        if (!parts.some(p => p.type === 'user-add' && p.key === a.key)) {
            parts.push({
                type: 'user-add',
                key: a.key,
                selected: a.selected,
                isCorrect: a.isCorrect
            });
        }
    });

    const escProof = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    let out = '';
    for (const p of parts) {
        if (p.type === 'text') {
            out += p.content.split('\n\n').map(para => para.split('\n').join('<br/>')).join('</p><p class="proofread-para">');
        } else if (p.type === 'word') {
            const errAttr = p.slice ? `data-error-id="${escProof(p.slice.item.id || `C${p.slice.cid}`)}"` : '';
            out += `<span class="proof-word dict-word" data-start="${p.start}" data-end="${p.end}" data-word="${escProof(p.word)}" ${errAttr}>${escProof(p.word)}</span>`;
        } else if (p.type === 'user-mod') {
            const safeKey = escProof(p.key);
            const safeOrig = escProof(p.orig);
            const safeSel = escProof(p.selected);
            if (isExam) {
                out += `<ruby class="proof-user-item proof-mod-word proof-exam-blue" data-edit-key="${safeKey}" data-orig="${safeOrig}" data-selected="${safeSel}"><span class="proof-orig-del">${safeOrig}</span><rt class="proof-sub-input">${safeSel}</rt></ruby>`;
            } else if (p.isCorrect) {
                out += `<ruby class="proof-user-item proof-mod-word proof-correct" data-edit-key="${safeKey}" data-orig="${safeOrig}" data-selected="${safeSel}"><span class="proof-orig-del">${safeOrig}</span><rt class="proof-sub-input">${safeSel} <span class="proof-sub-mark ok">✓</span></rt></ruby>`;
            } else {
                out += `<ruby class="proof-user-item proof-mod-word proof-wrong" data-edit-key="${safeKey}" data-orig="${safeOrig}" data-selected="${safeSel}"><span class="proof-orig-del">${safeOrig}</span><rt class="proof-sub-input">${safeSel} <span class="proof-sub-mark err">✕</span></rt></ruby>`;
            }
        } else if (p.type === 'user-del') {
            const safeKey = escProof(p.key);
            const safeOrig = escProof(p.orig);
            if (isExam) {
                out += `<span class="proof-user-item proof-del-word proof-exam-blue" data-edit-key="${safeKey}" data-orig="${safeOrig}"><del>${safeOrig}</del></span>`;
            } else if (p.isCorrect) {
                out += `<ruby class="proof-user-item proof-del-word proof-correct" data-edit-key="${safeKey}" data-orig="${safeOrig}"><del>${safeOrig}</del><rt class="proof-sub-input"><span class="proof-sub-mark ok">✓</span></rt></ruby>`;
            } else {
                out += `<ruby class="proof-user-item proof-del-word proof-wrong" data-edit-key="${safeKey}" data-orig="${safeOrig}"><del>${safeOrig}</del><rt class="proof-sub-input"><span class="proof-sub-mark err">✕</span></rt></ruby>`;
            }
        } else if (p.type === 'user-add') {
            const safeKey = escProof(p.key);
            const safeSel = escProof(p.selected);
            if (isExam) {
                out += `<ruby class="proof-user-item proof-add-word proof-exam-blue" data-edit-key="${safeKey}" data-selected="${safeSel}"><span class="proof-caret">∧</span><rt class="proof-sub-input">${safeSel}</rt></ruby> `;
            } else if (p.isCorrect) {
                out += `<ruby class="proof-user-item proof-add-word proof-correct" data-edit-key="${safeKey}" data-selected="${safeSel}"><span class="proof-caret">∧</span><rt class="proof-sub-input">${safeSel} <span class="proof-sub-mark ok">✓</span></rt></ruby> `;
            } else {
                out += `<ruby class="proof-user-item proof-add-word proof-wrong" data-edit-key="${safeKey}" data-selected="${safeSel}"><span class="proof-caret">∧</span><rt class="proof-sub-input">${safeSel} <span class="proof-sub-mark err">✕</span></rt></ruby> `;
            }
        }
    }
    return `<p class="proofread-para">${out}</p>`;
}

function dismissProofreadPopovers() {
    document.querySelectorAll('.word-action-popover').forEach(el => el.remove());
    document.querySelectorAll('.proof-word.proof-word-selected, .proof-user-item.selected').forEach(el => el.classList.remove('proof-word-selected', 'selected'));
}
window.dismissProofreadPopovers = dismissProofreadPopovers;

function bindProofreadWordInteractions(passageCard, passage, slices, allProofread, index) {
    if (!window._proofreadGlobalClickBound) {
        window._proofreadGlobalClickBound = true;
        document.addEventListener('click', (e) => {
            if (!e.target.closest('.word-action-popover') && !e.target.closest('.proof-word') && !e.target.closest('.proof-user-item')) {
                dismissProofreadPopovers();
            }
        });
    }

    const showPopoverAt = (targetEl, htmlContent) => {
        dismissProofreadPopovers();

        targetEl.classList.add('proof-word-selected');
        const popover = document.createElement('div');
        popover.className = 'word-action-popover';
        popover.innerHTML = htmlContent;
        document.body.appendChild(popover);

        const rect = targetEl.getBoundingClientRect();
        let top;
        if (rect.top < 120) {
            popover.classList.add('popover-flip-below');
            top = rect.bottom + window.scrollY;
        } else {
            top = rect.top + window.scrollY - 10;
        }
        let left = rect.left + window.scrollX + (rect.width / 2);
        const minLeft = 140;
        const maxLeft = (window.innerWidth || 360) - 140;
        left = Math.max(minLeft, Math.min(maxLeft, left));
        popover.style.top = `${top}px`;
        popover.style.left = `${left}px`;
        return popover;
    };

    // 1. 点击文中普通单词
    passageCard.querySelectorAll('.proof-word').forEach(wordEl => {
        wordEl.addEventListener('click', (e) => {
            if (window.isLookupMode) return;
            e.stopPropagation();

            const wStart = parseInt(wordEl.dataset.start);
            const wEnd = parseInt(wordEl.dataset.end);
            const wText = wordEl.dataset.word;

            const popover = showPopoverAt(wordEl, `
                <div class="popover-main-view">
                    <div class="popover-word-title">单词: <strong>${wText}</strong></div>
                    <div class="popover-actions-row">
                        <button type="button" class="popover-btn btn-mod" data-action="modify">✏️ 修改此词</button>
                        <button type="button" class="popover-btn btn-del" data-action="delete">✂️ 划除多余词</button>
                        <button type="button" class="popover-btn btn-add" data-action="add-after">∧ 词后补词</button>
                    </div>
                </div>
                <div class="popover-input-view" style="display:none;"></div>
            `);

            const mainView = popover.querySelector('.popover-main-view');
            const inputView = popover.querySelector('.popover-input-view');

            // ✏️ 修改此词
            popover.querySelector('.btn-mod').addEventListener('click', (ev) => {
                ev.stopPropagation();
                mainView.style.display = 'none';
                inputView.style.display = 'block';
                inputView.innerHTML = `
                    <div class="popover-input-header">将 “<strong>${wText}</strong>” 修改为：</div>
                    <div class="popover-input-box">
                        <input type="text" class="popover-text-input" placeholder="输入修改后的单词..." autofocus />
                        <button type="button" class="popover-submit-btn">确定</button>
                        <button type="button" class="popover-cancel-btn">取消</button>
                    </div>
                `;
                const inp = inputView.querySelector('.popover-text-input');
                const btnSub = inputView.querySelector('.popover-submit-btn');
                const btnCancel = inputView.querySelector('.popover-cancel-btn');
                inp.focus();
                inp.addEventListener('focus', () => {
                    setTimeout(() => {
                        popover.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    }, 220);
                });
                setTimeout(() => {
                    popover.scrollIntoView({ behavior: 'smooth', block: 'center' });
                }, 100);

                const submitMod = () => {
                    const val = (inp.value || '').trim();
                    if (!val) return;
                    popover.remove();
                    const matchedSlice = slices.find(s => s.start === wStart && s.end === wEnd);
                    if (matchedSlice) {
                        const targetQ = matchedSlice.item;
                        const isCor = (matchedSlice.ctype === 'modify') && checkIsCorrect(val, targetQ.target);
                        selectWrittenOption(targetQ.id, val, targetQ.target, { userType: 'modify', isCorrect: isCor });
                    } else {
                        if (!window.isExamMode && window.FeedbackEngine) window.FeedbackEngine.playWrong();
                        if (!userWrittenAnswers[currentWrittenExamTitle]) userWrittenAnswers[currentWrittenExamTitle] = {};
                        const nowTs = Date.now();
                        const customKey = `custom_${wStart}`;
                        userWrittenAnswers[currentWrittenExamTitle][customKey] = {
                            selected: val,
                            orig: wText,
                            userType: 'modify',
                            isCorrect: false,
                            ts: nowTs
                        };
                        if (currentWrittenExamTitle) {
                            if (!window.completedExams[currentWrittenExamTitle]) window.completedExams[currentWrittenExamTitle] = {};
                            window.completedExams[currentWrittenExamTitle].timestamp = nowTs;
                            if (!window.completedExams[currentWrittenExamTitle].writtenAnswers) {
                                window.completedExams[currentWrittenExamTitle].writtenAnswers = {};
                            }
                            Object.assign(window.completedExams[currentWrittenExamTitle].writtenAnswers, userWrittenAnswers[currentWrittenExamTitle]);
                            window.completedExams[currentWrittenExamTitle].writtenAnswers[customKey] = Object.assign({}, userWrittenAnswers[currentWrittenExamTitle][customKey]);
                            saveUserCloudData(currentWrittenExamTitle);
                        }
                    }
                    showProofreadToast(`✏️ 已修改：“${wText}” ➔ “${val}”`);
                    renderWrittenQuestion(index, { preserveScroll: true });
                };

                btnSub.addEventListener('click', submitMod);
                inp.addEventListener('keydown', (ke) => {
                    if (ke.key === 'Enter') submitMod();
                    if (ke.key === 'Escape') popover.remove();
                });
                btnCancel.addEventListener('click', () => popover.remove());
            });

            // ✂️ 划除多余词
            popover.querySelector('.btn-del').addEventListener('click', (ev) => {
                ev.stopPropagation();
                popover.remove();
                const matchedSlice = slices.find(s => s.start === wStart && s.end === wEnd);
                if (matchedSlice) {
                    const targetQ = matchedSlice.item;
                    const isCor = (matchedSlice.ctype === 'delete');
                    selectWrittenOption(targetQ.id, '', targetQ.target, { userType: 'delete', isCorrect: isCor });
                } else {
                    if (!window.isExamMode && window.FeedbackEngine) window.FeedbackEngine.playWrong();
                    if (!userWrittenAnswers[currentWrittenExamTitle]) userWrittenAnswers[currentWrittenExamTitle] = {};
                    const nowTs = Date.now();
                    const customKey = `custom_${wStart}`;
                    userWrittenAnswers[currentWrittenExamTitle][customKey] = {
                        selected: '',
                        orig: wText,
                        userType: 'delete',
                        isCorrect: false,
                        ts: nowTs
                    };
                    if (currentWrittenExamTitle) {
                        if (!window.completedExams[currentWrittenExamTitle]) window.completedExams[currentWrittenExamTitle] = {};
                        window.completedExams[currentWrittenExamTitle].timestamp = nowTs;
                        if (!window.completedExams[currentWrittenExamTitle].writtenAnswers) {
                            window.completedExams[currentWrittenExamTitle].writtenAnswers = {};
                        }
                        Object.assign(window.completedExams[currentWrittenExamTitle].writtenAnswers, userWrittenAnswers[currentWrittenExamTitle]);
                        window.completedExams[currentWrittenExamTitle].writtenAnswers[customKey] = Object.assign({}, userWrittenAnswers[currentWrittenExamTitle][customKey]);
                        saveUserCloudData(currentWrittenExamTitle);
                    }
                }
                showProofreadToast(`✂️ 已划除多余词 “${wText}”`);
                renderWrittenQuestion(index, { preserveScroll: true });
            });

            // ∧ 词后补词
            popover.querySelector('.btn-add').addEventListener('click', (ev) => {
                ev.stopPropagation();
                mainView.style.display = 'none';
                inputView.style.display = 'block';
                inputView.innerHTML = `
                    <div class="popover-input-header">在 “<strong>${wText}</strong>” 后补入单词：</div>
                    <div class="popover-input-box">
                        <input type="text" class="popover-text-input" placeholder="输入补入单词..." autofocus />
                        <button type="button" class="popover-submit-btn">确定</button>
                        <button type="button" class="popover-cancel-btn">取消</button>
                    </div>
                `;
                const inp = inputView.querySelector('.popover-text-input');
                const btnSub = inputView.querySelector('.popover-submit-btn');
                const btnCancel = inputView.querySelector('.popover-cancel-btn');
                inp.focus();
                inp.addEventListener('focus', () => {
                    setTimeout(() => {
                        popover.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    }, 220);
                });
                setTimeout(() => {
                    popover.scrollIntoView({ behavior: 'smooth', block: 'center' });
                }, 100);

                const submitAdd = () => {
                    const val = (inp.value || '').trim();
                    if (!val) return;
                    popover.remove();
                    const matchedAdd = slices.find(s => s.ctype === 'add' && Math.abs(s.start - wEnd) <= 2);
                    if (matchedAdd) {
                        const targetQ = matchedAdd.item;
                        const isCor = (matchedAdd.ctype === 'add') && checkIsCorrect(val, targetQ.target);
                        selectWrittenOption(targetQ.id, val, targetQ.target, { userType: 'add', pos: matchedAdd.start, isCorrect: isCor });
                    } else {
                        if (!window.isExamMode && window.FeedbackEngine) window.FeedbackEngine.playWrong();
                        if (!userWrittenAnswers[currentWrittenExamTitle]) userWrittenAnswers[currentWrittenExamTitle] = {};
                        const nowTs = Date.now();
                        const addKey = `add_${wEnd}`;
                        userWrittenAnswers[currentWrittenExamTitle][addKey] = {
                            selected: val,
                            userType: 'add',
                            pos: wEnd,
                            isCorrect: false,
                            ts: nowTs
                        };
                        if (currentWrittenExamTitle) {
                            if (!window.completedExams[currentWrittenExamTitle]) window.completedExams[currentWrittenExamTitle] = {};
                            window.completedExams[currentWrittenExamTitle].timestamp = nowTs;
                            if (!window.completedExams[currentWrittenExamTitle].writtenAnswers) {
                                window.completedExams[currentWrittenExamTitle].writtenAnswers = {};
                            }
                            Object.assign(window.completedExams[currentWrittenExamTitle].writtenAnswers, userWrittenAnswers[currentWrittenExamTitle]);
                            window.completedExams[currentWrittenExamTitle].writtenAnswers[addKey] = Object.assign({}, userWrittenAnswers[currentWrittenExamTitle][addKey]);
                            saveUserCloudData(currentWrittenExamTitle);
                        }
                    }
                    showProofreadToast(`🎉 成功在此补入：“${val}”`);
                    renderWrittenQuestion(index, { preserveScroll: true });
                };

                btnSub.addEventListener('click', submitAdd);
                inp.addEventListener('keydown', (ke) => {
                    if (ke.key === 'Enter') submitAdd();
                    if (ke.key === 'Escape') popover.remove();
                });
                btnCancel.addEventListener('click', () => popover.remove());
            });
        });
    });

    // 2. 点击已修改/已划除/已补词项 (允许撤回还原或再次编辑)
    passageCard.querySelectorAll('.proof-user-item').forEach(userEl => {
        userEl.addEventListener('click', (e) => {
            if (window.isLookupMode) return;
            e.stopPropagation();

            const editKey = userEl.dataset.editKey;
            const orig = userEl.dataset.orig || '';
            const selected = userEl.dataset.selected || '';

            let desc = '';
            if (userEl.classList.contains('proof-mod-word')) {
                desc = `“${orig}” ➔ “${selected}”`;
            } else if (userEl.classList.contains('proof-del-word')) {
                desc = `已划除 “${orig}”`;
            } else {
                desc = `已插入 “${selected}”`;
            }

            const popover = showPopoverAt(userEl, `
                <div class="popover-main-view">
                    <div class="popover-word-title">当前修改: <strong>${desc}</strong></div>
                    <div class="popover-actions-row">
                        <button type="button" class="popover-btn btn-revert" style="color:#ef4444; border-color:#fca5a5;">↺ 还原为原文</button>
                    </div>
                </div>
            `);

            popover.querySelector('.btn-revert').addEventListener('click', (ev) => {
                ev.stopPropagation();
                popover.remove();
                if (userWrittenAnswers[currentWrittenExamTitle] && userWrittenAnswers[currentWrittenExamTitle][editKey]) {
                    delete userWrittenAnswers[currentWrittenExamTitle][editKey];
                    if (currentWrittenExamTitle) {
                        const nowTs = Date.now();
                        if (!window.completedExams[currentWrittenExamTitle]) window.completedExams[currentWrittenExamTitle] = {};
                        window.completedExams[currentWrittenExamTitle].timestamp = nowTs;
                        if (!window.completedExams[currentWrittenExamTitle].writtenAnswers) {
                            window.completedExams[currentWrittenExamTitle].writtenAnswers = {};
                        }
                        Object.assign(window.completedExams[currentWrittenExamTitle].writtenAnswers, userWrittenAnswers[currentWrittenExamTitle]);
                        window.completedExams[currentWrittenExamTitle].writtenAnswers[editKey] = {
                            _deleted: true,
                            ts: nowTs
                        };
                        saveUserCloudData(currentWrittenExamTitle);
                    }
                    updateDashboardStats();
                    submitUserScore();
                }
                showProofreadToast('↺ 已撤销修改，恢复为原文');
                renderWrittenQuestion(index, { preserveScroll: true });
            });
        });
    });

    passageCard.querySelectorAll('.proof-mark-tag').forEach(tag => {
        tag.addEventListener('click', (e) => {
            e.stopPropagation();
            const prev = tag.previousElementSibling || tag.closest('.proof-user-item');
            if (prev && (prev.classList.contains('proof-user-item') || prev.closest('.proof-user-item'))) {
                const target = prev.classList.contains('proof-user-item') ? prev : prev.closest('.proof-user-item');
                target.click();
            }
        });
    });
}

function renderActiveProofreadPassage(passageCard, q, index) {
    const allProofread = (currentWrittenQuestions || []).filter(item => item.type === 'proofread');
    const cleanedPassage = cleanProofreadRawPassage(q.passage);
    const slices = computeProofreadSlices(cleanedPassage, allProofread);
    const userAns = userWrittenAnswers[currentWrittenExamTitle] || {};

    const activeHtml = buildActivePracticePassageHtml(cleanedPassage, slices, userAns);

    const isExam = !!window.isExamMode;
    passageCard.innerHTML = `
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px;">
            <div style="font-size:12.5px; font-weight:700; color:#0284c7; letter-spacing:0.02em;">
                📄 短文改错（点击文中单词即可修改）
            </div>
        </div>
        <div class="proofread-interactive-body">
            ${activeHtml}
        </div>
    `;

    bindProofreadWordInteractions(passageCard, cleanedPassage, slices, allProofread, index);
}

function renderRevealedProofreadPassage(passageCard, q, index) {
    const allProofread = (currentWrittenQuestions || []).filter(item => item.type === 'proofread');
    const annotatedHtml = generateAnnotatedPassageClient(q.passage, allProofread);

    const activeNumId = q.numId || parseInt(String(q.id).replace(/\D/g, '')) || 1;

    let streamCardsHtml = '';
    allProofread.forEach((item, idx) => {
        const itemNum = item.numId || parseInt(String(item.id).replace(/\D/g, '')) || 1;
        const circ = item.circ_num || getProofreadCircNum(itemNum, idx);
        const ctype = item.corr_type || 'modify';
        const typeClass = ctype === 'modify' ? 'mod' : (ctype === 'delete' ? 'del' : (ctype === 'correct' ? 'cor' : 'add'));
        const typeText = ctype === 'modify' ? '修改' : (ctype === 'delete' ? '删除' : (ctype === 'correct' ? '正确行' : '增加'));
        const diff = item.diff_display || (
            ctype === 'correct'
                ? '✔️ 原文正确（无需修改）'
                : (ctype === 'delete' 
                    ? `${item.original} ➔ ＼` 
                    : (ctype === 'add' 
                        ? `∧ ➔ ${item.target}` 
                        : `${item.original} ➔ ${item.target}`))
        );
        const isActive = (itemNum === activeNumId);

        streamCardsHtml += `
            <div class="proofread-stream-card ${isActive ? 'active-stream-card' : ''}" id="proofread-card-${itemNum}" data-num="${itemNum}">
                <div class="stream-card-header">
                    <div style="display:flex; align-items:center; gap:8px;">
                        <span class="stream-circ-tag">${circ}</span>
                        <span class="stream-diff-badge">${diff}</span>
                        <span class="stream-type-tag ${typeClass}">${typeText}</span>
                    </div>
                    <span style="font-size:12px; font-weight:700; color:#0284c7; background:#e0f2fe; padding:3px 10px; border-radius:8px;">🏷️ ${item.tag || '语法考点'}</span>
                </div>
                <div class="stream-card-body">
                    ${typeof formatInlineAnalysisMarkdown === 'function' ? formatInlineAnalysisMarkdown(item.analysis || '暂无详细学术解析。', true) : (item.analysis || '暂无详细学术解析。')}
                </div>
            </div>
        `;
    });

    passageCard.innerHTML = `
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px; flex-wrap:wrap; gap:8px;">
            <div style="display:flex; align-items:center; gap:8px;">
                <div style="font-size:12px; font-weight:700; color:var(--accent-gold); text-transform:uppercase; letter-spacing:0.04em;">
                    🛠️ 短文改错 (点击单词可联动下方全题精析)
                </div>
                <span style="font-size:11.5px; font-weight:700; color:#10b981; background:#dcfce7; padding:2px 8px; border-radius:6px;">已呈现参考标准答案</span>
            </div>
        </div>
        <div class="proofread-manuscript-body">
            <p class="proofread-para">${annotatedHtml.split(/\n\n+/).join('</p><p class="proofread-para">')}</p>
        </div>
        <div class="proofread-analysis-section">
            <div class="proofread-analysis-header">
                <div style="display:flex; align-items:center; gap:6px;">
                    <span class="proofread-analysis-title">🔍 全题 10 处考点逐题精析</span>
                    <span class="proofread-analysis-hint">点击卡片联动正文对应位置</span>
                </div>
            </div>
            <div class="proofread-stream-container">
                ${streamCardsHtml}
            </div>
        </div>
    `;

    // 绑定考点卡片点击事件
    passageCard.querySelectorAll('.proofread-stream-card').forEach(card => {
        card.addEventListener('click', () => {
            const itemNum = parseInt(card.dataset.num);
            if (itemNum) highlightProofreadItem(itemNum);
        });
    });

    const activeItemEl = passageCard.querySelector(`.corr-item[data-id="${activeNumId}"]`);
    if (activeItemEl) {
        activeItemEl.classList.add('corr-flash-focus');
    }

    passageCard.querySelectorAll('.corr-item, .corr-badge').forEach(el => {
        el.addEventListener('click', (e) => {
            if (window.isLookupMode) return;
            e.stopPropagation();
            const targetId = parseInt(el.dataset.id);
            if (targetId) {
                highlightProofreadItem(targetId);
            }
        });
    });
}

function highlightProofreadItem(itemNum) {
    if (!itemNum) return;

    // 1. 下方卡片激活与平滑滚动
    const passPaneEl = document.querySelector('.written-split-passage');
    document.querySelectorAll('.proofread-stream-card').forEach(c => {
        if (parseInt(c.dataset.num) === itemNum) {
            c.classList.add('active-stream-card');
            scrollElementIntoPane(c, passPaneEl);
        } else {
            c.classList.remove('active-stream-card');
        }
    });

    // 2. 上方文章对应单词动画闪烁
    document.querySelectorAll('.corr-item').forEach(el => {
        if (parseInt(el.dataset.id) === itemNum) {
            el.classList.add('corr-flash-focus');
            setTimeout(() => el.classList.remove('corr-flash-focus'), 1600);
        } else {
            el.classList.remove('corr-flash-focus');
        }
    });
}
window.highlightProofreadItem = highlightProofreadItem;



/* === js/written_subjective.js === */
// ==========================================================================
// Written Subjective Formatting & Analysis Markdown Engine (js/written_subjective.js)
// ==========================================================================
function formatWritingInstructions(text) {
    if (!text || typeof text !== 'string') return '';
    // 过滤纯下划线占位行
    const lines = text.split(/\n+/).map(l => l.trim()).filter(l => l && !/^_{3,}$/.test(l));
    let html = '';

    lines.forEach((line) => {
        // 1. Section Header / Leaked Paper Header / Standalone "Directions:"
        if (/^Directions\s*:?\s*$/i.test(line) ||
            /^[【\[](?:practical_writing|applied_writing|continuation_writing|section_[12ab])[】\]]/i.test(line) ||
            /^第[一二三四1234]部分[^\n]*$/i.test(line) ||
            /^(?:第[一二两12]节|Section\s*[AB12]|Part\s*[AB12])[^\n]*(?:满分\s*\d+\s*分|共\d+小题|应用文写作|读后续写|短文写作|短文改错|语法填空|完形填空)/i.test(line) ||
            /^(?:第[一二两12]节|Section\s*[AB12]|Part\s*[AB12])[（\(]?(?:满分\s*\d+\s*分)?[）\)]?[：:\s]*$/i.test(line) ||
            /^[（\(]?满分\s*\d+\s*分[）\)]?[：:\s]*$/i.test(line) ||
            /^(?:应用文写作|读后续写)[（\(]?(?:满分\s*\d+\s*分)?[）\)]?[：:\s]*$/i.test(line)) {
            return;
        }
        line = line.replace(/^Directions\s*:\s*/i, '').trim();
        if (!line) return;

        // 2. Caution / Note (注意：, Note:, etc.)
        if (/^(?:注意[：:]?|Note[：:]?)/i.test(line)) {
            html += `<div class="writing-note-title">${makeTextClickable(line)}</div>`;
            return;
        }

        // 3. List item (1. ..., 1) ..., (1) ..., 1、...)
        const listPrefixMatch = line.match(/^((?:\(\d+\)|\d+[\.\)、]|\([a-zA-Z]\)|[a-zA-Z]\))\s*)(.*)$/);
        if (listPrefixMatch) {
            html += `<div class="writing-list-item"><span style="color:#007AFF; font-weight:700; margin-right:5px;">${listPrefixMatch[1].trim()}</span>${makeTextClickable(listPrefixMatch[2])}</div>`;
            return;
        }

        // 4. English story narrative paragraphs (e.g. story in Section B)
        if (/^[A-Za-z“"']/.test(line)) {
            html += `<p class="writing-en-para">${makeTextClickable(line)}</p>`;
            return;
        }

        // 5. Regular Chinese paragraph (prompts, requirements)
        html += `<p class="writing-zh-para">${makeTextClickable(line)}</p>`;
    });

    return html;
}

function parseWritingDirections(text, q) {
    if (!text || typeof text !== 'string') {
        return { instructionsHtml: '', answerSheetHtml: '' };
    }

    // 1. Continuation writing (Paragraph 1 & 2)
    const para1Match = text.match(/(?:^|\n)\s*(Paragraph\s*1:?[^\n]*)/i);
    const para2Match = text.match(/(?:^|\n)\s*(Paragraph\s*2:?[^\n]*)/i);
    if (para1Match && para2Match) {
        const splitIdx = text.indexOf(para1Match[0]);
        const instrText = text.substring(0, splitIdx).trim();
        const p1Text = para1Match[1].trim();
        const p2Text = para2Match[1].trim();

        const instructionsHtml = formatWritingInstructions(instrText);
        const answerSheetHtml = `
            <div class="writing-answer-sheet">
                <div class="sheet-header-badge"><div class="ios-subj-header-left"><span class="ios-subj-accent-bar"></span><span class="ios-subj-header-title">考场答题纸</span></div></div>
                <div class="sheet-continuation-block">
                    <div class="sheet-para-tag">第一段作答区 · PARAGRAPH 1</div>
                    <div class="sheet-starter-line">${makeTextClickable(p1Text)}</div>
                    <div class="sheet-ruled-lines">
                        <div class="sheet-ruled-line"></div>
                        <div class="sheet-ruled-line"></div>
                        <div class="sheet-ruled-line"></div>
                    </div>
                </div>
                <div class="sheet-continuation-block">
                    <div class="sheet-para-tag">第二段作答区 · PARAGRAPH 2</div>
                    <div class="sheet-starter-line">${makeTextClickable(p2Text)}</div>
                    <div class="sheet-ruled-lines">
                        <div class="sheet-ruled-line"></div>
                        <div class="sheet-ruled-line"></div>
                        <div class="sheet-ruled-line"></div>
                    </div>
                </div>
            </div>
        `;
        return { instructionsHtml, answerSheetHtml };
    }

    // 2. Letter / Email format (Dear ..., optionally preceded by Date e.g. June 8, 2008)
    const dearMatch = text.match(/(?:^|\n)\s*(?:([A-Z][a-z]+\s+\d{1,2},\s+\d{4})\s*\n+)?\s*(Dear[^\n,:]{1,50}[,:])/i);
    if (dearMatch) {
        const splitIdx = text.indexOf(dearMatch[0]);
        const instrText = text.substring(0, splitIdx).trim();
        const templateText = text.substring(splitIdx).trim();

        const dateStr = dearMatch[1] ? dearMatch[1].trim() : '';
        const salutation = dearMatch[2].trim();
        const afterSalutation = templateText.substring(templateText.indexOf(salutation) + salutation.length).trim();

        let signoffLines = [];
        let bodyLines = [];
        let closerLines = [];
        const rawLines = afterSalutation.split(/\n+/).map(l => l.trim()).filter(Boolean);

        // 优先从后往前识别签名落款（Yours, / Best regards, / Li Hua 等）
        let signoffStart = -1;
        for (let i = rawLines.length - 1; i >= 0; i--) {
            const line = rawLines[i];
            const isSignoffWord = /^(?:Yours\s*(?:sincerely|faithfully|truly)?|Best\s*(?:regards|wishes)?|With\s+best\s+wishes|Sincerely|Warm\s*regards|Regards|Cheers)[,:\s]*$/i.test(line);
            if (isSignoffWord) {
                signoffStart = i;
                break;
            }
        }

        const isCloserLine = (line) => {
            return /^(?:(?:I\s*(?:am\s*)?)?look(?:ing)?\s*forward\s*to\s*[^\n]+|Thank\s*you\s*[^\n]+|Wish(?:ing)?\s+you\s+[^\n]+|Hope\s+to\s+hear\s*[^\n]+)[,\.\!]?$/i.test(line);
        };

        if (signoffStart !== -1) {
            signoffLines = rawLines.slice(signoffStart).filter(l => !l.startsWith('_'));
            const beforeSignoff = rawLines.slice(0, signoffStart);
            beforeSignoff.forEach((line, idx) => {
                if (isCloserLine(line) || (idx === beforeSignoff.length - 1 && /结束语已为你写好|结尾已为你写好/.test(instrText))) {
                    closerLines.push(line);
                } else {
                    bodyLines.push(line);
                }
            });
        } else {
            let foundSignoff = false;
            for (let i = 0; i < rawLines.length; i++) {
                const line = rawLines[i];
                const isSignoff = /^(?:Yours|Best|Sincerely)/i.test(line);
                if (isSignoff) {
                    foundSignoff = true;
                    signoffLines.push(line);
                } else if (foundSignoff) {
                    if (!line.startsWith('_')) signoffLines.push(line);
                } else if (isCloserLine(line) || (i === rawLines.length - 1 && /结束语已为你写好|结尾已为你写好/.test(instrText))) {
                    closerLines.push(line);
                } else {
                    bodyLines.push(line);
                }
            }
        }

        let starterText = '';
        bodyLines.forEach(l => {
            const cleaned = l.replace(/_{3,}/g, '').trim();
            if (cleaned) {
                if (starterText) starterText += ' ' + cleaned;
                else starterText = cleaned;
            }
        });

        const instructionsHtml = formatWritingInstructions(instrText);
        const answerSheetHtml = `
            <div class="writing-answer-sheet">
                <div class="sheet-header-badge"><div class="ios-subj-header-left"><span class="ios-subj-accent-bar"></span><span class="ios-subj-header-title">考场答题纸</span></div></div>
                ${dateStr ? `<div style="text-align:right; font-size:14px; color:#1C1C1E; margin-bottom:4px; line-height:30px; border-bottom:1px solid rgba(60, 60, 67, 0.18);">${makeTextClickable(dateStr)}</div>` : ''}
                <div class="sheet-salutation">${makeTextClickable(salutation)}</div>
                ${starterText ? `<div class="sheet-starter-line">${makeTextClickable(starterText)}</div>` : ''}
                <div class="sheet-ruled-lines">
                    <div class="sheet-ruled-line">${!starterText ? '<span class="sheet-indent-hint"></span>' : ''}</div>
                    <div class="sheet-ruled-line"></div>
                    <div class="sheet-ruled-line"></div>
                    <div class="sheet-ruled-line"></div>
                    <div class="sheet-ruled-line"></div>
                </div>
                ${closerLines.length > 0 ? closerLines.map(c => `<div class="sheet-closer-line">${makeTextClickable(c)}</div>`).join('') : ''}
                ${signoffLines.length > 0 ? `
                    <div class="sheet-signoff-box">
                        ${signoffLines.map(s => `<div class="sheet-signoff-line">${makeTextClickable(s)}</div>`).join('')}
                    </div>
                ` : `
                    <div class="sheet-ruled-line"></div>
                `}
            </div>
        `;
        return { instructionsHtml, answerSheetHtml };
    }

    // 3. Standalone Title (e.g. "Youth and Me" or "My Views on Filming Short Videos on Campus" followed by underscores)
    const titleWithUndMatch = text.match(/(?:^|\n)\s*([A-Za-z0-9\s:,'"-]{4,80})\s*\n+_{3,}/);
    if (titleWithUndMatch) {
        const splitIdx = text.indexOf(titleWithUndMatch[0]);
        const instrText = text.substring(0, splitIdx).trim();
        const essayTitle = titleWithUndMatch[1].trim();

        const instructionsHtml = formatWritingInstructions(instrText);
        const answerSheetHtml = `
            <div class="writing-answer-sheet">
                <div class="sheet-header-badge"><div class="ios-subj-header-left"><span class="ios-subj-accent-bar"></span><span class="ios-subj-header-title">考场答题纸</span></div></div>
                <div class="sheet-title">${makeTextClickable(essayTitle)}</div>
                <div class="sheet-ruled-lines">
                    <div class="sheet-ruled-line"><span class="sheet-indent-hint"></span></div>
                    <div class="sheet-ruled-line"></div>
                    <div class="sheet-ruled-line"></div>
                    <div class="sheet-ruled-line"></div>
                    <div class="sheet-ruled-line"></div>
                </div>
            </div>
        `;
        return { instructionsHtml, answerSheetHtml };
    }

    // 4. Default / General Writing (e.g. Kaoyan Part A & B / CET-4 / CET-6 prompt)
    const cleanText = text.replace(/_{3,}/g, '').trim();
    const instructionsHtml = formatWritingInstructions(cleanText);

    const essayLines = (q && typeof q.essay === 'string')
        ? q.essay.split(/\n+/).map(l => l.trim()).filter(Boolean)
        : [];
    const firstEssayLine = essayLines[0] || '';

    // 4a. Notice format (e.g. Kaoyan Part A Notice)
    if (/^Notice$/i.test(firstEssayLine) || /\bwrite\s+a\s+notice\b/i.test(cleanText)) {
        const tailLines = essayLines.slice(-2).filter(l =>
            /^(?:Li\s*Ming|Li\s*Hua|(?:The\s+)?Students?'?\s*Union|(?:The\s+)?Postgraduates?'?\s*Association|(?:The\s+)?Youth\s+Volunteer\s+Association|[A-Z][a-z]+\s+\d{1,2},?\s*\d{4})[,\.]?$/i.test(l)
        );
        const answerSheetHtml = `
            <div class="writing-answer-sheet">
                <div class="sheet-header-badge"><div class="ios-subj-header-left"><span class="ios-subj-accent-bar"></span><span class="ios-subj-header-title">考场答题纸</span></div></div>
                <div class="sheet-title">Notice</div>
                <div class="sheet-ruled-lines">
                    <div class="sheet-ruled-line"><span class="sheet-indent-hint"></span></div>
                    <div class="sheet-ruled-line"></div>
                    <div class="sheet-ruled-line"></div>
                    <div class="sheet-ruled-line"></div>
                    <div class="sheet-ruled-line"></div>
                </div>
                ${tailLines.length > 0 ? `
                    <div class="sheet-signoff-box">
                        ${tailLines.map(s => `<div class="sheet-signoff-line">${makeTextClickable(s)}</div>`).join('')}
                    </div>
                ` : `
                    <div class="sheet-ruled-line"></div>
                `}
            </div>
        `;
        return { instructionsHtml, answerSheetHtml };
    }

    // 4b. Letter / Email format inferred from prompt or model essay (e.g. Kaoyan Part A Email/Letter)
    if (/^Dear\s+[^\n,:]{1,50}[,:]/i.test(firstEssayLine) ||
        /\bwrite\s+an?\s+(?:email|letter|reply)\b/i.test(cleanText) ||
        /Use\s+[“"']?(?:Li\s*(?:Ming|Hua|Ping)|Zhang\s*Wei|Wang\s*Ming)[”"']?/i.test(cleanText)) {
        const salutation = /^Dear\s+[^\n,:]{1,50}[,:]/i.test(firstEssayLine) ? firstEssayLine : 'Dear Sir or Madam,';
        let signoffLines = essayLines.slice(-2).filter(l =>
            /^(?:Yours\s*(?:sincerely|faithfully|truly|cordially)?|Sincerely(?:\s+yours)?|Best\s*(?:regards|wishes)?|Li\s*(?:Ming|Hua|Ping)|Zhang\s*Wei|Wang\s*Ming)[,:\.]?$/i.test(l)
        );
        if (signoffLines.length === 0) {
            const defaultSigner = /Zhang\s*Wei/i.test(cleanText) ? 'Zhang Wei' : (/Wang\s*Ming/i.test(cleanText) ? 'Wang Ming' : (/Li\s*Hua/i.test(cleanText) ? 'Li Hua' : 'Li Ming'));
            signoffLines = ['Yours sincerely,', defaultSigner];
        }
        const answerSheetHtml = `
            <div class="writing-answer-sheet">
                <div class="sheet-header-badge"><div class="ios-subj-header-left"><span class="ios-subj-accent-bar"></span><span class="ios-subj-header-title">考场答题纸</span></div></div>
                <div class="sheet-salutation">${makeTextClickable(salutation)}</div>
                <div class="sheet-ruled-lines">
                    <div class="sheet-ruled-line"><span class="sheet-indent-hint"></span></div>
                    <div class="sheet-ruled-line"></div>
                    <div class="sheet-ruled-line"></div>
                    <div class="sheet-ruled-line"></div>
                    <div class="sheet-ruled-line"></div>
                </div>
                <div class="sheet-signoff-box">
                    ${signoffLines.map(s => `<div class="sheet-signoff-line">${makeTextClickable(s)}</div>`).join('')}
                </div>
            </div>
        `;
        return { instructionsHtml, answerSheetHtml };
    }

    // 4c. Standard Essay format (Kaoyan Part B / CET-4 / CET-6) — 无预设答题纸内容时不生成空白考场答题纸
    return { instructionsHtml, answerSheetHtml: '' };
}

function formatModelEssayHtml(text) {
    if (!text || typeof text !== 'string') return '';
    text = text
        .replace(/^[【\[](?:practical_writing|applied_writing|continuation_writing|section_[12ab])[】\]](?:[:：\s]*(?:中文翻译|译文|范文))?\s*/gi, '')
        .replace(/^(?:第[一二两12]节|Section\s*[AB12]|Part\s*[AB12])[：:\s]*(?:应用文写作|读后续写|应用文|续写|短文写作|写作)?[：:\s]*\n*/gi, '')
        .replace(/^(?:读后续写|应用文写作|应用文|续写)[：:\s]*\n*/gi, '');

    const rawLines = text.split(/\n+/).map(l => l.trim()).filter(Boolean);
    if (rawLines.length === 0) return '';

    const isEnSignoffLine = (line, idx, total) => {
        if (/^(?:Yours\s*(?:sincerely|faithfully|truly|cordially)?|Sincerely(?:\s+yours)?|Best\s*(?:regards|wishes)?|With\s+best\s+wishes|Warm\s*regards|Kind\s*regards|Regards|Cheers|Respectfully(?:\s+yours)?)[,:\s]*$/i.test(line)) {
            return true;
        }
        if (/^(?:Li\s*Ming|Li\s*Hua|Li\s*Ping|Zhang\s*Wei|Wang\s*Ming|(?:The\s+)?Students?'?\s*Union|(?:The\s+)?Postgraduates?'?\s*Association|(?:The\s+)?Youth\s+Volunteer\s+Association|University\s+Library|Campus\s+Volunteer\s+Center)[,\.]?$/i.test(line)) {
            return true;
        }
        if (idx === total - 1 && /^[A-Z][a-z]+\s+\d{1,2},?\s*\d{4}\.?$/.test(line)) {
            return true;
        }
        return false;
    };

    let signoffStart = -1;
    const tailStart = Math.max(1, rawLines.length - 3);
    for (let i = tailStart; i < rawLines.length; i++) {
        if (isEnSignoffLine(rawLines[i], i, rawLines.length)) {
            signoffStart = i;
            break;
        }
    }

    const endIdx = signoffStart !== -1 ? signoffStart : rawLines.length;
    const signoffLines = signoffStart !== -1 ? rawLines.slice(signoffStart) : [];
    const bodyLines = rawLines.slice(0, endIdx);
    let html = '';

    bodyLines.forEach((line, idx) => {
        // 过滤残留的标记行
        if (/^[【\[](?:practical_writing|applied_writing|continuation_writing|section_[12ab])[】\]]/i.test(line) ||
            /^(?:第[一二两12]节|Section\s*[AB12]|Part\s*[AB12])[：:\s]*(?:应用文写作|读后续写|短文写作|写作)?[：:\s]*$/i.test(line) ||
            /^(?:读后续写|应用文写作|续写)[：:\s]*$/i.test(line)) {
            return;
        }

        // Notice header at the very top
        if (idx === 0 && /^Notice$/i.test(line)) {
            html += `<div style="text-align:center; font-size:16.5px; font-weight:700; color:#1c1c1e; margin-bottom:10px; letter-spacing:0.02em;">${makeTextClickable(line)}</div>`;
            return;
        }

        // Date at the top (e.g. June 8, 2008 or October 20, 2019 right under Notice)
        if ((idx === 0 || idx === 1) && /^[A-Z][a-z]+\s+\d{1,2},?\s*\d{4}$/.test(line)) {
            html += `<div style="text-align:right; font-size:14.5px; color:#64748b; margin-bottom:8px;">${makeTextClickable(line)}</div>`;
            return;
        }

        // Salutation (Dear ..., To whom ..., Greetings ...)
        if (/^(?:Dear\s+[A-Za-z0-9\s/,'\.-]+[,:]|To\s+whom\s+it\s+may\s+concern[,:]|Greetings[,:])/i.test(line)) {
            html += `<p style="margin-bottom:12px; text-indent:0; font-weight:600; color:#1c1c1e;">${makeTextClickable(line)}</p>`;
            return;
        }

        // Continuation writing paragraph marker (Paragraph 1: ... / Paragraph 2: ...)
        const paraMatch = line.match(/^(Paragraph\s*[12][：:]?)\s*(.*)/i);
        if (paraMatch) {
            html += `<p style="margin-bottom:12px; text-indent:2em; line-height:1.8;"><strong style="color:#007AFF;">${paraMatch[1]}</strong> ${makeTextClickable(paraMatch[2])}</p>`;
            return;
        }

        html += `<p style="margin-bottom:12px; text-indent:2em; line-height:1.8;">${makeTextClickable(line)}</p>`;
    });

    if (signoffLines.length > 0) {
        html += `
            <div class="essay-signoff-box" style="margin-left:auto; width:fit-content; text-align:right; margin-top:14px; margin-bottom:6px; padding-right:8px;">
                ${signoffLines.map(s => `<div style="font-size:15.5px; font-weight:600; color:#1c1c1e; line-height:1.65;">${makeTextClickable(s)}</div>`).join('')}
            </div>
        `;
    }

    return html;
}

function formatModelEssayZhHtml(text) {
    if (!text || typeof text !== 'string') return '';
    // 彻底清洗开头残留的“第一节：”、“第二节：读后续写”等标记
    text = text
        .replace(/^[【\[](?:practical_writing|applied_writing|continuation_writing|section_[12ab])[】\]](?:[:：\s]*(?:中文翻译|译文|范文))?\s*/gi, '')
        .replace(/^(?:第[一二两12]节|Section\s*[AB12]|Part\s*[AB12])[：:\s]*(?:应用文写作|读后续写|应用文|续写|短文写作|写作)?[：:\s]*\n*/gi, '')
        .replace(/^(?:读后续写|应用文写作|应用文|续写)[：:\s]*\n*/gi, '');

    const rawLines = text.split(/\n+/).map(l => l.trim()).filter(Boolean);
    if (rawLines.length === 0) return '';

    const isZhSignoffLine = (line, idx, total) => {
        if (/^(?:您?(?:真诚|诚挚|真挚|忠实)的|你的朋友|祝好|此致|敬礼|谨上|致以[^\n]{1,10}|祝[^\n]{1,8}|李明|李华|李平|张伟|研究生会|学生会|青年志愿者协会)[，,！!。：:\s]*$/i.test(line)) {
            return true;
        }
        if (idx === total - 1 && /^\d{4}年\d{1,2}月\d{1,2}日$/.test(line)) {
            return true;
        }
        return false;
    };

    let signoffStart = -1;
    const tailStart = Math.max(1, rawLines.length - 3);
    for (let i = tailStart; i < rawLines.length; i++) {
        if (isZhSignoffLine(rawLines[i], i, rawLines.length)) {
            signoffStart = i;
            break;
        }
    }

    const endIdx = signoffStart !== -1 ? signoffStart : rawLines.length;
    const signoffLines = signoffStart !== -1 ? rawLines.slice(signoffStart) : [];
    const bodyLines = rawLines.slice(0, endIdx);
    let html = '';

    bodyLines.forEach((line, idx) => {
        // 过滤独立成行的“第一节：”、“第二节：读后续写”、“读后续写”及原始标签行
        if (/^[【\[](?:practical_writing|applied_writing|continuation_writing|section_[12ab])[】\]]/i.test(line) ||
            /^(?:第[一二两12]节|Section\s*[AB12]|Part\s*[AB12])[：:\s]*(?:应用文写作|读后续写|短文写作|写作)?[：:\s]*$/i.test(line) ||
            /^(?:读后续写|续写)[：:\s]*$/i.test(line)) {
            return;
        }

        // Notice header at top (通知)
        if (idx === 0 && /^通知$/.test(line)) {
            html += `<div style="text-align:center; font-size:15.5px; font-weight:700; color:#1c1c1e; margin-bottom:8px;">${line}</div>`;
            return;
        }

        // Date at top (e.g. 2008年6月8日)
        if ((idx === 0 || idx === 1) && /^\d{4}年\d{1,2}月\d{1,2}日$/.test(line)) {
            html += `<div style="text-align:right; font-size:13.5px; color:#64748b; margin-bottom:6px;">${line}</div>`;
            return;
        }

        // Chinese Salutation (如 尊敬的...：/ 亲爱的...：/ 大家好：)
        if (/^(?:尊敬的[^\n]+[：:]|亲爱的[^\n]+[：:]|各位[^\n]+[：:]|大家好[！!，,：:])/i.test(line)) {
            html += `<p style="margin-bottom:8px; text-indent:0; font-weight:600; color:#1c1c1e;">${line}</p>`;
            return;
        }

        // Chinese Paragraph 1/2 for continuation writing
        const paraMatch = line.match(/^(第[一二12]段[：:]?)\s*(.*)/);
        if (paraMatch) {
            html += `<p style="margin-bottom:10px; text-indent:2em; line-height:1.75;"><strong style="color:#007AFF;">${paraMatch[1]}</strong> ${paraMatch[2]}</p>`;
            return;
        }

        html += `<p style="margin-bottom:8px; text-indent:2em; line-height:1.75;">${line}</p>`;
    });

    if (signoffLines.length > 0) {
        html += `
            <div style="margin-left:auto; width:fit-content; text-align:right; margin-top:12px; margin-bottom:4px; padding-right:8px;">
                ${signoffLines.map(s => `<div style="font-size:14.5px; font-weight:600; color:#1c1c1e; line-height:1.65;">${s}</div>`).join('')}
            </div>
        `;
    }

    return html;
}

function scrollElementIntoPane(el, pane) {
    if (!el) return;
    const splitContainer = document.querySelector('.written-split-container');
    if (splitContainer && splitContainer.classList.contains('mobile-sheet-split-active')) {
        const quizPane = splitContainer.querySelector('.written-split-quiz');
        const sheetH = (window.UXReadingSplitSheet && window.UXReadingSplitSheet._targetHeightPx)
            ? window.UXReadingSplitSheet._targetHeightPx
            : (quizPane ? quizPane.offsetHeight : (window.innerHeight * 0.5));
        const visibleUpperH = Math.max(160, window.innerHeight - sheetH);
        const elRect = el.getBoundingClientRect();
        const targetViewportY = Math.max(78, visibleUpperH * 0.38);
        const targetWindowTop = Math.max(0, window.scrollY + elRect.top - targetViewportY);
        window.scrollTo({ top: targetWindowTop, behavior: 'smooth' });
        return;
    }
    if (pane && pane.scrollHeight > pane.clientHeight + 10) {
        const elRect = el.getBoundingClientRect();
        const paneRect = pane.getBoundingClientRect();
        const relTop = elRect.top - paneRect.top + pane.scrollTop;
        const targetTop = Math.max(0, relTop - (pane.clientHeight * 0.36));
        pane.scrollTo({ top: targetTop, behavior: 'smooth' });
    } else {
        el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
}

function hideBackToQuestionPill() {
    const pill = document.getElementById('btn-back-to-question');
    if (pill) pill.classList.remove('show');
}

function showBackToQuestionPill(targetQ) {
    let pill = document.getElementById('btn-back-to-question');
    if (!pill) {
        pill = document.createElement('button');
        pill.id = 'btn-back-to-question';
        pill.type = 'button';
        pill.className = 'back-to-question-pill';
        document.body.appendChild(pill);
        window.addEventListener('scroll', () => {
            if (!pill.classList.contains('show')) return;
            const quizPane = document.querySelector('#view-written-arena .written-split-quiz');
            if (quizPane) {
                const rect = quizPane.getBoundingClientRect();
                if (rect.bottom > window.innerHeight * 0.45) {
                    pill.classList.remove('show');
                }
            }
        }, { passive: true });
    }
    const qLabel = (targetQ && targetQ.id) ? `第 ${targetQ.id} 题` : '当前题目';
    pill.textContent = `↑ 返回${qLabel}解析`;
    pill.onclick = () => {
        pill.classList.remove('show');
        const expEl = document.getElementById('written-explanation-card');
        const stageEl = document.getElementById('written-stage-card');
        const dest = (expEl && expEl.classList.contains('show')) ? expEl : stageEl;
        if (dest) dest.scrollIntoView({ behavior: 'smooth', block: 'center' });
    };
    setTimeout(() => {
        pill.classList.add('show');
    }, 180);
}

function formatInlineAnalysisMarkdown(rawStr, withClickableWords = true) {
    if (!rawStr || typeof rawStr !== 'string') return '';
    let s = (withClickableWords && typeof makeTextClickable === 'function')
        ? makeTextClickable(rawStr)
        : rawStr;
    s = s.replace(/\*\*([^*\n]+)\*\*/g, '<strong style="color:#0f172a; font-weight:700;">$1</strong>');
    s = s.replace(/(^|[^*])\*([^*\n]+)\*([^*]|$)/g, '$1<span class="md-em-phrase" style="font-style:italic; font-weight:600; color:#0369a1; background:rgba(2, 132, 199, 0.07); padding:1px 5px; border-radius:5px;">$2</span>$3');
    s = s.replace(/\*\*/g, '');
    return s;
}
window.formatInlineAnalysisMarkdown = formatInlineAnalysisMarkdown;

function formatAnalysisRows(rawAnalysis) {
    if (!rawAnalysis || typeof rawAnalysis !== 'string') return '';
    let lines = rawAnalysis.split(/\n+/).map(p => p.trim()).filter(Boolean);
    if (lines.length === 1 && /(?:；|;|\。)\s*[2-9][\.\、]/.test(lines[0])) {
        lines = lines[0].replace(/([；;。])\s*(?=[1-9][\.\、])/g, '$1\n').split(/\n+/).map(p => p.trim()).filter(Boolean);
    }
    // 过滤类似“【审题立意与篇章架构解析】”这种无正文的独立冗余标题行
    lines = lines.filter(line => !/^【[^】]+】[：:\s]*$/.test(line) && !/^(?:审题立意与篇章架构解析|审题构思与行文拆解|审题构思|考点解析)[：:\s]*$/.test(line));
    return lines.map(line => {
        const numMatch = line.match(/^(\d+)[\.\、]\s*(\*\*[^*\n]+\*\*[：:]?|[^：:]{2,26}[：:])?(.*)$/);
        if (numMatch) {
            const num = numMatch[1];
            const cleanLead = numMatch[2] ? numMatch[2].replace(/\*\*/g, '').replace(/\*/g, '').trim() : '';
            const leadTitle = cleanLead ? `<strong style="color:#0f172a; font-weight:700; margin-right:4px;">${formatInlineAnalysisMarkdown(cleanLead, true)}</strong>` : '';
            const rest = formatInlineAnalysisMarkdown(numMatch[3] || '', true);
            return `<div class="ios-subj-list-row"><span class="ios-subj-step-num">${num}</span><div style="flex:1;">${leadTitle}${rest}</div></div>`;
        }
        const subBulletMatch = line.match(/^[-•]\s*(\*\*[^*\n]+\*\*[：:]?|[^：:“”"'‘’，,。；;]{2,18}[：:])?(.*)$/);
        if (subBulletMatch) {
            const cleanSubLead = subBulletMatch[1] ? subBulletMatch[1].replace(/\*\*/g, '').replace(/\*/g, '').trim() : '';
            const subLead = cleanSubLead ? `<strong style="color:#0f172a; font-weight:700; margin-right:4px;">${formatInlineAnalysisMarkdown(cleanSubLead, true)}</strong>` : '';
            const subRest = formatInlineAnalysisMarkdown(subBulletMatch[2] || '', true);
            return `<div class="ios-subj-list-row ios-subj-list-subrow"><div style="flex:1;"><span style="color:#94A3B8; margin-right:6px;">•</span>${subLead}${subRest}</div></div>`;
        }
        const bracketMatch = line.match(/^【([^】]+)】[：:\s]*(.+)$/);
        if (bracketMatch) {
            const cleanBTitle = bracketMatch[1].replace(/\*\*/g, '').trim();
            const bRest = formatInlineAnalysisMarkdown(bracketMatch[2] || '', true);
            return `<div class="ios-subj-list-row"><div style="flex:1;"><strong style="color:#0f172a; font-weight:700; margin-right:4px;">${cleanBTitle}：</strong>${bRest}</div></div>`;
        }
        return `<div class="ios-subj-list-row"><div style="flex:1;">${formatInlineAnalysisMarkdown(line, true)}</div></div>`;
    }).join('');
}
window.formatAnalysisRows = formatAnalysisRows;

function formatObjectiveAnalysisHtml(rawAnalysis) {
    if (!rawAnalysis || typeof rawAnalysis !== 'string') return '暂无详细题目解析。';
    const text = rawAnalysis.trim();
    if (!text) return '暂无详细题目解析。';
    const parts = text
        .replace(/([。；;！!])\s*(?=(?:(?:[A-G]\s*[、,，]\s*)*[A-G]\s*选?项|选项\s*[A-G]|【[A-G]】))/g, '$1\n')
        .split(/\n+/)
        .map(s => s.trim())
        .filter(Boolean);
    const highlightOpt = (s) => formatInlineAnalysisMarkdown(
        s.replace(
            /((?:[A-G]\s*[、,，]\s*)*[A-G]\s*选?项|选项\s*[A-G](?:\s*[、,，]\s*[A-G])*|【[A-G]】)\s*/g,
            (match, tag, offset, fullStr) => {
                const rest = fullStr.slice(offset + match.length);
                const isPunctNext = !rest || /^[，。；;：:、！？!?,.\)）\]】]/.test(rest);
                return isPunctNext
                    ? `<span class="exp-opt-tag">${tag.trim()}</span>`
                    : `<span class="exp-opt-tag">${tag.trim()}</span> `;
            }
        ),
        false
    );
    if (parts.length <= 1) {
        return highlightOpt(text);
    }
    return parts.map(p => `<div class="exp-analysis-seg">${highlightOpt(p)}</div>`).join('');
}
window.formatObjectiveAnalysisHtml = formatObjectiveAnalysisHtml;


window.formatWritingInstructions = formatWritingInstructions;
window.parseWritingDirections = parseWritingDirections;
window.formatModelEssayHtml = formatModelEssayHtml;
window.formatModelEssayZhHtml = formatModelEssayZhHtml;
window.scrollElementIntoPane = scrollElementIntoPane;
window.hideBackToQuestionPill = hideBackToQuestionPill;
window.showBackToQuestionPill = showBackToQuestionPill;


/* === js/written_annotations.js === */
// ==========================================================================
// Written Evidence Locator, Option Elimination & Passage Underline Engine (js/written_annotations.js)
// ==========================================================================
function clearEvidenceHighlightInPassage(passageCard) {
    const pCard = passageCard || document.getElementById('written-passage-card');
    if (!pCard) return;
    if (window.UXRoughNotation && typeof window.UXRoughNotation.clearAnnotations === 'function') {
        window.UXRoughNotation.clearAnnotations(pCard);
    }
    pCard.querySelectorAll('mark.passage-evidence-highlight').forEach(markEl => {
        markEl.querySelectorAll('.passage-evidence-badge').forEach(b => b.remove());
        const parent = markEl.parentNode;
        if (!parent) return;
        while (markEl.firstChild) {
            parent.insertBefore(markEl.firstChild, markEl);
        }
        parent.removeChild(markEl);
    });
}

function highlightEvidenceInPassage(targetQ, opts = {}) {
    const pCard = document.getElementById('written-passage-card');
    const passPane = document.querySelector('.written-split-passage');
    if (!pCard || pCard.style.display === 'none') return null;

    clearEvidenceHighlightInPassage(pCard);
    if (!targetQ) return null;

    const rawEv = (targetQ.evidence_en || '').trim();
    const rawSegments = [];
    if (rawEv) {
        const cleanedEv = rawEv
            .replace(/^\s*(?:\(Para\.?\s*\d+\)|【[^】]+】|\[[^\]]+\])\s*/gi, '')
            .replace(/^["“']+|["”']+$/g, '')
            .trim();
        cleanedEv.split(/(?:\.{3,}|…)/).map(s => s.trim()).filter(Boolean).forEach(seg => {
            rawSegments.push(seg);
        });
    }
    if (rawSegments.length === 0 && Array.isArray(targetQ.synonym_pairs)) {
        targetQ.synonym_pairs.forEach(sp => {
            if (sp && sp.orig) rawSegments.push(String(sp.orig).trim());
        });
    }
    if (rawSegments.length === 0) return null;

    const paras = Array.from(pCard.querySelectorAll('p'));
    let firstMarkEl = null;

    rawSegments.forEach((seg, segIdx) => {
        const targetWords = (seg.toLowerCase().match(/[a-z]+/g) || []);
        if (targetWords.length < 2) return;

        for (const p of paras) {
            const wordEls = Array.from(p.querySelectorAll('.dict-word')).filter(el =>
                !el.closest('.written-cloze-blank, .seven-blank-reflected, .fill-blank-reflected, .sentence-insert-square, .trans-marker-badge, .passage-evidence-badge')
            );
            if (wordEls.length === 0) continue;

            const pTokens = [];
            wordEls.forEach(el => {
                const sub = el.textContent.toLowerCase().match(/[a-z]+/g) || [];
                sub.forEach(w => pTokens.push({ word: w, el }));
            });
            if (pTokens.length < targetWords.length) continue;

            let matchStartIdx = -1;
            let matchEndIdx = -1;

            // 1. Exact contiguous sequence match
            for (let i = 0; i <= pTokens.length - targetWords.length; i++) {
                let ok = true;
                for (let k = 0; k < targetWords.length; k++) {
                    if (pTokens[i + k].word !== targetWords[k]) {
                        ok = false;
                        break;
                    }
                }
                if (ok) {
                    matchStartIdx = i;
                    matchEndIdx = i + targetWords.length - 1;
                    break;
                }
            }

            // 2. Fuzzy prefix + suffix anchor match within same paragraph
            if (matchStartIdx === -1 && targetWords.length >= 6) {
                const headLen = 3;
                const tailLen = 3;
                for (let i = 0; i <= pTokens.length - headLen; i++) {
                    if (pTokens[i].word === targetWords[0] &&
                        pTokens[i + 1].word === targetWords[1] &&
                        pTokens[i + 2].word === targetWords[2]) {
                        const maxJ = Math.min(pTokens.length - tailLen, i + targetWords.length + 12);
                        const minJ = Math.max(i + headLen, i + targetWords.length - 12);
                        for (let j = minJ; j <= maxJ; j++) {
                            if (pTokens[j].word === targetWords[targetWords.length - 3] &&
                                pTokens[j + 1].word === targetWords[targetWords.length - 2] &&
                                pTokens[j + 2].word === targetWords[targetWords.length - 1]) {
                                matchStartIdx = i;
                                matchEndIdx = j + 2;
                                break;
                            }
                        }
                        if (matchStartIdx !== -1) break;
                    }
                }
            }

            // 3. Prefix 4-word fallback
            if (matchStartIdx === -1 && targetWords.length >= 5) {
                for (let i = 0; i <= pTokens.length - 4; i++) {
                    if (pTokens[i].word === targetWords[0] &&
                        pTokens[i + 1].word === targetWords[1] &&
                        pTokens[i + 2].word === targetWords[2] &&
                        pTokens[i + 3].word === targetWords[3]) {
                        matchStartIdx = i;
                        matchEndIdx = Math.min(pTokens.length - 1, i + targetWords.length - 1);
                        break;
                    }
                }
            }

            if (matchStartIdx !== -1 && matchEndIdx >= matchStartIdx) {
                const startEl = pTokens[matchStartIdx].el;
                const endEl = pTokens[matchEndIdx].el;
                let rangeStartNode = startEl;
                let rangeEndNode = endEl;
                if (startEl && endEl && startEl.parentNode !== endEl.parentNode) {
                    const sUnit = startEl.closest('.passage-sent-unit');
                    const eUnit = endEl.closest('.passage-sent-unit');
                    if (sUnit && eUnit && sUnit.parentNode === eUnit.parentNode) {
                        rangeStartNode = sUnit;
                        rangeEndNode = eUnit;
                    }
                }
                if (rangeStartNode && rangeEndNode && rangeStartNode.parentNode === rangeEndNode.parentNode) {
                    try {
                        const range = document.createRange();
                        range.setStartBefore(rangeStartNode);
                        range.setEndAfter(rangeEndNode);
                        const markEl = document.createElement('mark');
                        markEl.className = 'passage-evidence-highlight';
                        if (!firstMarkEl && segIdx === 0 && targetQ.id) {
                            const badge = document.createElement('span');
                            badge.className = 'passage-evidence-badge';
                            badge.textContent = `🎯 Q${targetQ.id}`;
                            markEl.appendChild(badge);
                        }
                        markEl.appendChild(range.extractContents());
                        range.insertNode(markEl);
                        if (!firstMarkEl) firstMarkEl = markEl;
                        break;
                    } catch (e) {}
                }
            }
        }
    });

    if (firstMarkEl) {
        if (window.UXRoughNotation && typeof window.UXRoughNotation.annotatePassageEvidence === 'function') {
            requestAnimationFrame(() => window.UXRoughNotation.annotatePassageEvidence(pCard));
        }
        if (opts.pulse) {
            firstMarkEl.classList.remove('evidence-pulse');
            void firstMarkEl.offsetWidth;
            firstMarkEl.classList.add('evidence-pulse');
        }
        const splitContainer = document.querySelector('.written-split-container');
        const isSheetSplit = !!(splitContainer && splitContainer.classList.contains('mobile-sheet-split-active'));
        if (opts.forceScroll) {
            if (isSheetSplit && passPane) {
                scrollElementIntoPane(firstMarkEl, passPane);
            } else if (passPane && passPane.scrollHeight > passPane.clientHeight + 10) {
                scrollElementIntoPane(firstMarkEl, passPane);
            } else {
                firstMarkEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
                showBackToQuestionPill(targetQ);
            }
        } else if (opts.autoScrollSplit) {
            if (isSheetSplit || (passPane && passPane.scrollHeight > passPane.clientHeight + 10)) {
                scrollElementIntoPane(firstMarkEl, passPane);
            }
        }
    } else if (opts.forceScroll && pCard) {
        scrollElementIntoPane(pCard, passPane);
        if (!(passPane && passPane.scrollHeight > passPane.clientHeight + 10)) {
            showBackToQuestionPill(targetQ);
        }
    }

    return firstMarkEl;
}

// ==========================================================================
// ✨ 1. 极致无感排除选项系统 (横抹跟手划除 + 0.28s 长按排除 + 轻点恢复)
//    - 单击正常选项：100% 永远是选择该选项作答，绝不误触发排除
//    - 直觉 A (横向轻抹)：划动时删除线实时跟手生长，满 18px 丝滑锁定排除
//    - 直觉 B (长按 0.28s)：按住选项停顿 0.28s 直接排除（松手不误选）
//    - 直觉 C (PC 右键)：右键一点即切换排除/恢复
//    - 极简恢复：无任何多余按钮，直接轻点一下已排除的选项即刻恢复
// ==========================================================================
window._eliminatedOptionsMap = window._eliminatedOptionsMap || {};

function persistEliminatedOptions(elimStateKey) {
    if (!elimStateKey) return;
    const parts = String(elimStateKey).split('::');
    const examTitle = parts.length >= 2 ? parts[1] : (window.currentWrittenExamTitle || 'default');
    if (!examTitle || examTitle === 'default') return;
    if (!window.completedExams) window.completedExams = {};
    if (!window.completedExams[examTitle]) {
        window.completedExams[examTitle] = { timestamp: Date.now() };
    }
    if (!window.completedExams[examTitle].eliminatedOptions || typeof window.completedExams[examTitle].eliminatedOptions !== 'object') {
        window.completedExams[examTitle].eliminatedOptions = {};
    }
    const elimSet = window._eliminatedOptionsMap[elimStateKey];
    if (elimSet && elimSet.size > 0) {
        window.completedExams[examTitle].eliminatedOptions[elimStateKey] = Array.from(elimSet);
    } else {
        delete window.completedExams[examTitle].eliminatedOptions[elimStateKey];
    }
    window.completedExams[examTitle].eliminatedUpdatedAt = Date.now();
    window.completedExams[examTitle].timestamp = Date.now();
    if (typeof window.saveUserCloudData === 'function') {
        window.saveUserCloudData(examTitle, false);
    }
}

function clearOptionEliminationForKeys(elimStateKey, keys) {
    if (!elimStateKey || !Array.isArray(keys) || keys.length === 0) return;
    if (!window._eliminatedOptionsMap[elimStateKey]) {
        const parts = String(elimStateKey).split('::');
        const examTitle = parts.length >= 2 ? parts[1] : (window.currentWrittenExamTitle || 'default');
        const savedArr = window.completedExams &&
            window.completedExams[examTitle] &&
            window.completedExams[examTitle].eliminatedOptions &&
            window.completedExams[examTitle].eliminatedOptions[elimStateKey];
        if (!Array.isArray(savedArr) || savedArr.length === 0) return;
        window._eliminatedOptionsMap[elimStateKey] = new Set(savedArr.map(String));
    }
    const elimSet = window._eliminatedOptionsMap[elimStateKey];
    let changed = false;
    keys.forEach(k => {
        if (k !== undefined && k !== null && elimSet.delete(String(k))) {
            changed = true;
        }
    });
    if (changed) {
        persistEliminatedOptions(elimStateKey);
    }
}
window.clearOptionEliminationForKeys = clearOptionEliminationForKeys;

function bindOptionElimination(btn, elimStateKey, optKey) {
    if (!btn || !elimStateKey || !optKey) return;

    if (!window._eliminatedOptionsMap[elimStateKey]) {
        const parts = String(elimStateKey).split('::');
        const examTitle = parts.length >= 2 ? parts[1] : (window.currentWrittenExamTitle || 'default');
        const savedArr = window.completedExams &&
            window.completedExams[examTitle] &&
            window.completedExams[examTitle].eliminatedOptions &&
            window.completedExams[examTitle].eliminatedOptions[elimStateKey];
        window._eliminatedOptionsMap[elimStateKey] = new Set(Array.isArray(savedArr) ? savedArr.map(String) : []);
    }
    const elimSet = window._eliminatedOptionsMap[elimStateKey];
    const textEl = btn.querySelector('.opt-en-text, .word-bank-opt-text');

    const clearScratchPreview = () => {
        if (textEl) {
            textEl.style.backgroundSize = '';
            textEl.style.backgroundPosition = '';
        }
        btn.style.opacity = '';
    };

    const isLockedOrSelected = () => (
        btn.classList.contains('opt-current-pick') ||
        btn.classList.contains('correct-state') ||
        btn.classList.contains('wrong-state') ||
        btn.classList.contains('exam-selected-state')
    );

    if (elimSet.has(optKey) && !isLockedOrSelected()) {
        btn.classList.add('opt-eliminated');
    }

    const setEliminatedState = (shouldEliminate) => {
        clearScratchPreview();
        if (isLockedOrSelected()) {
            btn.classList.remove('opt-eliminated');
            if (elimSet.delete(optKey)) {
                persistEliminatedOptions(elimStateKey);
            }
            return;
        }
        if (shouldEliminate) {
            btn.classList.add('opt-eliminated');
            elimSet.add(optKey);
        } else {
            btn.classList.remove('opt-eliminated');
            elimSet.delete(optKey);
        }
        persistEliminatedOptions(elimStateKey);
        if (navigator && typeof navigator.vibrate === 'function') {
            try { navigator.vibrate(10); } catch (e) {}
        }
        if (window.FeedbackEngine && typeof window.FeedbackEngine.playTap === 'function') {
            window.FeedbackEngine.playTap();
        }
    };

    // 捕获阶段拦截点击：
    // 1. 如果是横抹或长按刚松手产生的合成 click，直接吞掉；
    // 2. 如果当前选项已处于「已排除态」，单击任意位置 = 立即恢复为正常态；
    // 3. 如果当前选项是「正常态」，单击完全放行给原有的选答案逻辑！
    btn.addEventListener('click', (e) => {
        if (window.isLookupMode) return;
        if (btn._suppressNextClickUntil && Date.now() < btn._suppressNextClickUntil) {
            e.stopImmediatePropagation();
            e.preventDefault();
            return;
        }
        if (btn.classList.contains('opt-eliminated') && !isLockedOrSelected()) {
            e.stopImmediatePropagation();
            e.preventDefault();
            setEliminatedState(false);
            return;
        }
    }, true);

    // PC 端鼠标右键点击切换排除/恢复
    btn.addEventListener('contextmenu', (e) => {
        if (window.isLookupMode || isLockedOrSelected()) return;
        e.preventDefault();
        e.stopPropagation();
        setEliminatedState(!btn.classList.contains('opt-eliminated'));
    });

    // 移动端 / 平板 / 触控板：横抹跟手划除 + 0.28s 静置长按排除
    let startX = 0;
    let startY = 0;
    let isTracking = false;
    let hasTriggeredInGesture = false;
    let longPressTimer = null;

    const cancelLongPress = () => {
        if (longPressTimer) {
            clearTimeout(longPressTimer);
            longPressTimer = null;
        }
    };

    const onGestureStart = (clientX, clientY) => {
        if (window.isLookupMode || isLockedOrSelected()) return;
        startX = clientX;
        startY = clientY;
        isTracking = true;
        hasTriggeredInGesture = false;
        cancelLongPress();

        longPressTimer = setTimeout(() => {
            longPressTimer = null;
            if (!isTracking || hasTriggeredInGesture || window.isLookupMode || isLockedOrSelected()) return;
            hasTriggeredInGesture = true;
            isTracking = false;
            btn._suppressNextClickUntil = Date.now() + 450;
            setEliminatedState(!btn.classList.contains('opt-eliminated'));
        }, 460);
    };

    const onGestureMove = (clientX, clientY, ev) => {
        if (!isTracking || hasTriggeredInGesture) return;
        const dx = clientX - startX;
        const dy = clientY - startY;
        const absDx = Math.abs(dx);
        const absDy = Math.abs(dy);

        if (absDx > 7 || absDy > 7) {
            cancelLongPress();
        }

        // 垂直滚动优先放行
        if (absDy > 18 && absDy > absDx) {
            isTracking = false;
            clearScratchPreview();
            return;
        }

        // 水平轻抹跟手实时预览 (6px ~ 18px 之间删除线随手指实时生长)
        if (absDx >= 6 && absDx > absDy * 1.15) {
            if (ev && ev.cancelable) {
                try { ev.preventDefault(); } catch (err) {}
            }
            const isCurrentlyElim = btn.classList.contains('opt-eliminated');
            if (!isCurrentlyElim && textEl && absDx < 18) {
                const pct = Math.min(95, Math.round((absDx / 18) * 100));
                textEl.style.backgroundPosition = dx >= 0 ? '0% 55%' : '100% 55%';
                textEl.style.backgroundSize = `${pct}% 1.6px`;
            }

            if (absDx >= 18) {
                hasTriggeredInGesture = true;
                isTracking = false;
                btn._suppressNextClickUntil = Date.now() + 400;
                setEliminatedState(!isCurrentlyElim);
            }
        }
    };

    const onGestureEnd = () => {
        cancelLongPress();
        if (isTracking && !hasTriggeredInGesture) {
            clearScratchPreview();
        }
        isTracking = false;
    };

    btn.addEventListener('touchstart', (e) => {
        if (e.touches && e.touches.length === 1) {
            onGestureStart(e.touches[0].clientX, e.touches[0].clientY);
        }
    }, { passive: true });

    btn.addEventListener('touchmove', (e) => {
        if (e.touches && e.touches.length === 1) {
            onGestureMove(e.touches[0].clientX, e.touches[0].clientY, e);
        }
    }, { passive: false });

    btn.addEventListener('touchend', onGestureEnd, { passive: true });
    btn.addEventListener('touchcancel', onGestureEnd, { passive: true });

    btn.addEventListener('mousedown', (e) => {
        if (e.button === 0) {
            onGestureStart(e.clientX, e.clientY);
        }
    });
    btn.addEventListener('mousemove', (e) => {
        if (isTracking && (e.buttons & 1)) {
            onGestureMove(e.clientX, e.clientY, e);
        }
    });
    btn.addEventListener('mouseup', onGestureEnd);
    btn.addEventListener('mouseleave', onGestureEnd);
}
window.bindOptionElimination = bindOptionElimination;

// ==========================================================================
// ✨ 2. 原文零感画线定位引擎 (轻点智能意群画线 + 按住横抹自由选词 + 再点即擦)
//    - 默认做题态轻点原文：智能识别当前短分句/意群（标点、从句引导词、题号自然断句），墨水线平滑展开
//    - 轻点已画线处：整段相连下划线平滑回缩擦除
//    - 按住横向轻抹：想画哪几个词就精准画哪几个词（支持跨行顺滑连画，查词模式下也可直接横抹画线）
// ==========================================================================
window._passageUnderlinesMap = window._passageUnderlinesMap || {};

function syncParagraphUnderlineSeparators(paraEl) {
    if (!paraEl) return;
    const seps = paraEl.querySelectorAll('.dict-sep');
    seps.forEach(sep => {
        const prev = sep.previousElementSibling;
        const next = sep.nextElementSibling;
        const shouldConnect = !!(
            prev && next &&
            prev.classList.contains('dict-word') &&
            next.classList.contains('dict-word') &&
            prev.classList.contains('is-user-underlined') &&
            next.classList.contains('is-user-underlined')
        );
        sep.classList.toggle('is-user-underlined', shouldConnect);
    });
}

function persistPassageUnderlines(passageCard) {
    if (!passageCard) return;
    const examKey = passageCard._underlineExamKey || window.currentWrittenExamTitle || 'default';
    const set = new Set();
    passageCard.querySelectorAll('.dict-word.is-user-underlined').forEach(w => {
        if (w.dataset.uIdx !== undefined) {
            set.add(String(w.dataset.uIdx));
        }
    });
    window._passageUnderlinesMap[examKey] = set;

    const sepIdx = String(examKey).indexOf('::');
    const realExamTitle = sepIdx !== -1 ? String(examKey).slice(0, sepIdx) : String(examKey);
    const passageScope = sepIdx !== -1 ? String(examKey).slice(sepIdx + 2) : '';

    if (realExamTitle && realExamTitle !== 'default') {
        if (!window.completedExams) window.completedExams = {};
        if (!window.completedExams[realExamTitle]) {
            window.completedExams[realExamTitle] = { timestamp: Date.now() };
        }
        const existingArr = Array.isArray(window.completedExams[realExamTitle].underlines)
            ? window.completedExams[realExamTitle].underlines.map(String)
            : [];
        if (passageScope) {
            const prefix = `${passageScope}::`;
            const others = existingArr.filter(item => item.includes('::') && !item.startsWith(prefix));
            const scoped = Array.from(set).map(u => `${prefix}${u}`);
            window.completedExams[realExamTitle].underlines = others.concat(scoped);
            window._passageUnderlinesMap[realExamTitle] = new Set(window.completedExams[realExamTitle].underlines);
        } else {
            window.completedExams[realExamTitle].underlines = Array.from(set);
        }
        window.completedExams[realExamTitle].underlinesUpdatedAt = Date.now();
        window.completedExams[realExamTitle].timestamp = Date.now();
        if (typeof window.saveUserCloudData === 'function') {
            window.saveUserCloudData(realExamTitle, false);
        }
    }
}

function hydrateWrittenArenaAnnotations(targetExamTitle) {
    if (!window.completedExams || typeof window.completedExams !== 'object') return;
    window._passageUnderlinesMap = window._passageUnderlinesMap || {};
    window._eliminatedOptionsMap = window._eliminatedOptionsMap || {};

    const titles = targetExamTitle ? [targetExamTitle] : Object.keys(window.completedExams);
    titles.forEach(title => {
        const rec = window.completedExams[title];
        if (!rec || typeof rec !== 'object') return;
        if (Array.isArray(rec.underlines)) {
            const rawList = rec.underlines.map(String);
            window._passageUnderlinesMap[title] = new Set(rawList);
            rawList.forEach(item => {
                const idx = item.indexOf('::');
                if (idx !== -1) {
                    const scope = item.slice(0, idx);
                    const uIdx = item.slice(idx + 2);
                    const compositeKey = `${title}::${scope}`;
                    if (!window._passageUnderlinesMap[compositeKey]) {
                        window._passageUnderlinesMap[compositeKey] = new Set();
                    }
                    window._passageUnderlinesMap[compositeKey].add(uIdx);
                }
            });
        }
        if (rec.eliminatedOptions && typeof rec.eliminatedOptions === 'object') {
            Object.entries(rec.eliminatedOptions).forEach(([elimKey, arr]) => {
                if (Array.isArray(arr)) {
                    window._eliminatedOptionsMap[elimKey] = new Set(arr.map(String));
                }
            });
        }
    });
}
window.hydrateWrittenArenaAnnotations = hydrateWrittenArenaAnnotations;

function clearExamArenaAnnotations(targetExamTitle) {
    if (!targetExamTitle) return;
    if (window.completedExams && window.completedExams[targetExamTitle]) {
        delete window.completedExams[targetExamTitle].underlines;
        delete window.completedExams[targetExamTitle].eliminatedOptions;
    }
    if (window._passageUnderlinesMap && typeof window._passageUnderlinesMap === 'object') {
        const prefix = `${targetExamTitle}::`;
        Object.keys(window._passageUnderlinesMap).forEach(k => {
            if (k === targetExamTitle || k.indexOf(prefix) === 0) delete window._passageUnderlinesMap[k];
        });
    }
    if (window._eliminatedOptionsMap && typeof window._eliminatedOptionsMap === 'object') {
        const mid = `::${targetExamTitle}::`;
        Object.keys(window._eliminatedOptionsMap).forEach(k => {
            if (k === targetExamTitle || k.includes(mid) || k.endsWith(`::${targetExamTitle}`) || k.startsWith(`${targetExamTitle}_`)) {
                delete window._eliminatedOptionsMap[k];
            }
        });
    }
    document.querySelectorAll('.dict-word.is-user-underlined').forEach(el => el.classList.remove('is-user-underlined'));
    document.querySelectorAll('.opt-eliminated').forEach(el => el.classList.remove('opt-eliminated'));
}
window.clearExamArenaAnnotations = clearExamArenaAnnotations;

function eraseContiguousUnderlineSpan(wordEl, passageCard) {
    if (!wordEl || !passageCard) return;
    const paraEl = wordEl.closest('p') || passageCard;
    const words = Array.from(paraEl.querySelectorAll('.dict-word'));
    const pos = words.indexOf(wordEl);
    if (pos === -1) return;

    wordEl.classList.remove('is-user-underlined');
    for (let i = pos - 1; i >= 0; i--) {
        if (words[i].classList.contains('is-user-underlined')) {
            words[i].classList.remove('is-user-underlined');
        } else {
            break;
        }
    }
    for (let i = pos + 1; i < words.length; i++) {
        if (words[i].classList.contains('is-user-underlined')) {
            words[i].classList.remove('is-user-underlined');
        } else {
            break;
        }
    }

    syncParagraphUnderlineSeparators(paraEl);
    persistPassageUnderlines(passageCard);

    if (navigator && typeof navigator.vibrate === 'function') {
        try { navigator.vibrate(8); } catch (e) {}
    }
    if (window.FeedbackEngine && typeof window.FeedbackEngine.playTap === 'function') {
        window.FeedbackEngine.playTap();
    }
}
window.eraseContiguousUnderlineSpan = eraseContiguousUnderlineSpan;

const SENSE_GROUP_BREAK_WORDS = new Set([
    'that', 'which', 'who', 'whom', 'whose', 'where', 'when', 'whether',
    'while', 'whereas', 'although', 'though', 'because', 'since', 'unless',
    'until', 'before', 'after', 'if', 'but', 'yet', 'however'
]);

function toggleClauseUnderlineAroundWord(targetEl) {
    if (!targetEl) return false;
    const wordEl = targetEl.classList && targetEl.classList.contains('dict-word')
        ? targetEl
        : (targetEl.closest ? targetEl.closest('.dict-word') : null);
    if (!wordEl) return false;

    const passageCard = wordEl.closest('#written-passage-card');
    if (!passageCard) return false;

    if (wordEl.classList.contains('is-user-underlined')) {
        eraseContiguousUnderlineSpan(wordEl, passageCard);
        return false;
    }

    const paraEl = wordEl.closest('p') || passageCard;
    const clauseBreakRe = /[.!?。！？；;:：,，—()（）"“”]/;
    const leftWords = [];
    const rightWords = [];

    // 向左收集同一标点/题号内的词
    let cur = wordEl;
    while (cur.previousSibling) {
        const prev = cur.previousSibling;
        if (prev.nodeType === 1) {
            if (prev.classList.contains('dict-word')) {
                leftWords.push(prev);
            } else if (prev.classList.contains('dict-sep')) {
                if (clauseBreakRe.test(prev.textContent || '')) break;
            } else {
                break;
            }
        }
        cur = prev;
    }

    // 向右收集同一标点/题号内的词
    cur = wordEl;
    while (cur.nextSibling) {
        const next = cur.nextSibling;
        if (next.nodeType === 1) {
            if (next.classList.contains('dict-word')) {
                rightWords.push(next);
            } else if (next.classList.contains('dict-sep')) {
                if (clauseBreakRe.test(next.textContent || '')) break;
            } else {
                break;
            }
        }
        cur = next;
    }

    // 如果两个标点之间的长句超过 9 个词，按从句连词智能切分为精炼意群，避免一次画满三四行
    const clauseWords = [...leftWords.reverse(), wordEl, ...rightWords];
    let finalWords = clauseWords;
    if (clauseWords.length > 9) {
        const tapIdx = leftWords.length;
        let subStart = 0;
        let subEnd = clauseWords.length - 1;

        for (let i = tapIdx; i > 0; i--) {
            const wClean = (clauseWords[i].textContent || '').trim().toLowerCase();
            if (SENSE_GROUP_BREAK_WORDS.has(wClean) && (i >= 3)) {
                subStart = i;
                break;
            }
        }
        for (let i = tapIdx + 1; i < clauseWords.length; i++) {
            const wClean = (clauseWords[i].textContent || '').trim().toLowerCase();
            if (SENSE_GROUP_BREAK_WORDS.has(wClean) && (i - subStart >= 4)) {
                subEnd = i - 1;
                break;
            }
        }
        finalWords = clauseWords.slice(subStart, subEnd + 1);
    }

    finalWords.forEach(w => w.classList.add('is-user-underlined'));
    syncParagraphUnderlineSeparators(paraEl);
    persistPassageUnderlines(passageCard);

    if (navigator && typeof navigator.vibrate === 'function') {
        try { navigator.vibrate(10); } catch (e) {}
    }
    if (window.FeedbackEngine && typeof window.FeedbackEngine.playTap === 'function') {
        window.FeedbackEngine.playTap();
    }
    return true;
}
window.toggleSentenceUnderlineElement = toggleClauseUnderlineAroundWord;

function prepareParagraphWordsForUnderline(paraEl, pIdx, counterRef, savedSet) {
    if (!paraEl || paraEl.dataset.uPrepared === '1') return;
    paraEl.dataset.uPrepared = '1';

    const childNodes = Array.from(paraEl.childNodes);
    childNodes.forEach(node => {
        if (node.nodeType === 3) {
            const text = node.nodeValue || '';
            if (text.length > 0) {
                const sep = document.createElement('span');
                sep.className = 'dict-sep';
                sep.textContent = text;
                paraEl.replaceChild(sep, node);
            }
        } else if (node.nodeType === 1 && node.classList.contains('dict-word')) {
            const idxStr = String(counterRef.val++);
            node.dataset.uIdx = idxStr;
            node.dataset.pIdx = String(pIdx);
            if (savedSet && savedSet.has(idxStr)) {
                node.classList.add('is-user-underlined');
            }
        }
    });

    syncParagraphUnderlineSeparators(paraEl);
}

function findWordNearPoint(passageCard, clientX, clientY, preferredParaEl, cachedWordRects) {
    const isInsideBlankBadge = (el) => !!(el && el.closest && el.closest('.written-cloze-blank, .seven-blank-reflected, .fill-blank-reflected, .sentence-insert-square, .trans-marker-badge, .passage-evidence-badge'));
    const hit = document.elementFromPoint(clientX, clientY);
    if (hit && passageCard.contains(hit)) {
        if (isInsideBlankBadge(hit)) return null;
        const directWord = hit.closest('.dict-word');
        if (directWord && passageCard.contains(directWord) && !isInsideBlankBadge(directWord)) return directWord;

        const sep = hit.closest('.dict-sep');
        if (sep && passageCard.contains(sep)) {
            const prev = sep.previousElementSibling;
            const next = sep.nextElementSibling;
            if (prev && prev.classList.contains('dict-word') && !isInsideBlankBadge(prev)) return prev;
            if (next && next.classList.contains('dict-word') && !isInsideBlankBadge(next)) return next;
        }
    }

    if (cachedWordRects && cachedWordRects.length > 0) {
        let bestWord = null;
        let bestDist = Infinity;
        for (let i = 0; i < cachedWordRects.length; i++) {
            const item = cachedWordRects[i];
            const rect = item.rect;
            if (clientY >= rect.top - 12 && clientY <= rect.bottom + 12) {
                const dx = clientX < rect.left
                    ? rect.left - clientX
                    : (clientX > rect.right ? clientX - rect.right : 0);
                if (dx < bestDist && dx <= 42) {
                    bestDist = dx;
                    bestWord = item.el;
                }
            }
        }
        return bestWord;
    }

    const scopeEl = preferredParaEl || passageCard;
    const words = scopeEl.querySelectorAll('.dict-word');
    let bestWord = null;
    let bestDist = Infinity;

    for (let i = 0; i < words.length; i++) {
        const w = words[i];
        if (isInsideBlankBadge(w)) continue;
        const rect = w.getBoundingClientRect();
        if (clientY >= rect.top - 12 && clientY <= rect.bottom + 12) {
            const dx = clientX < rect.left
                ? rect.left - clientX
                : (clientX > rect.right ? clientX - rect.right : 0);
            if (dx < bestDist && dx <= 42) {
                bestDist = dx;
                bestWord = w;
            }
        }
    }
    return bestWord;
}

const GESTURE_WHISPER_STORAGE_KEY = 'toy_gesture_whisper_seen_v5';

function dismissGestureWhisperPill(markSeen = false) {
    const pill = document.getElementById('gesture-whisper-pill');
    if (markSeen) {
        window._hasShownGestureWhisper = true;
        try {
            window.__toyLS.setItem(GESTURE_WHISPER_STORAGE_KEY, '1');
        } catch (e) {}
    }
    if (!pill) return;
    pill.classList.remove('show');
    setTimeout(() => {
        if (pill.parentNode) pill.parentNode.removeChild(pill);
    }, 300);
}
window.dismissGestureWhisperPill = dismissGestureWhisperPill;

function maybeShowFirstTimeGestureWhisper(force = false) {
    if (!force) return;

    if (typeof window.closeTopMenuHint === 'function') {
        window.closeTopMenuHint(false);
    }

    let pill = document.getElementById('gesture-whisper-pill');
    if (pill) {
        pill.classList.add('show');
        return;
    }

    pill = document.createElement('div');
    pill.id = 'gesture-whisper-pill';
    pill.className = 'gesture-whisper-pill';
    pill.setAttribute('role', 'status');
    pill.innerHTML = `
        <div class="gesture-guide-header">
            <span class="gesture-guide-title">💡 快捷手势</span>
            <button type="button" class="gesture-guide-close">知道了</button>
        </div>
        <div class="gesture-guide-row">
            <span class="gesture-guide-tag">点词收藏</span>
            <span><b>轻点单词</b>加入生词本 / 充电查释义</span>
        </div>
        <div class="gesture-guide-row">
            <span class="gesture-guide-tag">原文画线</span>
            <span><b>按住横划</b>自由画线，再次横划擦除</span>
        </div>
        <div class="gesture-guide-row">
            <span class="gesture-guide-tag">排除选项</span>
            <span><b>横划 / 长按</b>划掉选项，轻点恢复</span>
        </div>
    `;
    document.body.appendChild(pill);

    const closeBtn = pill.querySelector('.gesture-guide-close');
    if (closeBtn) {
        closeBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            dismissGestureWhisperPill(true);
        });
    }

    requestAnimationFrame(() => {
        setTimeout(() => {
            if (pill.parentNode) pill.classList.add('show');
        }, 120);
    });

    const backBtn = document.getElementById('btn-top-nav-action');
    if (backBtn && !backBtn._whisperBound) {
        backBtn._whisperBound = true;
        backBtn.addEventListener('click', () => dismissGestureWhisperPill(false));
    }
}
window.showGestureWhisperPill = maybeShowFirstTimeGestureWhisper;

function initPassageUserUnderline(passageCard, examTitle) {
    if (!passageCard || passageCard.style.display === 'none') return;
    if (passageCard.querySelector('.proof-word, .corr-item')) return;

    const examKey = examTitle || window.currentWrittenExamTitle || 'default';
    passageCard._underlineExamKey = examKey;
    if (!window._passageUnderlinesMap[examKey]) {
        const sepIdx = String(examKey).indexOf('::');
        const realExamTitle = sepIdx !== -1 ? String(examKey).slice(0, sepIdx) : String(examKey);
        const passageScope = sepIdx !== -1 ? String(examKey).slice(sepIdx + 2) : '';
        const persistedArr = window.completedExams &&
            window.completedExams[realExamTitle] &&
            window.completedExams[realExamTitle].underlines;
        const extracted = [];
        if (Array.isArray(persistedArr)) {
            const prefix = passageScope ? `${passageScope}::` : '';
            persistedArr.forEach(item => {
                const s = String(item);
                if (prefix && s.startsWith(prefix)) {
                    extracted.push(s.slice(prefix.length));
                } else if (!prefix && !s.includes('::')) {
                    extracted.push(s);
                }
            });
        }
        window._passageUnderlinesMap[examKey] = new Set(extracted);
    }
    const savedSet = window._passageUnderlinesMap[examKey];

    const counterRef = { val: 0 };
    const paras = Array.from(passageCard.querySelectorAll('p'));
    paras.forEach((p, idx) => {
        prepareParagraphWordsForUnderline(p, idx, counterRef, savedSet);
    });

    if (passageCard._underlineEventsBound) return;
    passageCard._underlineEventsBound = true;

    const isInteractiveBlank = (el) => {
        if (!el || typeof el.closest !== 'function') return true;
        return !!el.closest('.written-cloze-blank, .seven-blank-reflected, .fill-blank-reflected, .sentence-insert-square, .trans-marker-badge, .passage-evidence-badge');
    };

    // 1. 手势彻底分离（方案 A）：
    //    - 轻点单词 (.dict-word) -> 交由 dictionary.js 直接查词 & 加入生词本（绝不触发整句画线！）
    //    - 仅当点击在已画线的词间空白 (.dict-sep.is-user-underlined) 或未收录于词典的已画线词上时，平滑擦除该段画线
    passageCard.addEventListener('click', (e) => {
        if (window._suppressNextLookupClickUntil && Date.now() < window._suppressNextLookupClickUntil) {
            return;
        }
        if (isInteractiveBlank(e.target)) return;

        let underlinedWord = e.target.closest('.dict-word.is-user-underlined');
        if (!underlinedWord) {
            const sep = e.target.closest('.dict-sep.is-user-underlined');
            if (sep) {
                const prev = sep.previousElementSibling;
                if (prev && prev.classList.contains('dict-word') && prev.classList.contains('is-user-underlined')) {
                    underlinedWord = prev;
                }
            }
        }
        if (underlinedWord && passageCard.contains(underlinedWord)) {
            e.stopPropagation();
            eraseContiguousUnderlineSpan(underlinedWord, passageCard);
        }
    });

    // 2. 横向笔触滑动自由选词画线 / 擦除 (Pen-Glide Range Underline，与轻点查词完全正交无冲突)
    let glideState = null;

    const startGlideCandidate = (clientX, clientY, target) => {
        if (isInteractiveBlank(target)) {
            glideState = null;
            return;
        }
        const startWord = findWordNearPoint(passageCard, clientX, clientY, null);
        if (!startWord || isInteractiveBlank(startWord)) {
            glideState = null;
            return;
        }
        const paraEl = startWord.closest('p') || passageCard;
        const paraWords = Array.from(paraEl.querySelectorAll('.dict-word')).filter(w => !isInteractiveBlank(w));
        const startPos = paraWords.indexOf(startWord);
        if (startPos === -1) {
            glideState = null;
            return;
        }

        glideState = {
            startX: clientX,
            startY: clientY,
            paraEl,
            paraWords,
            wordRects: null,
            startPos,
            lastPos: startPos,
            isGliding: false,
            mode: startWord.classList.contains('is-user-underlined') ? 'erase' : 'add',
            snapshot: paraWords.map(w => w.classList.contains('is-user-underlined'))
        };
    };

    const moveGlideCandidate = (clientX, clientY, ev) => {
        if (!glideState) {
            return;
        }
        const dx = clientX - glideState.startX;
        const dy = clientY - glideState.startY;

        if (!glideState.isGliding) {
            // 垂直滚动优先放行，绝不卡页面上下滑动
            if (Math.abs(dy) > 15 && Math.abs(dy) > Math.abs(dx) * 1.15) {
                glideState = null;
                return;
            }
            // 水平笔触位移 >= 10px 立即进入实时自由选词画线/擦除状态
            if (Math.abs(dx) >= 10 && Math.abs(dx) > Math.abs(dy) * 1.15) {
                glideState.isGliding = true;
                glideState.wordRects = glideState.paraWords.map(w => ({ el: w, rect: w.getBoundingClientRect() }));
                window._suppressNextLookupClickUntil = Date.now() + 450;
                dismissGestureWhisperPill(true);
                if (typeof window.closeTopMenuHint === 'function') {
                    window.closeTopMenuHint(false);
                }
                const activePopover = document.getElementById('dict-popover');
                if (activePopover && activePopover.classList.contains('active')) {
                    activePopover.classList.remove('active');
                }
                const shouldUnderline = glideState.mode === 'add';
                if (glideState.paraWords[glideState.startPos]) {
                    glideState.paraWords[glideState.startPos].classList.toggle('is-user-underlined', shouldUnderline);
                    syncParagraphUnderlineSeparators(glideState.paraEl);
                }
                if (navigator && typeof navigator.vibrate === 'function') {
                    try { navigator.vibrate(8); } catch (e) {}
                }
            } else {
                return;
            }
        }

        if (ev && ev.cancelable) {
            try { ev.preventDefault(); } catch (err) {}
        }
        window._suppressNextLookupClickUntil = Date.now() + 450;

        const curWord = findWordNearPoint(passageCard, clientX, clientY, glideState.paraEl, glideState.wordRects);
        if (!curWord) return;
        const curPos = glideState.paraWords.indexOf(curWord);
        if (curPos === -1 || curPos === glideState.lastPos) return;
        glideState.lastPos = curPos;

        const minPos = Math.min(glideState.startPos, curPos);
        const maxPos = Math.max(glideState.startPos, curPos);
        const shouldUnderline = glideState.mode === 'add';

        glideState.paraWords.forEach((w, idx) => {
            const inRange = idx >= minPos && idx <= maxPos;
            const targetVal = inRange ? shouldUnderline : glideState.snapshot[idx];
            w.classList.toggle('is-user-underlined', targetVal);
        });

        syncParagraphUnderlineSeparators(glideState.paraEl);
    };

    const endGlideCandidate = () => {
        if (!glideState) return;
        if (glideState.isGliding) {
            const minPos = Math.min(glideState.startPos, glideState.lastPos);
            const maxPos = Math.max(glideState.startPos, glideState.lastPos);
            const shouldUnderline = glideState.mode === 'add';
            for (let i = minPos; i <= maxPos; i++) {
                if (glideState.paraWords[i]) {
                    glideState.paraWords[i].classList.toggle('is-user-underlined', shouldUnderline);
                }
            }
            syncParagraphUnderlineSeparators(glideState.paraEl);
            persistPassageUnderlines(passageCard);
            window._suppressNextLookupClickUntil = Date.now() + 380;
            if (window.FeedbackEngine && typeof window.FeedbackEngine.playTap === 'function') {
                window.FeedbackEngine.playTap();
            }
        }
        glideState = null;
    };

    passageCard.addEventListener('touchstart', (e) => {
        if (e.touches && e.touches.length === 1) {
            startGlideCandidate(e.touches[0].clientX, e.touches[0].clientY, e.target);
        }
    }, { passive: true });

    passageCard.addEventListener('touchmove', (e) => {
        if (e.touches && e.touches.length === 1) {
            moveGlideCandidate(e.touches[0].clientX, e.touches[0].clientY, e);
        }
    }, { passive: false });

    passageCard.addEventListener('touchend', endGlideCandidate, { passive: true });
    passageCard.addEventListener('touchcancel', () => { glideState = null; }, { passive: true });

    passageCard.addEventListener('mousedown', (e) => {
        if (e.button === 0) {
            startGlideCandidate(e.clientX, e.clientY, e.target);
        }
    });
    passageCard.addEventListener('mousemove', (e) => {
        if (glideState && (e.buttons & 1)) {
            moveGlideCandidate(e.clientX, e.clientY, e);
        }
    });
    window.addEventListener('mouseup', () => {
        if (glideState) endGlideCandidate();
    });
}
window.initPassageUserUnderline = initPassageUserUnderline;



window.clearEvidenceHighlightInPassage = clearEvidenceHighlightInPassage;
window.highlightEvidenceInPassage = highlightEvidenceInPassage;
window.persistEliminatedOptions = persistEliminatedOptions;


/* === js/written_passage_renderer.js === */
// ==========================================================================
// Written Reading Passage & Bilingual Translation Pane Renderer (js/written_passage_renderer.js)
// ==========================================================================
function renderWrittenPassagePane(ctx) {
    const { index, q, isExam, canUseB, passPane, passageCard, transCard } = ctx;
    const isFullPassageTrans = Boolean(
        q.type === 'translation_en_zh' &&
        q.passage &&
        q.source_en &&
        q.passage.trim() === q.source_en.trim()
    );

    if (passageCard) {
        if (!passageCard._interactiveBlankDelegateBound) {
            passageCard._interactiveBlankDelegateBound = true;
            passageCard.addEventListener('click', (e) => {
                const blankEl = e.target && e.target.closest
                    ? e.target.closest('.written-cloze-blank, .seven-blank-reflected, .fill-blank-reflected')
                    : null;
                if (blankEl) {
                    e.stopPropagation();
                    if (window.UXReadingSplitSheet && typeof window.UXReadingSplitSheet.ensureHalfForInteraction === 'function') {
                        window.UXReadingSplitSheet.ensureHalfForInteraction('blank');
                    }
                    const targetBlankId = parseInt(blankEl.dataset.blankId, 10);
                    if (!isNaN(targetBlankId)) {
                        const targetIdx = (currentWrittenQuestions || []).findIndex(item => item.id === targetBlankId || parseInt(item.id, 10) === targetBlankId);
                        if (targetIdx >= 0) {
                            renderWrittenQuestion(targetIdx, { preserveScroll: true });
                            setTimeout(() => {
                                const nextInput = document.getElementById(`grammar-input-${targetBlankId}`);
                                if (nextInput) {
                                    nextInput.focus();
                                    const nLen = (nextInput.value || '').length;
                                    try { nextInput.setSelectionRange(nLen, nLen); } catch (err) {}
                                }
                            }, 80);
                        }
                    }
                    return;
                }

                const sqEl = e.target && e.target.closest ? e.target.closest('.sentence-insert-square') : null;
                if (sqEl) {
                    e.stopPropagation();
                    const curIdx = (typeof currentWrittenQIndex === 'number') ? currentWrittenQIndex : 0;
                    const curQ = (currentWrittenQuestions || [])[curIdx];
                    if (curQ) {
                        const sq = sqEl.dataset.square;
                        selectWrittenOption(curQ.id, sq, curQ.answer);
                        renderWrittenQuestion(curIdx, { preserveScroll: true });
                    }
                    return;
                }

                const transBadgeEl = e.target && e.target.closest ? e.target.closest('.trans-marker-badge') : null;
                if (transBadgeEl) {
                    e.stopPropagation();
                    const targetId = parseInt(transBadgeEl.dataset.transId, 10);
                    if (!isNaN(targetId)) {
                        const targetIdx = (currentWrittenQuestions || []).findIndex(item => parseInt(item.id, 10) === targetId);
                        if (targetIdx >= 0) {
                            renderWrittenQuestion(targetIdx, { preserveScroll: true });
                        }
                    }
                }
            });
        }

        if (typeof clearEvidenceHighlightInPassage === 'function') {
            clearEvidenceHighlightInPassage(passageCard);
        }

        if (q.type === 'matching' || q.type === 'translation' || q.type === 'writing' || isFullPassageTrans || !q.passage || !q.passage.trim()) {
            passageCard.style.display = 'none';
            passageCard._renderedPassageKey = '';
        } else {
            passageCard.style.display = 'block';
            const currentPassageKey = `${currentWrittenExamTitle}::${q.type}::${q.sub_type === 'info_matching' ? q.id : ''}::${isExam}::${(q.passage || '').trim().slice(0, 64)}::${(q.passage || '').length}`;
            const canPatchClozeInPlace = (
                (q.type === 'cloze' || q.type === 'banked_cloze' || q.type === 'cloze_choice') &&
                passageCard._renderedPassageKey === currentPassageKey &&
                passageCard.querySelectorAll('.written-cloze-blank').length > 0
            );
            const canReuseCarefulInPlace = (
                q.type === 'careful' &&
                passageCard._renderedPassageKey === currentPassageKey &&
                passageCard.children.length > 0
            );

            if (canPatchClozeInPlace) {
                passageCard.querySelectorAll('.written-cloze-blank').forEach(el => {
                    const blankId = parseInt(el.dataset.blankId);
                    const filled = userWrittenAnswers[currentWrittenExamTitle]?.[blankId];
                    const isCurrentBlank = (blankId === q.id || blankId === parseInt(q.id));
                    const targetQ = currentWrittenQuestions.find(it => it.id === blankId || parseInt(it.id) === blankId) || q;
                    const rawWord = (filled && targetQ.options && targetQ.options[filled.selected]) ? targetQ.options[filled.selected] : (filled ? filled.selected : '');
                    const wordVal = filled ? (rawWord && rawWord !== filled.selected ? rawWord : filled.selected) : '';

                    if (filled) {
                        const isRight = filled.isCorrect;
                        const fillClass = isExam ? 'filled-exam' : (isRight ? 'filled-correct' : 'filled-wrong');
                        const badgeColor = isExam ? '#007AFF' : (isRight ? '#15803D' : '#DC2626');
                        const badgeBg = isExam ? 'rgba(0, 122, 255, 0.12)' : (isRight ? 'rgba(52, 199, 89, 0.15)' : 'rgba(255, 59, 48, 0.13)');
                        el.className = `written-cloze-blank ${isCurrentBlank ? 'active ' : ''}${fillClass}`;
                        el.style.background = badgeBg;
                        el.style.color = badgeColor;
                        el.style.padding = '1px 9px';
                        el.style.fontSize = '13.5px';
                        el.textContent = `${blankId}. ${wordVal}`;
                    } else if (isCurrentBlank) {
                        el.className = 'written-cloze-blank active';
                        el.style.background = '#007AFF';
                        el.style.color = '#FFFFFF';
                        el.style.padding = '1px 10px';
                        el.style.fontSize = '13.5px';
                        el.textContent = `${blankId}`;
                    } else {
                        el.className = 'written-cloze-blank';
                        el.style.background = 'rgba(0, 122, 255, 0.09)';
                        el.style.color = '#007AFF';
                        el.style.padding = '1px 9px';
                        el.style.fontSize = '13px';
                        el.textContent = `${blankId}`;
                    }
                });
                const activeBlankEl = passageCard.querySelector('.written-cloze-blank.active');
                if (activeBlankEl) {
                    scrollElementIntoPane(activeBlankEl, passPane);
                }
            } else if (canReuseCarefulInPlace) {
                // 同一篇阅读理解切换小题（如 Q21 -> Q22）时直接复用已渲染 DOM，零重排、零闪烁
            } else if (q.type === 'proofread') {
                passageCard._renderedPassageKey = '';
                const proofreadKey = 'proofread_' + currentWrittenExamTitle;
                const canPracticeNow = (!window.ToyPermissions || typeof window.ToyPermissions.canUsePracticeMode !== 'function' || window.ToyPermissions.canUsePracticeMode());
                const isRevealed = canPracticeNow && ((revealedModelKeys[proofreadKey] !== undefined)
                    ? !!revealedModelKeys[proofreadKey]
                    : false);

                if (!isRevealed) {
                    renderActiveProofreadPassage(passageCard, q, index);
                } else {
                    renderRevealedProofreadPassage(passageCard, q, index);
                }
            } else if (q.type === 'cloze' || q.type === 'banked_cloze' || q.type === 'cloze_choice' || q.type === 'seven_out_of_five' || q.type === 'fill_in' || q.type === 'sentence_insertion') {
                passageCard._renderedPassageKey = currentPassageKey;
                let pText = q.passage || '';
                pText = makeTextClickable(pText);

                // 1. 七选五空格动态展开
                if (q.type === 'seven_out_of_five') {
                    pText = pText.replace(/(?:_{2,}\s*(\d+)\s*_{2,}|\[\s*(\d+)\s*\]|【\s*(\d+)\s*】|\(\s*(\d+)\s*\))/g, (match, b1, b2, b3, b4) => {
                        const blankId = parseInt(b1 || b2 || b3 || b4);
                        if (isNaN(blankId) || blankId < 31 || blankId > 50) return match;
                        const filled = userWrittenAnswers[currentWrittenExamTitle]?.[blankId];
                        const isCurrentBlank = (blankId === q.id || blankId === parseInt(q.id));
                        const targetQ = currentWrittenQuestions.find(it => it.id === blankId || parseInt(it.id) === blankId) || q;
                        const optText = (filled && targetQ.options && targetQ.options[filled.selected]) ? targetQ.options[filled.selected] : '';

                        if (filled) {
                            const optDisplay = optText ? `<span>${makeTextClickable(optText)}</span>` : `<span>选项 ${filled.selected}</span>`;
                            const isRight = filled.isCorrect;
                            const badgeClass = isExam ? 'filled exam' : (isRight ? 'filled correct' : 'filled wrong');
                            const color = isExam ? '#0284c7' : (isRight ? 'var(--correct-green)' : 'var(--wrong-red)');
                            const bg = isExam ? '#f8fafc' : (isRight ? 'var(--correct-bg)' : 'var(--wrong-bg)');
                            const border = isExam ? '#0284c7' : (isRight ? 'var(--correct-green)' : 'var(--wrong-red)');
                            return `<span class="seven-blank-reflected ${badgeClass} ${isCurrentBlank ? 'active' : ''}" data-blank-id="${blankId}" style="background:${bg}; border-color:${border};"><span style="color:${color}; font-weight:800; margin-right:8px;">[${blankId}. ${filled.selected}]</span>${optDisplay}</span>`;
                        } else {
                            return `<span class="seven-blank-reflected unfilled ${isCurrentBlank ? 'active' : ''}" data-blank-id="${blankId}"><span style="font-weight:700;">[ 📑 空格 ${blankId} · 点击此处作答 ]</span></span>`;
                        }
                    });
                } else if (q.type === 'fill_in') {
                    // 2. 语法填空空格动态回填
                    pText = pText.replace(/(?:_{2,}\s*(\d+)\s*_{2,}|\[\s*(\d+)\s*\]|【\s*(\d+)\s*】|\(\s*(\d+)\s*\))/g, (match, b1, b2, b3, b4) => {
                        const blankId = parseInt(b1 || b2 || b3 || b4);
                        const filled = userWrittenAnswers[currentWrittenExamTitle]?.[blankId];
                        const isCurrentBlank = (blankId === q.id || blankId === parseInt(q.id));
                        const targetQ = currentWrittenQuestions.find(it => it.id === blankId || parseInt(it.id) === blankId) || q;

                        if (filled) {
                            const isRight = filled.isCorrect;
                            const badgeClass = isExam ? 'filled-exam' : (isRight ? 'correct' : 'wrong');
                            const valText = isExam ? filled.selected : (isRight ? `${filled.selected} ✓` : `${filled.selected} ➔ ${targetQ.answer || targetQ.word || ''}`);
                            return `<span class="fill-blank-reflected ${badgeClass} ${isCurrentBlank ? 'active' : ''}" data-blank-id="${blankId}">[${blankId}. ${valText}]</span>`;
                        } else {
                            return `<span class="fill-blank-reflected unfilled ${isCurrentBlank ? 'active' : ''}" data-blank-id="${blankId}">[${blankId}]</span>`;
                        }
                    });
                } else if (q.type === 'sentence_insertion') {
                    // 3. 托福黑方块插句
                    pText = pText.replace(/(?:\[■\s*([A-D])\]|■\s*\[?([A-D])\]?|\[([A-D])\])/gi, (match, s1, s2, s3) => {
                        const sq = (s1 || s2 || s3).toUpperCase();
                        const filled = userWrittenAnswers[currentWrittenExamTitle]?.[q.id];
                        const isChosen = (filled && filled.selected === sq);
                        if (isChosen) {
                            const isRight = filled.isCorrect;
                            const cls = isExam ? 'exam' : (isRight ? 'correct' : 'wrong');
                            return `<span class="sentence-inserted-content ${cls}">【■ ${sq}】${makeTextClickable(q.insert_sentence || q.sentence || '')}</span>`;
                        }
                        return ` <span class="sentence-insert-square" data-square="${sq}">■ ${sq}</span> `;
                    });
                } else {
                    // 4. 完形填空 / 选词填空 (iOS 极简扁平胶囊风格，无括号、无双层发光边框)
                    pText = pText.replace(/(?:_{2,}\s*(\d+)\s*_{2,}|\[\s*(\d+)\s*\]|【\s*(\d+)\s*】|\(\s*(\d+)\s*\))/g, (match, b1, b2, b3, b4) => {
                        const blankId = parseInt(b1 || b2 || b3 || b4);
                        const filled = userWrittenAnswers[currentWrittenExamTitle]?.[blankId];
                        const isCurrentBlank = (blankId === q.id || blankId === parseInt(q.id));
                        const targetQ = currentWrittenQuestions.find(it => it.id === blankId || parseInt(it.id) === blankId) || q;
                        const rawWord = (filled && targetQ.options && targetQ.options[filled.selected]) ? targetQ.options[filled.selected] : (filled ? filled.selected : '');
                        const wordVal = filled ? (rawWord && rawWord !== filled.selected ? rawWord : filled.selected) : '';
                        let badgeHtml = '';

                        if (filled) {
                            const isRight = filled.isCorrect;
                            const fillClass = isExam ? 'filled-exam' : (isRight ? 'filled-correct' : 'filled-wrong');
                            const badgeColor = isExam ? '#007AFF' : (isRight ? '#15803D' : '#DC2626');
                            const badgeBg = isExam ? 'rgba(0, 122, 255, 0.12)' : (isRight ? 'rgba(52, 199, 89, 0.15)' : 'rgba(255, 59, 48, 0.13)');
                            const activeClass = isCurrentBlank ? 'active' : '';
                            badgeHtml = `<span class="written-cloze-blank ${activeClass} ${fillClass}" data-blank-id="${blankId}" style="text-indent:0 !important; display:inline-block; vertical-align:baseline; text-align:center; padding:1px 9px; font-size:13.5px; background:${badgeBg}; color:${badgeColor}; border-radius:6px; border:none; box-shadow:none; font-weight:600; cursor:pointer;">${blankId}. ${wordVal}</span>`;
                        } else if (isCurrentBlank) {
                            badgeHtml = `<span class="written-cloze-blank active" data-blank-id="${blankId}" style="text-indent:0 !important; display:inline-block; vertical-align:baseline; text-align:center; padding:1px 10px; font-size:13.5px; background:#007AFF; color:#FFFFFF; border-radius:6px; border:none; box-shadow:none; font-weight:600; cursor:pointer;">${blankId}</span>`;
                        } else {
                            badgeHtml = `<span class="written-cloze-blank" data-blank-id="${blankId}" style="text-indent:0 !important; display:inline-block; vertical-align:baseline; text-align:center; padding:1px 9px; font-size:13px; background:rgba(0, 122, 255, 0.09); color:#007AFF; border-radius:6px; border:none; box-shadow:none; font-weight:600; cursor:pointer;">${blankId}</span>`;
                        }
                        return ` ${badgeHtml} `;
                    });
                }

                const dirsBannerHtml = (q.type === 'seven_out_of_five' && q.directions)
                    ? `<div style="font-size:13px; color:#3A3A3C; background:rgba(0,0,0,0.03); border-radius:10px; padding:10px 14px; margin-bottom:12px; line-height:1.6;"><strong style="color:#007AFF;">题型说明：</strong>${makeTextClickable(q.directions)}</div>`
                    : '';

                passageCard.innerHTML = `
                    ${dirsBannerHtml}
                    ${pText.split(/\n+/).map(p => p.trim()).filter(Boolean).map(para => `<p>${para}</p>`).join('')}
                `;

                if (q.type === 'seven_out_of_five' && q.sub_type === 'info_matching') {
                    const mEntity = (q.question_text || '').match(/【([^】]+)】/);
                    if (mEntity && mEntity[1]) {
                        const cleanEntity = mEntity[1].replace(/\s+(?:held|argued|believed|pointed\s+out|claimed|suggested|stated|noted)\s+that$/i, '').trim();
                        const tokens = cleanEntity.split(/\s+/).filter(Boolean);
                        const lastToken = tokens.length > 0 ? tokens[tokens.length - 1].toLowerCase() : '';
                        const paras = Array.from(passageCard.querySelectorAll('p'));
                        let matchedPara = paras.find(p => p.textContent.toLowerCase().includes(cleanEntity.toLowerCase()));
                        if (!matchedPara && lastToken && lastToken.length >= 3) {
                            matchedPara = paras.find(p => p.textContent.toLowerCase().includes(lastToken));
                        }
                        if (matchedPara) {
                            matchedPara.classList.add('active-info-match-para');
                            matchedPara.style.cssText = 'background:rgba(0, 122, 255, 0.06); border-left:3px solid #007AFF; padding:8px 12px; border-radius:8px; transition:background 0.2s ease;';
                        }
                    }
                }

                // 自动将当前题号对应的空格或匹配段落平滑滚动至左栏可视区域中心（不抖动外层窗口）
                setTimeout(() => {
                    const activeBlankEl = passageCard.querySelector(`.written-cloze-blank.active, .seven-blank-reflected.active, .fill-blank-reflected.active, .active-info-match-para`);
                    if (activeBlankEl) {
                        scrollElementIntoPane(activeBlankEl, passPane);
                    }
                }, 30);
            } else if (q.type === 'careful' || q.type === 'translation_en_zh') {
                passageCard._renderedPassageKey = (q.type === 'careful') ? currentPassageKey : '';
                let rawP = (q.passage || '');
                let renderedParas = rawP.split(/\n+/).map(p => p.trim()).filter(Boolean).map(para => {
                    let clicked = makeTextClickable(para);
                    if (q.type === 'translation_en_zh') {
                        clicked = clicked.replace(/\((\d{2})\)/g, (m, numStr) => {
                            const numId = parseInt(numStr, 10);
                            const isCurrent = (numId === parseInt(q.id, 10));
                            const bg = isCurrent ? '#007AFF' : 'rgba(0, 122, 255, 0.10)';
                            const fg = isCurrent ? '#FFFFFF' : '#007AFF';
                            const cls = isCurrent ? 'active-trans-marker trans-marker-badge' : 'trans-marker-badge';
                            return `<strong class="${cls}" data-trans-id="${numId}" style="color:${fg}; background:${bg}; padding:1px 8px; border-radius:6px; font-weight:600; cursor:pointer; margin-right:3px;">(${numId})</strong>`;
                        });
                    }
                    return `<p>${clicked}</p>`;
                }).join('');
                passageCard.innerHTML = `
                    ${renderedParas}
                `;
                if (q.type === 'translation_en_zh') {
                    setTimeout(() => {
                        const marked = q.source_en
                            ? highlightEvidenceInPassage({ id: '', evidence_en: q.source_en }, { autoScrollSplit: true })
                            : null;
                        if (!marked) {
                            const markerEl = passageCard.querySelector('.active-trans-marker');
                            if (markerEl) scrollElementIntoPane(markerEl, passPane);
                        }
                    }, 30);
                }
            }
            if (q.type !== 'proofread' && typeof window.initPassageUserUnderline === 'function') {
                window.initPassageUserUnderline(passageCard, `${currentWrittenExamTitle || 'default'}::${(q.passage || '').trim().slice(0, 48)}`);
            }
        }
    }

    if (transCard) {
        const canShowTrans = canUseB && !isFullPassageTrans && q.translation_zh && (q.type === 'cloze' || q.type === 'careful' || q.type === 'seven_out_of_five' || q.type === 'cloze_choice' || q.type === 'fill_in' || q.type === 'banked_cloze' || q.type === 'translation_en_zh');
        transCard.style.display = (window.showWrittenBilingual && canShowTrans) ? 'block' : 'none';
        if (canShowTrans) {
            transCard.innerHTML = `
                <div style="font-size:12.5px; font-weight:700; color:var(--accent-gold); margin-bottom:12px;">📜 全文参考译文</div>
                ${q.translation_zh.split(/\n+/).map(p => p.trim()).filter(Boolean).map(p => `<p style="font-size:14.5px; color:#3f3f46; line-height:1.76; margin-bottom:14px; text-indent:2em;">${p}</p>`).join('')}
            `;
        }
    }

    // 3.5 Determine if split container should be in single-column full-width mode (no reading passage)
    const splitContainer = document.querySelector('.written-split-container');
    const passageCol = document.querySelector('.written-split-passage');
    const hasPassage = !!(passageCard && passageCard.style.display !== 'none' && passageCard.innerHTML.trim().length > 0);
    const hasTrans = !!(transCard && transCard.style.display !== 'none' && transCard.innerHTML.trim().length > 0);
    const hasLeftContent = hasPassage || hasTrans;

    if (splitContainer) {
        splitContainer.classList.toggle('no-passage-mode', !hasLeftContent);
    }
    if (passageCol) {
        passageCol.style.display = hasLeftContent ? '' : 'none';
    }

    return { hasPassage, hasTrans, hasLeftContent };
}
window.renderWrittenPassagePane = renderWrittenPassagePane;


/* === js/written_question_objective.js === */
// ==========================================================================
// Written Objective, Proofread & Fill-in Question Renderers (js/written_question_objective.js)
// ==========================================================================
function renderWrittenObjectiveQuestion(ctx) {
    const {
        index, q, isExam, canUseB, ansRecord, isAnswered,
        writtenStageCard, passPane, passageCard, optionsWrapper,
        explanationCard, showWrittenExplanation
    } = ctx;
    if (!optionsWrapper) return false;
        if (q.type === 'proofread') {
            const proofreadKey = 'proofread_' + currentWrittenExamTitle;
            const canPracticeNow = (!window.ToyPermissions || typeof window.ToyPermissions.canUsePracticeMode !== 'function' || window.ToyPermissions.canUsePracticeMode());
            const isRevealed = canPracticeNow && ((revealedModelKeys[proofreadKey] !== undefined)
                ? !!revealedModelKeys[proofreadKey]
                : false);

            const allProofread = currentWrittenQuestions.filter(item => item.type === 'proofread');
            const cleanedPassageForStats = cleanProofreadRawPassage(q.passage);
            const slicesForStats = computeProofreadSlices(cleanedPassageForStats, allProofread);
            const userAns = userWrittenAnswers[currentWrittenExamTitle] || {};
            const stats = getProofreadStats(userAns, slicesForStats);

            let badgeHtml = '';
            if (isRevealed) {
                badgeHtml = '✅ 参考批改与考点精析';
            } else {
                badgeHtml = `已修改 <b id="proofread-done-count">${stats.total}</b>/10 处`;
            }

            const wrapper = document.createElement('div');
            wrapper.style.width = '100%';

            const compactBar = document.createElement('div');
            compactBar.className = `proofread-compact-bar ${isRevealed ? 'revealed' : ''}`;
            compactBar.innerHTML = `
                <div class="proofread-status-info">
                    <span class="proofread-status-title">${isRevealed ? '🛠️ 参考订正' : '📝 短文改错'}</span>
                    <span class="proofread-status-badge ${isRevealed ? 'success' : ''}">
                        ${badgeHtml}
                    </span>
                </div>
                <div class="proofread-bar-buttons">
                    ${!isRevealed ? '<button type="button" class="btn-proofread-clear" id="btn-proofread-clear">↺ 一键清空作答</button>' : ''}
                    <button type="button" class="btn-proofread-toggle" id="btn-proofread-toggle-mode">
                        ${isRevealed ? '返回自主改错作答' : '查看参考批改与全题解析'}
                    </button>
                </div>
            `;

            wrapper.appendChild(compactBar);

            if (!isRevealed) {
                const btnClear = compactBar.querySelector('#btn-proofread-clear');
                if (btnClear) {
                    btnClear.addEventListener('click', () => {
                        if (!userWrittenAnswers[currentWrittenExamTitle]) return;
                        const nowTs = Date.now();
                        const keysToDelete = Object.keys(userWrittenAnswers[currentWrittenExamTitle]).filter(k => k.startsWith('C') || k.startsWith('custom_') || k.startsWith('add_'));
                        if (currentWrittenExamTitle) {
                            if (!window.completedExams[currentWrittenExamTitle]) window.completedExams[currentWrittenExamTitle] = {};
                            if (!window.completedExams[currentWrittenExamTitle].writtenAnswers) {
                                window.completedExams[currentWrittenExamTitle].writtenAnswers = {};
                            }
                            window.completedExams[currentWrittenExamTitle].timestamp = nowTs;
                        }
                        keysToDelete.forEach(k => {
                            delete userWrittenAnswers[currentWrittenExamTitle][k];
                            if (currentWrittenExamTitle) {
                                window.completedExams[currentWrittenExamTitle].writtenAnswers[k] = {
                                    _deleted: true,
                                    ts: nowTs
                                };
                            }
                        });
                        saveUserCloudData(currentWrittenExamTitle);
                        updateDashboardStats();
                        submitUserScore();
                        renderWrittenQuestion(index, { preserveScroll: true });
                    });
                }
            }

            const btnToggle = compactBar.querySelector('#btn-proofread-toggle-mode');
            if (btnToggle) {
                btnToggle.addEventListener('click', () => {
                    if (!isRevealed && window.ToyPermissions && typeof window.ToyPermissions.canUsePracticeMode === 'function' && !window.ToyPermissions.canUsePracticeMode()) {
                        window.ToyPermissions.showUnlockModal('practice_mode');
                        return;
                    }
                    revealedModelKeys[proofreadKey] = !isRevealed;
                    renderWrittenQuestion(index, { preserveScroll: true });
                });
            }

            optionsWrapper.appendChild(wrapper);

            if (explanationCard) {
                explanationCard.classList.remove('show');
            }
            if (writtenStageCard) writtenStageCard.classList.add('answered-state');

        } else if (q.type === 'fill_in') {
            const fillWrapper = document.createElement('div');
            fillWrapper.className = 'grammar-container';

            const curAns = userWrittenAnswers[currentWrittenExamTitle]?.[q.id];
            const inputVal = curAns ? curAns.selected : '';

            const allFillIn = (currentWrittenQuestions || []).filter(item => item.type === 'fill_in');
            const isLastBlank = (allFillIn.length > 0 && (allFillIn[allFillIn.length - 1].id === q.id || parseInt(allFillIn[allFillIn.length - 1].id) === parseInt(q.id)));
            const btnLabel = isLastBlank ? '完成 ✓' : '下一空 ➔';

            // 即时反馈文案 (随刷随解模式)
            const escGrammarHtml = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
            let feedbackHtml = '';
            if (curAns && !isExam) {
                feedbackHtml = curAns.isCorrect 
                    ? '<div class="grammar-feedback-msg correct">✅ 回答正确！</div>' 
                    : `<div class="grammar-feedback-msg wrong">❌ 标准答案: <strong>${escGrammarHtml(q.answer || q.word)}</strong></div>`;
            }

            fillWrapper.innerHTML = `
                <div class="grammar-ios-bar">
                    <span class="grammar-stem-text">Question ${q.id}.</span>
                    <input 
                        type="text" 
                        class="grammar-fill-input" 
                        id="grammar-input-${q.id}" 
                        placeholder="输入英文单词..." 
                        value=""
                        autocapitalize="none" 
                        autocomplete="off" 
                        autocorrect="off" 
                        spellcheck="false"
                    />
                    <button type="button" class="grammar-btn-next" id="btn-grammar-next-${q.id}">
                        ${btnLabel}
                    </button>
                </div>
                <div id="grammar-feedback-${q.id}" class="grammar-feedback-box" style="${feedbackHtml ? 'display:block;' : 'display:none;'}">
                    ${feedbackHtml}
                </div>
            `;
            optionsWrapper.appendChild(fillWrapper);

            const inputEl = fillWrapper.querySelector(`#grammar-input-${q.id}`);
            if (inputEl && inputVal) inputEl.value = inputVal;
            const btnNext = fillWrapper.querySelector(`#btn-grammar-next-${q.id}`);
            const feedbackEl = fillWrapper.querySelector(`#grammar-feedback-${q.id}`);

            // 移动端软键盘弹出防遮挡 (Auto-center on mobile keyboard show)
            inputEl.addEventListener('focus', () => {
                setTimeout(() => {
                    fillWrapper.scrollIntoView({ behavior: 'smooth', block: 'center' });
                }, 220);
            });

            // 实时字符级动态回填 (Live Reflection)
            inputEl.addEventListener('input', () => {
                const val = (inputEl.value || '').trim();
                const reflected = passageCard ? passageCard.querySelector(`.fill-blank-reflected[data-blank-id="${q.id}"]`) : null;
                if (reflected) {
                    if (val) {
                        const badgeClass = isExam ? 'filled-exam active' : 'active';
                        reflected.className = `fill-blank-reflected ${badgeClass}`;
                        reflected.textContent = `[${q.id}. ${val}]`;
                    } else {
                        reflected.className = 'fill-blank-reflected unfilled active';
                        reflected.textContent = `[${q.id}]`;
                    }
                }
            });

            // 提交并自动流转至下一空 (Auto-advance on Enter / Click Next)
            const handleGrammarSubmitAndNext = () => {
                const val = (inputEl.value || '').trim();
                const targetAns = (q.answer || q.word || '').trim();

                if (val) {
                    const isRight = checkIsCorrect(val, targetAns);
                    selectWrittenOption(q.id, val, targetAns);

                    if (feedbackEl && !isExam) {
                        feedbackEl.style.display = 'block';
                        feedbackEl.innerHTML = isRight 
                            ? '<div class="grammar-feedback-msg correct">✅ 回答正确！</div>' 
                            : `<div class="grammar-feedback-msg wrong">❌ 标准答案: <strong>${targetAns}</strong></div>`;
                    }

                    const reflected = passageCard ? passageCard.querySelector(`.fill-blank-reflected[data-blank-id="${q.id}"]`) : null;
                    if (reflected) {
                        const badgeClass = isExam ? 'filled-exam' : (isRight ? 'correct' : 'wrong');
                        const valText = isExam ? val : (isRight ? `${val} ✓` : `${val} ➔ ${targetAns}`);
                        reflected.className = `fill-blank-reflected ${badgeClass}`;
                        reflected.textContent = `[${q.id}. ${valText}]`;
                    }

                    if (explanationCard && !isExam) {
                        showWrittenExplanation(q);
                    }
                    if (writtenStageCard) writtenStageCard.classList.add('answered-state');
                }

                // 自动跳下一空
                const nextFillInIdx = currentWrittenQuestions.findIndex((item, i) => i > index && item.type === 'fill_in');
                if (nextFillInIdx >= 0) {
                    renderWrittenQuestion(nextFillInIdx, { preserveScroll: true });
                    setTimeout(() => {
                        const nextQ = currentWrittenQuestions[nextFillInIdx];
                        const nextInp = document.getElementById(`grammar-input-${nextQ.id}`);
                        if (nextInp) {
                            nextInp.focus();
                            const nLen = (nextInp.value || '').length;
                            try { nextInp.setSelectionRange(nLen, nLen); } catch(e) {}
                        }
                        const nextBlankEl = document.querySelector(`.fill-blank-reflected[data-blank-id="${nextQ.id}"]`);
                        if (nextBlankEl) {
                            scrollElementIntoPane(nextBlankEl, passPane);
                        }
                    }, 80);
                } else {
                    // 已是最后一空
                    renderWrittenQuestion(index, { preserveScroll: true });
                }
            };

            btnNext.addEventListener('click', handleGrammarSubmitAndNext);
            inputEl.addEventListener('keydown', (e) => {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    handleGrammarSubmitAndNext();
                }
            });

            if (explanationCard && !isExam) {
                showWrittenExplanation(q);
                if (curAns && writtenStageCard) writtenStageCard.classList.add('answered-state');
            }

            // 确保当前空格平滑滚动可见
            setTimeout(() => {
                const curBlank = passageCard ? passageCard.querySelector(`.fill-blank-reflected[data-blank-id="${q.id}"]`) : null;
                if (curBlank) {
                    scrollElementIntoPane(curBlank, passPane);
                }
            }, 60);

        } else if (q.type === 'tfng' || q.type === 'true_false_not_given' || q.type === 'yes_no_not_given') {
            const isYNNG = (q.type === 'yes_no_not_given' || (q.answer && ['YES', 'NO'].includes(q.answer.toUpperCase())));
            const tfngOptions = isYNNG 
                ? [{ key: 'YES', label: 'YES' }, { key: 'NO', label: 'NO' }, { key: 'NOT GIVEN', label: 'NOT GIVEN' }]
                : [{ key: 'TRUE', label: 'TRUE' }, { key: 'FALSE', label: 'FALSE' }, { key: 'NOT GIVEN', label: 'NOT GIVEN' }];

            const grid = document.createElement('div');
            grid.className = 'tfng-grid';

            tfngOptions.forEach(opt => {
                const btn = document.createElement('button');
                btn.className = 'tfng-btn';
                btn.textContent = opt.label;

                if (isExam) {
                    if (isAnswered && ansRecord.selected === opt.key) {
                        btn.classList.add('selected');
                    }
                } else {
                    if (isAnswered) {
                        if (opt.key === q.answer?.toUpperCase()) btn.classList.add('correct');
                        else if (opt.key === ansRecord.selected?.toUpperCase()) btn.classList.add('wrong');
                    }
                }

                btn.addEventListener('click', () => {
                    if (window.isLookupMode) return;
                    const isExamNow = !!window.isExamMode;
                    const prevRec = userWrittenAnswers[currentWrittenExamTitle]?.[q.id];
                    if (!isExamNow && prevRec && String(prevRec.selected || '').toUpperCase() === opt.key) return;
                    const allBtns = grid.querySelectorAll('.tfng-btn');
                    if (isExamNow) {
                        allBtns.forEach(b => b.classList.remove('selected'));
                        btn.classList.add('selected');
                    } else {
                        allBtns.forEach(b => {
                            b.classList.remove('correct', 'wrong');
                            if (b.textContent.trim().toUpperCase() === q.answer?.toUpperCase()) b.classList.add('correct');
                            else if (b.textContent.trim().toUpperCase() === opt.key) b.classList.add('wrong');
                        });
                        if (explanationCard) {
                            showWrittenExplanation(q);
                        }
                        if (writtenStageCard) writtenStageCard.classList.add('answered-state');
                    }
                    selectWrittenOption(q.id, opt.key, q.answer);
                });

                grid.appendChild(btn);
            });
            optionsWrapper.appendChild(grid);

        } else if (q.type === 'sentence_insertion') {
            const insertWrapper = document.createElement('div');
            insertWrapper.style.cssText = 'display:flex; flex-direction:column; gap:14px; width:100%; margin-top:6px;';

            const insertSentenceText = q.insert_sentence || q.sentence || '';
            insertWrapper.innerHTML = `
                <div style="background:#f8fafc; border:1.5px solid #cbd5e1; border-radius:14px; padding:16px 20px; box-shadow:0 2px 8px rgba(0,0,0,0.02);">
                    <div style="font-size:12px; font-weight:700; color:#007aff; margin-bottom:6px; text-transform:uppercase; letter-spacing:0.04em;">
                        📌 待插入句子 (Sentence to Insert)
                    </div>
                    <div style="font-size:15.5px; font-weight:600; color:#0f172a; line-height:1.65;">
                        "${makeTextClickable(insertSentenceText)}"
                    </div>
                </div>
                <div style="font-size:13px; font-weight:700; color:#64748b; margin-top:2px;">
                    请点击下方或短文中的黑方块 [ ■ A ~ D ] 选择最佳插入位置：
                </div>
                <div class="sentence-insertion-grid">
                    ${['A', 'B', 'C', 'D'].map(sq => `
                        <button class="sentence-insertion-opt-btn" data-square="${sq}">
                            <span style="font-size:14px;">■</span> 方块 ${sq}
                        </button>
                    `).join('')}
                </div>
            `;

            const allBtns = insertWrapper.querySelectorAll('.sentence-insertion-opt-btn');
            allBtns.forEach(btn => {
                const sq = btn.dataset.square;
                if (isExam) {
                    if (isAnswered && ansRecord.selected === sq) {
                        btn.classList.add('selected');
                    }
                } else {
                    if (isAnswered) {
                        if (sq === q.answer?.toUpperCase()) btn.classList.add('correct');
                        else if (sq === ansRecord.selected?.toUpperCase()) btn.classList.add('wrong');
                    }
                }

                btn.addEventListener('click', () => {
                    if (window.isLookupMode) return;
                    const isExamNow = !!window.isExamMode;
                    const prevRec = userWrittenAnswers[currentWrittenExamTitle]?.[q.id];
                    if (!isExamNow && prevRec && String(prevRec.selected || '').toUpperCase() === sq) return;
                    if (isExamNow) {
                        allBtns.forEach(b => b.classList.remove('selected'));
                        btn.classList.add('selected');
                    } else {
                        allBtns.forEach(b => {
                            b.classList.remove('correct', 'wrong');
                            if (b.dataset.square === q.answer?.toUpperCase()) b.classList.add('correct');
                            else if (b.dataset.square === sq) b.classList.add('wrong');
                        });
                        if (explanationCard) {
                            showWrittenExplanation(q);
                        }
                        if (writtenStageCard) writtenStageCard.classList.add('answered-state');
                    }
                    selectWrittenOption(q.id, sq, q.answer);
                    renderWrittenQuestion(index, { preserveScroll: true });
                });
            });

            optionsWrapper.appendChild(insertWrapper);

        } else if (q.type === 'banked_cloze' || (q.type === 'cloze' && q.options && Object.keys(q.options).length > 7)) {
            const grid = document.createElement('div');
            grid.className = 'word-bank-options-grid';
            const elimStateKey = `wri::${currentWrittenExamTitle || 'default'}::${q.id}`;

            const usedElsewhereMap = {};
            const allExamAns = userWrittenAnswers[currentWrittenExamTitle] || {};
            (currentWrittenQuestions || []).forEach(sib => {
                if (!sib || sib.id === q.id) return;
                if (sib.type === q.type && sib.passage === q.passage) {
                    const sibRec = allExamAns[sib.id];
                    if (sibRec && !sibRec._deleted && sibRec.selected) {
                        const usedKey = sibRec.selected;
                        if (usedKey) {
                            if (!usedElsewhereMap[usedKey]) usedElsewhereMap[usedKey] = [];
                            usedElsewhereMap[usedKey].push(sib.id);
                        }
                    }
                }
            });

            Object.entries(q.options).forEach(([key, val]) => {
                const btn = document.createElement('div');
                btn.className = 'word-bank-opt-btn';

                if (isExam) {
                    if (isAnswered && ansRecord.selected === key) {
                        btn.classList.add('exam-selected-state');
                    }
                } else {
                    if (isAnswered) {
                        if (key === ansRecord.selected) btn.classList.add('opt-current-pick');
                        if (key === q.answer) btn.classList.add('correct-state');
                        else if (key === ansRecord.selected) btn.classList.add('wrong-state');
                    }
                }

                const usedIds = usedElsewhereMap[key];
                const hasUsedElsewhere = Array.isArray(usedIds) && usedIds.length > 0;
                const usedLabel = hasUsedElsewhere ? usedIds.map(id => `#${id}`).join(' ') : '';
                const usedTitle = hasUsedElsewhere ? `已在第 ${usedIds.join('、')} 空选过` : '';
                const isSelectedHere = isAnswered && ansRecord && ansRecord.selected === key;
                const hideBadgeNow = isSelectedHere || (!isExam && isAnswered && key === q.answer);
                if (hasUsedElsewhere && !hideBadgeNow && !btn.classList.contains('correct-state') && !btn.classList.contains('wrong-state')) {
                    btn.classList.add('opt-used-elsewhere');
                }

                btn.innerHTML = `
                    <span class="word-bank-opt-key">${key}.</span>
                    <span class="word-bank-opt-text">${makeTextClickable(val)}</span>
                    ${hasUsedElsewhere ? `<span class="opt-used-badge" data-used-blank="${usedIds[0]}" title="${usedTitle}" style="${hideBadgeNow ? 'display:none;' : ''}">${usedLabel}</span>` : ''}
                `;

                if (typeof window.bindOptionElimination === 'function') {
                    window.bindOptionElimination(btn, elimStateKey, key);
                }

                btn.addEventListener('click', () => {
                    if (window.isLookupMode) {
                        return;
                    }
                    const isExamNow = !!window.isExamMode;
                    // 随刷随解：作答后仍可随时改选其他选项（仅重复点击当前已选项时不重复判分）
                    if (!isExamNow && btn.classList.contains('opt-current-pick')) {
                        return;
                    }
                    const allBtns = grid.querySelectorAll('.word-bank-opt-btn');
                    if (isExamNow) {
                        allBtns.forEach(b => {
                            b.classList.remove('exam-selected-state');
                            const k = b.querySelector('.word-bank-opt-key')?.textContent?.replace('.', '').trim();
                            const hasUsed = !!(k && usedElsewhereMap[k] && usedElsewhereMap[k].length > 0);
                            b.classList.toggle('opt-used-elsewhere', hasUsed && k !== key);
                            const badgeEl = b.querySelector('.opt-used-badge');
                            if (badgeEl) badgeEl.style.display = (k === key) ? 'none' : '';
                        });
                        btn.classList.remove('opt-eliminated', 'opt-used-elsewhere');
                        btn.classList.add('exam-selected-state');
                        if (typeof window.clearOptionEliminationForKeys === 'function') {
                            window.clearOptionEliminationForKeys(elimStateKey, [key]);
                        }
                    } else {
                        allBtns.forEach(b => {
                            b.classList.remove('correct-state', 'wrong-state', 'opt-current-pick', 'opt-used-elsewhere');
                            const k = b.querySelector('.word-bank-opt-key')?.textContent?.replace('.', '').trim();
                            const hasUsed = !!(k && usedElsewhereMap[k] && usedElsewhereMap[k].length > 0);
                            if (k === q.answer || k === key) {
                                b.classList.remove('opt-eliminated');
                            }
                            if (k === q.answer) b.classList.add('correct-state');
                            else if (k === key) b.classList.add('wrong-state');
                            else if (hasUsed) b.classList.add('opt-used-elsewhere');
                            if (k === key) b.classList.add('opt-current-pick');
                            const badgeEl = b.querySelector('.opt-used-badge');
                            if (badgeEl) badgeEl.style.display = (k === key || k === q.answer) ? 'none' : '';
                        });
                        if (typeof window.clearOptionEliminationForKeys === 'function') {
                            window.clearOptionEliminationForKeys(elimStateKey, [key, q.answer]);
                        }
                        if (explanationCard) {
                            showWrittenExplanation(q);
                        }
                        if (writtenStageCard) writtenStageCard.classList.add('answered-state');
                    }
                    selectWrittenOption(q.id, key, q.answer);
                    if (passageCard) {
                        const reflectedCloze = passageCard.querySelector(`.written-cloze-blank[data-blank-id="${q.id}"]`);
                        if (reflectedCloze) {
                            const rawWord = (q.options && q.options[key]) ? q.options[key] : key;
                            const wordVal = rawWord && rawWord !== key ? rawWord : key;
                            const isRight = (key === q.answer);
                            const badgeColor = isExamNow ? '#007AFF' : (isRight ? '#15803D' : '#DC2626');
                            const badgeBg = isExamNow ? 'rgba(0, 122, 255, 0.12)' : (isRight ? 'rgba(52, 199, 89, 0.15)' : 'rgba(255, 59, 48, 0.13)');
                            const fillClass = isExamNow ? 'filled-exam' : (isRight ? 'filled-correct' : 'filled-wrong');
                            reflectedCloze.className = `written-cloze-blank active just-filled ${fillClass}`;
                            reflectedCloze.style.background = badgeBg;
                            reflectedCloze.style.color = badgeColor;
                            reflectedCloze.style.border = 'none';
                            reflectedCloze.style.boxShadow = 'none';
                            reflectedCloze.textContent = `${q.id}. ${wordVal}`;
                        }
                    }
                });

                grid.appendChild(btn);
            });
            optionsWrapper.appendChild(grid);

        } else if (q.type === 'matching') {
            const elimStateKey = `wri::${currentWrittenExamTitle || 'default'}::${q.id}`;
            const usedElsewhereMap = {};
            const allExamAns = userWrittenAnswers[currentWrittenExamTitle] || {};
            (currentWrittenQuestions || []).forEach(sib => {
                if (!sib || sib.id === q.id) return;
                if (sib.type === 'matching' && sib.section === q.section) {
                    const sibRec = allExamAns[sib.id];
                    if (sibRec && !sibRec._deleted && sibRec.selected) {
                        const usedKey = sibRec.selected;
                        if (usedKey) {
                            if (!usedElsewhereMap[usedKey]) usedElsewhereMap[usedKey] = [];
                            usedElsewhereMap[usedKey].push(sib.id);
                        }
                    }
                }
            });

            Object.entries(q.options).forEach(([key, val]) => {
                const btn = document.createElement('div');
                btn.className = 'opt-btn';

                if (isExam) {
                    if (isAnswered && ansRecord.selected === key) {
                        btn.classList.add('exam-selected-state');
                    }
                } else {
                    if (isAnswered) {
                        if (key === ansRecord.selected) btn.classList.add('opt-current-pick');
                        if (key === q.answer) btn.classList.add('correct-state');
                        else if (key === ansRecord.selected) btn.classList.add('wrong-state');
                    }
                }

                // 长篇段落匹配官方允许同一段落被多题重复选用，因此仅展示 #题号 轻提示，不加 .opt-used-elsewhere 删除线
                const usedIds = usedElsewhereMap[key];
                const hasUsedElsewhere = Array.isArray(usedIds) && usedIds.length > 0;
                const usedLabel = hasUsedElsewhere ? usedIds.map(id => `#${id}`).join(' ') : '';
                const usedTitle = hasUsedElsewhere ? `已在第 ${usedIds.join('、')} 题选过（长篇匹配允许重复选同一段）` : '';
                const isSelectedHere = isAnswered && ansRecord && ansRecord.selected === key;
                const hideBadgeNow = isSelectedHere || (!isExam && isAnswered && key === q.answer);

                const zhVal = (q.options_zh && q.options_zh[key]) ? q.options_zh[key] : '';
                const zhClass = (canUseB && window.showWrittenBilingual) ? 'opt-zh-text show' : 'opt-zh-text';

                btn.innerHTML = `
                    <span class="opt-key">${key}.</span>
                    <div class="opt-text-col">
                        <span class="opt-en-text">${makeTextClickable(val)}</span>
                        ${zhVal ? `<div class="${zhClass}">${zhVal}</div>` : ''}
                    </div>
                    ${hasUsedElsewhere ? `<span class="opt-used-badge" data-used-blank="${usedIds[0]}" title="${usedTitle}" style="${hideBadgeNow ? 'display:none;' : ''}">${usedLabel}</span>` : ''}
                `;

                if (typeof window.bindOptionElimination === 'function') {
                    window.bindOptionElimination(btn, elimStateKey, key);
                }

                btn.addEventListener('click', () => {
                    if (window.isLookupMode) {
                        return;
                    }
                    const isExamNow = !!window.isExamMode;
                    // 随刷随解：作答后仍可随时改选其他选项（仅重复点击当前已选项时不重复判分）
                    if (!isExamNow && btn.classList.contains('opt-current-pick')) {
                        return;
                    }
                    const allBtns = optionsWrapper.querySelectorAll('.opt-btn');
                    if (isExamNow) {
                        allBtns.forEach(b => {
                            b.classList.remove('exam-selected-state', 'opt-used-elsewhere');
                            const k = b.querySelector('.opt-key')?.textContent?.replace('.', '').trim();
                            const badgeEl = b.querySelector('.opt-used-badge');
                            if (badgeEl) badgeEl.style.display = (k === key) ? 'none' : '';
                        });
                        btn.classList.remove('opt-eliminated');
                        btn.classList.add('exam-selected-state');
                        if (typeof window.clearOptionEliminationForKeys === 'function') {
                            window.clearOptionEliminationForKeys(elimStateKey, [key]);
                        }
                    } else {
                        allBtns.forEach(b => {
                            b.classList.remove('correct-state', 'wrong-state', 'opt-current-pick', 'opt-used-elsewhere');
                            const k = b.querySelector('.opt-key')?.textContent?.replace('.', '').trim();
                            if (k === q.answer || k === key) {
                                b.classList.remove('opt-eliminated');
                            }
                            if (k === q.answer) b.classList.add('correct-state');
                            else if (k === key) b.classList.add('wrong-state');
                            if (k === key) b.classList.add('opt-current-pick');
                            const badgeEl = b.querySelector('.opt-used-badge');
                            if (badgeEl) badgeEl.style.display = (k === key || k === q.answer) ? 'none' : '';
                        });
                        if (typeof window.clearOptionEliminationForKeys === 'function') {
                            window.clearOptionEliminationForKeys(elimStateKey, [key, q.answer]);
                        }
                        if (explanationCard) {
                            showWrittenExplanation(q);
                        }
                        if (writtenStageCard) writtenStageCard.classList.add('answered-state');
                    }
                    selectWrittenOption(q.id, key, q.answer);
                });

                optionsWrapper.appendChild(btn);
            });

        } else if (q.type === 'careful' || q.type === 'seven_out_of_five' || q.type === 'cloze_choice' || (q.options && typeof q.options === 'object' && Object.keys(q.options).length > 0)) {
            const elimStateKey = `wri::${currentWrittenExamTitle || 'default'}::${q.id}`;
            const usedElsewhereMap = {};
            if (q.type === 'seven_out_of_five') {
                const allExamAns = userWrittenAnswers[currentWrittenExamTitle] || {};
                (currentWrittenQuestions || []).forEach(sib => {
                    if (!sib || sib.id === q.id) return;
                    if (sib.type === 'seven_out_of_five' && sib.passage === q.passage) {
                        const sibRec = allExamAns[sib.id];
                        if (sibRec && !sibRec._deleted && sibRec.selected) {
                            const usedKey = sibRec.selected;
                            if (usedKey) {
                                if (!usedElsewhereMap[usedKey]) usedElsewhereMap[usedKey] = [];
                                usedElsewhereMap[usedKey].push(sib.id);
                            }
                        }
                    }
                });
            }

            Object.entries(q.options).forEach(([key, val]) => {
                const btn = document.createElement('div');
                btn.className = 'opt-btn';

                if (isExam) {
                    if (isAnswered && ansRecord.selected === key) {
                        btn.classList.add('exam-selected-state');
                    }
                } else {
                    if (isAnswered) {
                        if (key === ansRecord.selected) btn.classList.add('opt-current-pick');
                        if (key === q.answer) btn.classList.add('correct-state');
                        else if (key === ansRecord.selected) btn.classList.add('wrong-state');
                    }
                }

                const usedIds = usedElsewhereMap[key];
                const hasUsedElsewhere = Array.isArray(usedIds) && usedIds.length > 0;
                const usedLabel = hasUsedElsewhere ? usedIds.map(id => `#${id}`).join(' ') : '';
                const usedTitle = hasUsedElsewhere ? `已在第 ${usedIds.join('、')} 空选过` : '';
                const isSelectedHere = isAnswered && ansRecord && ansRecord.selected === key;
                const hideBadgeNow = isSelectedHere || (!isExam && isAnswered && key === q.answer);
                if (hasUsedElsewhere && !hideBadgeNow && !btn.classList.contains('correct-state') && !btn.classList.contains('wrong-state')) {
                    btn.classList.add('opt-used-elsewhere');
                }

                const zhVal = (q.options_zh && q.options_zh[key]) ? q.options_zh[key] : '';
                const zhClass = (canUseB && window.showWrittenBilingual) ? 'opt-zh-text show' : 'opt-zh-text';

                btn.innerHTML = `
                    <span class="opt-key">${key}.</span>
                    <div class="opt-text-col">
                        <span class="opt-en-text">${makeTextClickable(val)}</span>
                        ${zhVal ? `<div class="${zhClass}">${zhVal}</div>` : ''}
                    </div>
                    ${hasUsedElsewhere ? `<span class="opt-used-badge" data-used-blank="${usedIds[0]}" title="${usedTitle}" style="${hideBadgeNow ? 'display:none;' : ''}">${usedLabel}</span>` : ''}
                `;

                if (typeof window.bindOptionElimination === 'function') {
                    window.bindOptionElimination(btn, elimStateKey, key);
                }

                btn.addEventListener('click', () => {
                    if (window.isLookupMode) {
                        return;
                    }
                    const isExamNow = !!window.isExamMode;
                    // 随刷随解：作答后仍可随时改选其他选项（仅重复点击当前已选项时不重复判分）
                    if (!isExamNow && btn.classList.contains('opt-current-pick')) {
                        return;
                    }
                    const allBtns = optionsWrapper.querySelectorAll('.opt-btn');
                    if (isExamNow) {
                        allBtns.forEach(b => {
                            b.classList.remove('exam-selected-state');
                            const k = b.querySelector('.opt-key')?.textContent?.replace('.', '').trim();
                            const hasUsed = !!(k && usedElsewhereMap[k] && usedElsewhereMap[k].length > 0);
                            b.classList.toggle('opt-used-elsewhere', hasUsed && k !== key);
                            const badgeEl = b.querySelector('.opt-used-badge');
                            if (badgeEl) badgeEl.style.display = (k === key) ? 'none' : '';
                        });
                        btn.classList.remove('opt-eliminated', 'opt-used-elsewhere');
                        btn.classList.add('exam-selected-state');
                        if (typeof window.clearOptionEliminationForKeys === 'function') {
                            window.clearOptionEliminationForKeys(elimStateKey, [key]);
                        }
                    } else {
                        allBtns.forEach(b => {
                            b.classList.remove('correct-state', 'wrong-state', 'opt-current-pick', 'opt-used-elsewhere');
                            const k = b.querySelector('.opt-key')?.textContent?.replace('.', '').trim();
                            const hasUsed = !!(k && usedElsewhereMap[k] && usedElsewhereMap[k].length > 0);
                            if (k === q.answer || k === key) {
                                b.classList.remove('opt-eliminated');
                            }
                            if (k === q.answer) b.classList.add('correct-state');
                            else if (k === key) b.classList.add('wrong-state');
                            else if (hasUsed) b.classList.add('opt-used-elsewhere');
                            if (k === key) b.classList.add('opt-current-pick');
                            const badgeEl = b.querySelector('.opt-used-badge');
                            if (badgeEl) badgeEl.style.display = (k === key || k === q.answer) ? 'none' : '';
                        });
                        if (typeof window.clearOptionEliminationForKeys === 'function') {
                            window.clearOptionEliminationForKeys(elimStateKey, [key, q.answer]);
                        }
                        if (explanationCard) {
                            showWrittenExplanation(q);
                        }
                        if (writtenStageCard) writtenStageCard.classList.add('answered-state');
                    }
                    selectWrittenOption(q.id, key, q.answer);
                    if (q.type === 'seven_out_of_five' && passageCard) {
                        const reflectedSeven = passageCard.querySelector(`.seven-blank-reflected[data-blank-id="${q.id}"]`);
                        if (reflectedSeven) {
                            const optText = (q.options && q.options[key]) ? q.options[key] : '';
                            const optDisplay = optText ? `<span>${makeTextClickable(optText)}</span>` : `<span>选项 ${key}</span>`;
                            const isRight = (key === q.answer);
                            const badgeClass = isExamNow ? 'filled active exam' : (isRight ? 'filled active correct' : 'filled active wrong');
                            const color = isExamNow ? '#0284c7' : (isRight ? 'var(--correct-green)' : 'var(--wrong-red)');
                            const bg = isExamNow ? '#f8fafc' : (isRight ? 'var(--correct-bg)' : 'var(--wrong-bg)');
                            const border = isExamNow ? '#0284c7' : (isRight ? 'var(--correct-green)' : 'var(--wrong-red)');
                            reflectedSeven.className = `seven-blank-reflected just-filled ${badgeClass}`;
                            reflectedSeven.style.background = bg;
                            reflectedSeven.style.borderColor = border;
                            reflectedSeven.style.borderWidth = '1.5px';
                            reflectedSeven.style.borderStyle = 'solid';
                            reflectedSeven.innerHTML = `<span style="color:${color}; font-weight:800; margin-right:8px;">[${q.id}. ${key}]</span>${optDisplay}`;
                        }
                    } else if ((q.type === 'cloze_choice' || q.type === 'cloze' || q.type === 'banked_cloze') && passageCard) {
                        const reflectedCloze = passageCard.querySelector(`.written-cloze-blank[data-blank-id="${q.id}"]`);
                        if (reflectedCloze) {
                            const rawWord = (q.options && q.options[key]) ? q.options[key] : key;
                            const wordVal = rawWord && rawWord !== key ? rawWord : key;
                            const isRight = (key === q.answer);
                            const badgeColor = isExamNow ? '#007AFF' : (isRight ? '#15803D' : '#DC2626');
                            const badgeBg = isExamNow ? 'rgba(0, 122, 255, 0.12)' : (isRight ? 'rgba(52, 199, 89, 0.15)' : 'rgba(255, 59, 48, 0.13)');
                            const fillClass = isExamNow ? 'filled-exam' : (isRight ? 'filled-correct' : 'filled-wrong');
                            reflectedCloze.className = `written-cloze-blank active just-filled ${fillClass}`;
                            reflectedCloze.style.background = badgeBg;
                            reflectedCloze.style.color = badgeColor;
                            reflectedCloze.style.border = 'none';
                            reflectedCloze.style.boxShadow = 'none';
                            reflectedCloze.textContent = `${q.id}. ${wordVal}`;
                        }
                    }
                });

                optionsWrapper.appendChild(btn);
            });

        } else {
            return false;
        }
    return true;
}
window.renderWrittenObjectiveQuestion = renderWrittenObjectiveQuestion;


/* === js/written_question_subjective.js === */
// ==========================================================================
// Written Translation, Essay & Explanation Card Renderers (js/written_question_subjective.js)
// ==========================================================================
function renderWrittenExplanationCard(targetQ, explanationCard) {
    if (!explanationCard) return;
    const expBodyP = document.getElementById('written-exp-body-p');
    const expEvidContainer = document.getElementById('written-exp-evidence-container');
    const expSynContainer = document.getElementById('written-exp-synonym-container');
        const expTitleEl = explanationCard.querySelector('.exp-title-lbl');
        if (expTitleEl) {
            if (targetQ.type === 'fill_in') {
                const promptHtml = targetQ.prompt ? `<span style="font-size:12px; font-weight:600; color:#475569; background:#f1f5f9; padding:2px 8px; border-radius:6px; margin-left:6px;">提示词: <strong>${targetQ.prompt}</strong></span>` : '';
                const ansVal = targetQ.answer || targetQ.word || '';
                const ansHtml = ansVal ? `<span style="font-size:12px; font-weight:700; color:#0369a1; background:#e0f2fe; padding:2px 8px; border-radius:6px; margin-left:6px;">标准答案: <strong>${ansVal}</strong></span>` : '';
                expTitleEl.innerHTML = `💡 Question ${targetQ.id} 语法考点精析 ${promptHtml} ${ansHtml}`;
            } else {
                expTitleEl.textContent = '💡 笔试考点精析与思路剖析';
            }
        }

        const curAnsRecord = userWrittenAnswers[currentWrittenExamTitle]?.[targetQ.id];
        let fillInStatusHtml = '';
        if (targetQ.type === 'fill_in' && curAnsRecord) {
            const isRight = curAnsRecord.isCorrect;
            fillInStatusHtml = isRight
                ? `<div style="display:inline-flex; align-items:center; gap:6px; background:#ecfdf5; border:1px solid #a7f3d0; color:#065f46; font-size:12px; font-weight:700; padding:4px 10px; border-radius:8px; margin-bottom:10px;"><span>✅ 你的作答: <strong>${curAnsRecord.selected}</strong> (回答正确)</span></div>`
                : `<div style="display:inline-flex; align-items:center; gap:6px; background:#fef2f2; border:1px solid #fecaca; color:#991b1b; font-size:12px; font-weight:700; padding:4px 10px; border-radius:8px; margin-bottom:10px;"><span>❌ 你的作答: <strong>${curAnsRecord.selected}</strong> ➔ 标准答案: <strong>${targetQ.answer || targetQ.word}</strong></span></div>`;
        }

        if (expBodyP) {
            expBodyP.innerHTML = (fillInStatusHtml ? fillInStatusHtml + '<div style="height:6px;"></div>' : '') + formatObjectiveAnalysisHtml(targetQ.analysis);
        }
        if (expEvidContainer) {
            if (targetQ.evidence_en) {
                expEvidContainer.innerHTML = `
                    <div class="exp-evidence-box" style="cursor:pointer;" title="点击可定位原文">
                        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:4px;">
                            <div class="exp-evidence-lbl">🎯 原文定位证据句</div>
                            <span style="font-size:11px; color:#0284c7; font-weight:700;">点击回看原文 ➔</span>
                        </div>
                        <div class="exp-evidence-en">${makeTextClickable(targetQ.evidence_en)}</div>
                        ${targetQ.evidence_zh ? `<div class="exp-evidence-zh">${targetQ.evidence_zh}</div>` : ''}
                    </div>
                `;
                const evidBox = expEvidContainer.querySelector('.exp-evidence-box');
                if (evidBox) {
                    evidBox.addEventListener('click', () => {
                        if (window.isLookupMode) return;
                        if (window.UXReadingSplitSheet && typeof window.UXReadingSplitSheet.ensureHalfForInteraction === 'function') {
                            window.UXReadingSplitSheet.ensureHalfForInteraction('evidence');
                        }
                        highlightEvidenceInPassage(targetQ, { forceScroll: true, pulse: true });
                    });
                }
            } else {
                expEvidContainer.innerHTML = '';
            }
        }
        if (expSynContainer) {
            if (targetQ.synonym_pairs && Array.isArray(targetQ.synonym_pairs) && targetQ.synonym_pairs.length > 0) {
                expSynContainer.innerHTML = `
                    <div class="exp-synonym-box" style="cursor:pointer;" title="点击可定位原文">
                        <div class="exp-synonym-lbl">🔄 核心同义替换词对</div>
                        ${targetQ.synonym_pairs.map(p => `
                            <div class="synonym-pair-item">
                                <div class="syn-line"><span class="syn-tag syn-tag-q">题干</span><span class="syn-text-q">${makeTextClickable(p.q || '')}</span></div>
                                <div class="syn-line"><span class="syn-tag syn-tag-orig">原文</span><span class="syn-text-orig">${makeTextClickable(p.orig || '')}</span></div>
                            </div>
                        `).join('')}
                    </div>
                `;
                const synBox = expSynContainer.querySelector('.exp-synonym-box');
                if (synBox) {
                    synBox.addEventListener('click', () => {
                        if (window.isLookupMode) return;
                        if (window.UXReadingSplitSheet && typeof window.UXReadingSplitSheet.ensureHalfForInteraction === 'function') {
                            window.UXReadingSplitSheet.ensureHalfForInteraction('evidence');
                        }
                        highlightEvidenceInPassage(targetQ, { forceScroll: true, pulse: true });
                    });
                }
            } else {
                expSynContainer.innerHTML = '';
            }
        }
        const wasShowingExp = explanationCard.classList.contains('show');
        explanationCard.classList.add('show');
        if (!wasShowingExp && window.UXAutoAnimate && typeof window.UXAutoAnimate.animateCardReveal === 'function') {
            window.UXAutoAnimate.animateCardReveal(explanationCard);
        }
        if (explanationCard._highlightTimer) {
            clearTimeout(explanationCard._highlightTimer);
        }
        explanationCard._highlightTimer = setTimeout(() => {
            if (window.isExamMode || !Array.isArray(currentWrittenQuestions) || currentWrittenQuestions[currentWrittenQIndex] !== targetQ) return;
            highlightEvidenceInPassage(targetQ, { autoScrollSplit: true });
        }, 20);
}
window.renderWrittenExplanationCard = renderWrittenExplanationCard;

function renderWrittenSubjectiveQuestion(ctx) {
    const { index, q, isExam, optionsWrapper } = ctx;
    if (!optionsWrapper) return false;
        if (q.type === 'translation' || q.type === 'translation_en_zh') {
            const transKey = (q.type === 'translation_en_zh')
                ? ('trans_' + currentWrittenExamTitle + '_' + q.id)
                : ('trans_' + currentWrittenExamTitle);
            const globalTransKey = 'trans_' + currentWrittenExamTitle;
            const canPracticeNow = (!window.ToyPermissions || typeof window.ToyPermissions.canUsePracticeMode !== 'function' || window.ToyPermissions.canUsePracticeMode());
            const isRevealed = canPracticeNow && ((revealedModelKeys[transKey] !== undefined)
                ? !!revealedModelKeys[transKey]
                : (revealedModelKeys[globalTransKey] !== undefined ? !!revealedModelKeys[globalTransKey] : !isExam));

            const wrapper = document.createElement('div');
            wrapper.style.width = '100%';

            // 1. Source Passage / Underlined Sentence Card (Clean White Card with Accent Header & Ruled Lines)
            if (q.prompt_zh || q.source_en) {
                const topStack = document.createElement('div');
                topStack.className = 'ios-subj-stack';
                const isEnToZh = (q.type === 'translation_en_zh');
                const enParas = isEnToZh ? (q.source_en || '').split(/\n+/).map(p => p.trim()).filter(Boolean) : [];
                const promptBodyHtml = isEnToZh
                    ? (enParas.length > 1
                        ? enParas.map(p => `<p style="margin-bottom:10px; text-indent:2em;">${makeTextClickable(p)}</p>`).join('')
                        : makeTextClickable(q.source_en || ''))
                    : q.prompt_zh;
                const headerLeft = isEnToZh ? (enParas.length > 1 || (q.source_en || '').length > 260 ? '待译段落' : `划线原句 (${q.id})`) : '待译原文';

                topStack.innerHTML = `
                    <div class="ios-subj-white-card">
                        <div class="ios-subj-card-header">
                            <div class="ios-subj-header-left">
                                <span class="ios-subj-accent-bar"></span>
                                <span class="ios-subj-header-title">${headerLeft}</span>
                            </div>
                        </div>
                        <div class="ios-subj-card-body">
                            ${promptBodyHtml}
                        </div>
                    </div>
                `;
                wrapper.appendChild(topStack);
            }

            const btnBar = document.createElement('div');
            btnBar.style.cssText = 'display:flex; justify-content:center; margin:6px 0 16px 0;';

            const toggleBtn = document.createElement('button');
            toggleBtn.className = 'ios-subj-toggle-btn';
            toggleBtn.innerHTML = isRevealed ? '收起参考译文与解析 ↑' : '✨ 查看参考译文与解析';

            toggleBtn.addEventListener('click', () => {
                if (!isRevealed && window.ToyPermissions && typeof window.ToyPermissions.canUsePracticeMode === 'function' && !window.ToyPermissions.canUsePracticeMode()) {
                    window.ToyPermissions.showUnlockModal('practice_mode');
                    return;
                }
                if (window.FeedbackEngine && typeof window.FeedbackEngine.triggerHaptic === 'function') {
                    window.FeedbackEngine.triggerHaptic('selection');
                }
                window._animateNextSubjReveal = !isRevealed;
                revealedModelKeys[transKey] = !isRevealed;
                renderWrittenQuestion(index, { preserveScroll: true });
            });

            btnBar.appendChild(toggleBtn);
            wrapper.appendChild(btnBar);

            if (isRevealed) {
                const solStack = document.createElement('div');
                solStack.className = 'ios-subj-stack';
                solStack.style.marginBottom = '20px';

                const refText = q.reference || q.official_reference_zh || '';
                const refCardHtml = `
                    <div class="ios-subj-white-card">
                        <div class="ios-subj-card-header">
                            <div class="ios-subj-header-left">
                                <span class="ios-subj-accent-bar emerald"></span>
                                <span class="ios-subj-header-title">参考译文</span>
                            </div>
                        </div>
                        <div class="ios-subj-card-body">
                            ${refText.split(/\n+/).map(p => p.trim()).filter(Boolean).map(p => `<p style="margin-bottom:8px; text-indent:0 !important;">${q.type === 'translation_en_zh' ? p : makeTextClickable(p)}</p>`).join('')}
                        </div>
                    </div>
                `;

                const analysisCardHtml = q.analysis ? `
                    <div class="ios-subj-white-card">
                        <div class="ios-subj-card-header">
                            <div class="ios-subj-header-left">
                                <span class="ios-subj-accent-bar amber"></span>
                                <span class="ios-subj-header-title">考点解析</span>
                            </div>
                        </div>
                        <div class="ios-subj-list-container">
                            ${formatAnalysisRows(q.analysis)}
                        </div>
                    </div>
                ` : '';

                let vocabCardHtml = '';
                if (q.vocabulary && q.vocabulary.length > 0) {
                    vocabCardHtml = `
                        <div class="ios-subj-white-card">
                            <div class="ios-subj-card-header">
                                <div class="ios-subj-header-left">
                                    <span class="ios-subj-accent-bar indigo"></span>
                                    <span class="ios-subj-header-title">重点词汇</span>
                                </div>
                            </div>
                            <div class="ios-subj-vocab-container">
                                ${q.vocabulary.map(v => {
                                    const enWord = v.word || v.en || v.term || '';
                                    const zhMeaning = v.meaning || v.cn || v.zh || v.def || '';
                                    return `
                                        <div class="ios-subj-vocab-row">
                                            <span class="ios-subj-vocab-en">${makeTextClickable(enWord)}</span>
                                            <span class="ios-subj-vocab-zh">${zhMeaning}</span>
                                        </div>
                                    `;
                                }).join('')}
                            </div>
                        </div>
                    `;
                }

                solStack.innerHTML = `
                    ${refCardHtml}
                    ${analysisCardHtml}
                    ${vocabCardHtml}
                `;
                wrapper.appendChild(solStack);
                if (window._animateNextSubjReveal && window.UXAutoAnimate && typeof window.UXAutoAnimate.animateCardReveal === 'function') {
                    window._animateNextSubjReveal = false;
                    requestAnimationFrame(() => window.UXAutoAnimate.animateCardReveal(solStack));
                }
            }
            optionsWrapper.appendChild(wrapper);

        } else if (q.type === 'writing') {
            const writingKey = 'writing_' + currentWrittenExamTitle + '_' + q.id;
            const globalWritingKey = 'writing_' + currentWrittenExamTitle;
            const canPracticeNow = (!window.ToyPermissions || typeof window.ToyPermissions.canUsePracticeMode !== 'function' || window.ToyPermissions.canUsePracticeMode());
            const isRevealed = canPracticeNow && ((revealedModelKeys[writingKey] !== undefined)
                ? !!revealedModelKeys[writingKey]
                : (revealedModelKeys[globalWritingKey] !== undefined ? !!revealedModelKeys[globalWritingKey] : !isExam));

            const wrapper = document.createElement('div');
            wrapper.style.width = '100%';

            // 1. Writing Directions & Embedded Cartoon/Chart + Answer Sheet (Direct White Cards without Gray Wrapper)
            if (q.directions || q.image_url) {
                const parsed = parseWritingDirections(q.directions || '', q);
                const topStack = document.createElement('div');
                topStack.className = 'ios-subj-stack';

                const ossBaseUrl = (window.EXAM_OSS_CONFIG && window.EXAM_OSS_CONFIG.baseUrl)
                    ? window.EXAM_OSS_CONFIG.baseUrl.replace(/\/$/, '')
                    : 'https://bilibilitoyassets.top';
                const isLocalHost = (typeof window !== 'undefined' && window.location && (
                    window.location.protocol === 'file:' ||
                    window.location.hostname === 'localhost' ||
                    window.location.hostname === '127.0.0.1'
                ));
                const cleanRelImg = (q.image_url || '').replace(/^\//, '');
                const remoteImgUrl = cleanRelImg.startsWith('http') ? cleanRelImg : `${ossBaseUrl}/${cleanRelImg}`;
                const remoteAltUrl = cleanRelImg.startsWith('http') ? cleanRelImg : `${ossBaseUrl}/${cleanRelImg.replace(/^input\//, '')}`;
                const primaryImgSrc = isLocalHost ? q.image_url : remoteImgUrl;

                const visualHtml = q.image_url ? `
                    <div class="writing-visual-container" style="padding:16px 18px; border-top:1px solid rgba(15, 23, 42, 0.08); text-align:center; background:#FFFFFF;">
                        <img src="${primaryImgSrc}" decoding="async" data-remote-src="${remoteImgUrl}" data-remote-alt="${remoteAltUrl}" data-local-src="${q.image_url}" alt="${q.subSection || 'Writing Part B Visual'}"
                             style="max-width:100%; height:auto; max-height:420px; border-radius:12px; display:block; margin:0 auto; cursor:zoom-in; background:#FFFFFF; border:1px solid rgba(15, 23, 42, 0.08);"
                             onclick="window.open(this.src, '_blank')"
                             onerror="if(!this.dataset.retried){this.dataset.retried='1';this.src=this.dataset.remoteSrc;}else if(this.dataset.retried==='1'){this.dataset.retried='2';this.src=this.dataset.remoteAlt;}else if(this.dataset.retried==='2'){this.dataset.retried='3';this.src=this.dataset.localSrc.replace(/^input\//,'assets/');}" />
                        ${q.image_description ? `
                            <div style="margin-top:12px; padding-top:10px; border-top:1px dashed rgba(15, 23, 42, 0.09); text-align:left; font-size:13.5px; line-height:1.68; color:#475569;">
                                <span class="ios-subj-inline-tag">图画/图表解读</span>${q.image_description}
                            </div>
                        ` : ''}
                    </div>
                ` : '';

                const cleanZhDirections = (q.directions_zh || '')
                    .replace(/^(?:审题译文|审题指南|审题要求|写作要求)[：:\s]*/g, '')
                    .replace(/^(?:审题译文|审题指南|审题要求|写作要求)[：:\s]*/g, '')
                    .trim();

                topStack.innerHTML = `
                    <div class="ios-subj-white-card">
                        <div class="ios-subj-card-header">
                            <div class="ios-subj-header-left">
                                <span class="ios-subj-accent-bar"></span>
                                <span class="ios-subj-header-title">写作要求</span>
                            </div>
                        </div>
                        <div class="ios-subj-card-body">
                            ${parsed.instructionsHtml}
                        </div>
                        ${cleanZhDirections ? `
                            <div class="ios-subj-card-subbody">
                                <span class="ios-subj-inline-tag">审题译文</span>${cleanZhDirections}
                            </div>
                        ` : ''}
                        ${visualHtml}
                    </div>
                    ${parsed.answerSheetHtml}
                `;
                wrapper.appendChild(topStack);
            }

            const btnBar = document.createElement('div');
            btnBar.style.cssText = 'display:flex; justify-content:center; margin:6px 0 16px 0;';

            const toggleBtn = document.createElement('button');
            toggleBtn.className = 'ios-subj-toggle-btn';
            toggleBtn.innerHTML = isRevealed ? '收起参考范文与解析 ↑' : '✨ 查看参考范文与解析';

            toggleBtn.addEventListener('click', () => {
                if (!isRevealed && window.ToyPermissions && typeof window.ToyPermissions.canUsePracticeMode === 'function' && !window.ToyPermissions.canUsePracticeMode()) {
                    window.ToyPermissions.showUnlockModal('practice_mode');
                    return;
                }
                if (window.FeedbackEngine && typeof window.FeedbackEngine.triggerHaptic === 'function') {
                    window.FeedbackEngine.triggerHaptic('selection');
                }
                window._animateNextSubjReveal = !isRevealed;
                revealedModelKeys[writingKey] = !isRevealed;
                renderWrittenQuestion(index, { preserveScroll: true });
            });

            btnBar.appendChild(toggleBtn);
            wrapper.appendChild(btnBar);

            if (isRevealed) {
                const solStack = document.createElement('div');
                solStack.className = 'ios-subj-stack';
                solStack.style.marginBottom = '20px';

                const essayCardHtml = `
                    <div class="ios-subj-white-card">
                        <div class="ios-subj-card-header">
                            <div class="ios-subj-header-left">
                                <span class="ios-subj-accent-bar emerald"></span>
                                <span class="ios-subj-header-title">高分参考范文</span>
                            </div>
                        </div>
                        <div class="ios-subj-card-body">
                            ${formatModelEssayHtml(q.essay || '')}
                        </div>
                        ${q.essay_zh ? `
                            <div class="ios-subj-essay-trans-divider">
                                <div class="ios-subj-sub-header">
                                    <span class="ios-subj-sub-badge">全文参考译文</span>
                                </div>
                                <div style="font-size:14.2px; line-height:1.76; color:#334155;">
                                    ${formatModelEssayZhHtml(q.essay_zh)}
                                </div>
                            </div>
                        ` : ''}
                    </div>
                `;

                const analysisCardHtml = q.analysis ? `
                    <div class="ios-subj-white-card">
                        <div class="ios-subj-card-header">
                            <div class="ios-subj-header-left">
                                <span class="ios-subj-accent-bar amber"></span>
                                <span class="ios-subj-header-title">审题构思与行文拆解</span>
                            </div>
                        </div>
                        <div class="ios-subj-list-container">
                            ${formatAnalysisRows(q.analysis)}
                        </div>
                    </div>
                ` : '';

                let vocabCardHtml = '';
                if (q.vocabulary && q.vocabulary.length > 0) {
                    vocabCardHtml = `
                        <div class="ios-subj-white-card">
                            <div class="ios-subj-card-header">
                                <div class="ios-subj-header-left">
                                    <span class="ios-subj-accent-bar indigo"></span>
                                    <span class="ios-subj-header-title">亮点词汇与闪光表达</span>
                                </div>
                            </div>
                            <div class="ios-subj-vocab-container">
                                ${q.vocabulary.map(v => {
                                    const enWord = v.word || v.en || v.term || '';
                                    const zhMeaning = v.meaning || v.cn || v.zh || v.def || '';
                                    return `
                                        <div class="ios-subj-vocab-row">
                                            <span class="ios-subj-vocab-en">${makeTextClickable(enWord)}</span>
                                            <span class="ios-subj-vocab-zh">${zhMeaning}</span>
                                        </div>
                                    `;
                                }).join('')}
                            </div>
                        </div>
                    `;
                }

                solStack.innerHTML = `
                    ${essayCardHtml}
                    ${analysisCardHtml}
                    ${vocabCardHtml}
                `;
                wrapper.appendChild(solStack);
                if (window._animateNextSubjReveal && window.UXAutoAnimate && typeof window.UXAutoAnimate.animateCardReveal === 'function') {
                    window._animateNextSubjReveal = false;
                    requestAnimationFrame(() => window.UXAutoAnimate.animateCardReveal(solStack));
                }
            }
            optionsWrapper.appendChild(wrapper);
        } else {
            return false;
        }
    return true;
}
window.renderWrittenSubjectiveQuestion = renderWrittenSubjectiveQuestion;


/* === js/written_exam.js === */
// ==========================================================================
// Written Exam Arena Orchestrator, Scoring & Report Engine (js/written_exam.js)
// ==========================================================================
function renderWrittenQuestion(index, options = {}) {
    let curLvl = null;
    if (currentWrittenExamTitle) {
        let meta = (typeof findExamMeta === 'function') ? findExamMeta(currentWrittenExamTitle) : null;
        curLvl = meta ? meta.level : null;
        if (!curLvl) {
            if (currentWrittenExamTitle.includes('考研')) curLvl = 'kaoyan';
            else if (currentWrittenExamTitle.includes('高考')) curLvl = 'gaokao';
            else if (currentWrittenExamTitle.includes('六级')) curLvl = 'cet6';
            else if (currentWrittenExamTitle.includes('四级')) curLvl = 'cet4';
        }
    }
    curLvl = curLvl || window.currentExamLevel || 'cet4';
    window.currentExamLevel = curLvl;

    const examIdx = getWrittenExamTrackIndex(currentWrittenExamTitle, curLvl);
    if (window.ToyPermissions && !window.ToyPermissions.canAccessWrittenExam(examIdx >= 0 ? examIdx : 0, index, curLvl)) {
        window.ToyPermissions.showUnlockModal('written', { examIndex: examIdx >= 0 ? examIdx : 0, questionIndex: index, level: curLvl });
        return;
    }

    if (!currentWrittenQuestions || currentWrittenQuestions.length === 0) return;
    index = Math.max(0, Math.min(Number(index) || 0, currentWrittenQuestions.length - 1));
    const prevWIndex = (typeof currentWrittenQIndex === 'number') ? currentWrittenQIndex : 0;
    const prevQ = currentWrittenQuestions[prevWIndex];
    const q = currentWrittenQuestions[index];
    currentWrittenQIndex = index;
    window.currentWrittenQIndex = currentWrittenQIndex;
    hideContextualPopover();
    if (typeof window.dismissProofreadPopovers === 'function') {
        window.dismissProofreadPopovers();
    }
    hideBackToQuestionPill();

    const isSamePassage = Boolean(
        prevQ && q &&
        prevQ.type === q.type &&
        q.passage && q.passage.trim() &&
        prevQ.passage && prevQ.passage.trim() === q.passage.trim()
    );

    const quizPane = document.querySelector('.written-split-quiz');
    const passPane = document.querySelector('.written-split-passage');
    const isArenaEntry = !!(options && options.isArenaEntry);

    if (isArenaEntry) {
        if (quizPane) quizPane.scrollTop = 0;
        if (passPane) passPane.scrollTop = 0;
    } else {
        if (quizPane && index !== prevWIndex) {
            quizPane.scrollTop = 0;
        }
        if (!options.preserveScroll) {
            if (!isSamePassage) {
                try {
                    window.scrollTo({ top: 0, behavior: 'instant' });
                } catch (_) {
                    try { window.scrollTo(0, 0); } catch (e) {}
                }
            }
            if (quizPane) quizPane.scrollTop = 0;
            if (passPane && index !== prevWIndex && !isSamePassage) {
                passPane.scrollTop = 0;
            }
        }
    }
    if (window.ToyPermissions && typeof window.ToyPermissions.canUsePracticeMode === 'function' && !window.ToyPermissions.canUsePracticeMode()) {
        window.isExamMode = true;
        const tabPractice = document.getElementById('tab-mode-practice');
        const tabExam = document.getElementById('tab-mode-exam');
        if (tabPractice && tabExam) {
            tabPractice.classList.remove('active');
            tabExam.classList.add('active');
            if (window.UXSegmentedGlider) {
                window.UXSegmentedGlider.sync('#header-mode-segmented', false);
            }
        }
    }
    const isExam = !!window.isExamMode;

    const writtenStageCard = document.getElementById('written-stage-card');
    const splitCont = writtenStageCard ? writtenStageCard.querySelector('.written-split-container') : null;
    const isSheetSplitActive = (window.UXReadingSplitSheet && typeof window.UXReadingSplitSheet.isViewportEligible === 'function')
        ? window.UXReadingSplitSheet.isViewportEligible(q)
        : !!(splitCont && splitCont.classList.contains('mobile-sheet-split-active'));
    const qH2ForSlide = document.getElementById('written-q-h2');
    const optsWrapForSlide = document.getElementById('written-options-wrapper');
    const slideTargets = isSheetSplitActive
        ? [qH2ForSlide, optsWrapForSlide].filter(Boolean)
        : [((isSamePassage && quizPane) ? quizPane : writtenStageCard)].filter(Boolean);
    if (writtenStageCard && isSheetSplitActive) {
        writtenStageCard.classList.remove('card-slide-forward', 'card-slide-backward');
    }
    if (!isSheetSplitActive) {
        if (qH2ForSlide) qH2ForSlide.classList.remove('card-slide-forward', 'card-slide-backward');
        if (optsWrapForSlide) optsWrapForSlide.classList.remove('card-slide-forward', 'card-slide-backward');
    }
    if (slideTargets.length > 0 && !options.preserveScroll && !isArenaEntry && index !== prevWIndex) {
        if (writtenStageCard) writtenStageCard.classList.remove('card-slide-forward', 'card-slide-backward');
        if (quizPane) quizPane.classList.remove('card-slide-forward', 'card-slide-backward');
        slideTargets.forEach(el => {
            el.classList.remove('card-slide-forward', 'card-slide-backward');
            void el.offsetWidth;
            if (index > prevWIndex) {
                el.classList.add('card-slide-forward');
            } else if (index < prevWIndex) {
                el.classList.add('card-slide-backward');
            }
            if (typeof el.addEventListener === 'function' && !el._cardSlideEndBound) {
                el._cardSlideEndBound = true;
                el.addEventListener('animationend', (ev) => {
                    if (!ev || ev.target === el) {
                        el.classList.remove('card-slide-forward', 'card-slide-backward');
                    }
                });
            }
        });
    }
    if (writtenStageCard) {
        if (q.type === 'fill_in') {
            writtenStageCard.classList.add('grammar-fillin-mode');
            writtenStageCard.classList.remove('proofread-mode');
        } else if (q.type === 'proofread') {
            writtenStageCard.classList.remove('grammar-fillin-mode');
            writtenStageCard.classList.add('proofread-mode');
        } else {
            writtenStageCard.classList.remove('grammar-fillin-mode');
            writtenStageCard.classList.remove('proofread-mode');
        }
    }
    const explanationCard = document.getElementById('written-explanation-card');
    const expCard = explanationCard;
    function showWrittenExplanation(targetQ) {
        renderWrittenExplanationCard(targetQ, explanationCard);
    }

    // 2. Top Badges (Unified Section · Question ID Pill)
    const seqVal = document.getElementById('written-seq-val');
    const secBadge = document.getElementById('written-section-badge');
    if (seqVal) seqVal.textContent = q.id;
    if (secBadge) {
        const secText = (q.section || '').trim();
        const qIdStr = (q.id !== undefined && q.id !== null) ? String(q.id).trim() : '';
        secBadge.textContent = (secText && qIdStr) ? `${secText} · ${qIdStr}` : (secText || qIdStr);
    }

    // 3. Render Passage & Translation Card
    const passageCard = document.getElementById('written-passage-card');
    const transCard = document.getElementById('written-translation-card');
    const canUseB = (window.ToyPermissions && typeof window.ToyPermissions.canUseBilingualMode === 'function')
        ? window.ToyPermissions.canUseBilingualMode()
        : false;

    const qH2 = document.getElementById('written-q-h2');
    const qZhP = document.getElementById('written-q-zh-p');
    const optionsWrapper = document.getElementById('written-options-wrapper');
    const rawAnsRecord = userWrittenAnswers[currentWrittenExamTitle]?.[q.id];
    const ansRecord = (rawAnsRecord && !rawAnsRecord._deleted) ? rawAnsRecord : undefined;
    const isAnswered = !!ansRecord;

    const renderCtx = {
        index, q, prevQ, prevWIndex, options, curLvl, isExam, canUseB,
        isSamePassage, isArenaEntry, isSheetSplitActive, ansRecord, isAnswered,
        writtenStageCard, quizPane, passPane, passageCard, transCard,
        optionsWrapper, explanationCard, showWrittenExplanation
    };

    renderWrittenPassagePane(renderCtx);

    // 4. Update Question Statement & Options
    if ((q.type === 'fill_in' && q.passage) || q.type === 'proofread' || q.type === 'writing' || (q.type === 'translation_en_zh' && q.source_en)) {
        if (qH2) qH2.style.display = 'none';
        if (qZhP) {
            qZhP.style.display = 'none';
            qZhP.classList.remove('show');
        }
    } else {
        if (qH2) qH2.style.display = '';
        let rawText = (q.question_text || '').replace(/^Question\s*\d*[\.:\s]*/i, '').trim();
        if (!rawText) {
            rawText = (q.question_text_zh || q.question_zh || q.statement || '').trim();
        }
        if (qH2) qH2.innerHTML = makeTextClickable(rawText ? `Question ${q.id}. ${rawText}` : `Question ${q.id}.`);
        if (qZhP) {
            const hasDiffZh = q.question_text_zh && q.question_text_zh.trim() !== rawText;
            qZhP.textContent = q.question_text_zh || '';
            if (hasDiffZh && canUseB && window.showWrittenBilingual && q.type !== 'translation' && q.type !== 'writing') {
                qZhP.style.display = 'block';
                qZhP.classList.add('show');
            } else {
                qZhP.style.display = 'none';
                qZhP.classList.remove('show');
            }
        }
    }

    if (writtenStageCard) {
        if (isAnswered) {
            writtenStageCard.classList.add('answered-state');
        } else {
            writtenStageCard.classList.remove('answered-state');
        }
    }

    if (optionsWrapper) {
        optionsWrapper.innerHTML = '';
        if (!renderWrittenObjectiveQuestion(renderCtx)) {
            renderWrittenSubjectiveQuestion(renderCtx);
        }
    }

    // 5. Explanation Box (STRICTLY HIDDEN IN EXAM MODE)
    if (explanationCard) {
        // In Practice Mode (随刷随解), grammar fill-in always displays immediate explanation for current blank
        const shouldShowExp = !isExam && (isAnswered || q.type === 'fill_in') && q.type !== 'writing' && q.type !== 'translation' && q.type !== 'translation_en_zh' && q.type !== 'proofread';
        if (shouldShowExp) {
            showWrittenExplanation(q);
        } else {
            if (explanationCard._highlightTimer) {
                clearTimeout(explanationCard._highlightTimer);
                explanationCard._highlightTimer = null;
            }
            explanationCard.classList.remove('show');
            clearEvidenceHighlightInPassage(passageCard);
        }
    }

    // 5.5 Sync Mobile/Tablet Reading Split Sheet (Free-Stop Persistent Split Ratio)
    if (window.UXReadingSplitSheet && typeof window.UXReadingSplitSheet.syncSheetState === 'function') {
        window.UXReadingSplitSheet.syncSheetState({ animate: false });
    }

    // 6. Navigation Buttons
    const btnWrittenPrev = document.getElementById('btn-written-prev-q');
    const btnWrittenNext = document.getElementById('btn-written-next-q');
    const ansProgress = document.getElementById('written-ans-progress');

    if (q.type === 'proofread') {
        const pfIndices = currentWrittenQuestions.map((it, i) => it.type === 'proofread' ? i : -1).filter(i => i !== -1);
        const firstPf = pfIndices[0];
        const lastPf = pfIndices[pfIndices.length - 1];
        if (ansProgress) ansProgress.textContent = '短文改错';
        if (btnWrittenPrev) btnWrittenPrev.disabled = firstPf === 0;
        if (btnWrittenNext) btnWrittenNext.textContent = (lastPf === currentWrittenQuestions.length - 1) ? '交卷 / 查看报告 🏆' : '下一大题 →';
    } else {
        if (btnWrittenPrev) btnWrittenPrev.disabled = index === 0;
        if (btnWrittenNext) btnWrittenNext.textContent = index === currentWrittenQuestions.length - 1 ? '交卷 / 查看报告 🏆' : '下一题 →';
        if (ansProgress) ansProgress.textContent = `${index + 1}/${currentWrittenQuestions.length}`;
    }
    if (typeof window.kickLiquidGlass === 'function') setTimeout(window.kickLiquidGlass, 60);
}

function showPassageSwitchBanner() {
    const pill = document.getElementById('passage-switch-pill');
    if (pill) {
        if (pill._hideTimer) clearTimeout(pill._hideTimer);
        pill.classList.remove('show');
        if (pill.parentNode) pill.parentNode.removeChild(pill);
    }
}

function checkIsCorrect(selectedKey, correctKey) {
    if (selectedKey === undefined || selectedKey === null || correctKey === undefined || correctKey === null) return false;
    const s = String(selectedKey).trim().toLowerCase();
    const rawC = String(correctKey).trim().toLowerCase();
    if (!s) return false;
    if (s === rawC) return true;
    const alts = rawC.split(/\/|\s+or\s+/).map(it => it.trim()).filter(Boolean);
    return alts.includes(s);
}

function selectWrittenOption(qId, selectedKey, correctKey, extraFields) {
    const isCorrect = (extraFields && typeof extraFields.isCorrect === 'boolean')
        ? extraFields.isCorrect
        : checkIsCorrect(selectedKey, correctKey);

    // Multi-sensory Feedback (Audio + Haptics + Combo)
    if (!window.isExamMode) {
        if (isCorrect) {
            if (window.FeedbackEngine) window.FeedbackEngine.playCorrect();
        } else {
            if (window.FeedbackEngine) window.FeedbackEngine.playWrong();
        }
    } else {
        if (window.FeedbackEngine) window.FeedbackEngine.playTap();
    }

    if (!userWrittenAnswers[currentWrittenExamTitle]) {
        userWrittenAnswers[currentWrittenExamTitle] = {};
    }
    const nowTs = Date.now();
    const prevW = (userWrittenAnswers[currentWrittenExamTitle] && typeof userWrittenAnswers[currentWrittenExamTitle][qId] === 'object' && !userWrittenAnswers[currentWrittenExamTitle][qId]._deleted)
        ? userWrittenAnswers[currentWrittenExamTitle][qId]
        : null;
    const firstCorrect = (prevW && typeof prevW.firstCorrect === 'boolean')
        ? prevW.firstCorrect
        : ((prevW && typeof prevW.isCorrect === 'boolean') ? prevW.isCorrect : isCorrect);
    const firstTs = (prevW && typeof prevW.firstTs === 'number')
        ? prevW.firstTs
        : ((prevW && typeof prevW.ts === 'number') ? prevW.ts : nowTs);
    const attempts = (prevW && typeof prevW.attempts === 'number') ? (prevW.attempts + 1) : (prevW ? 2 : 1);
    userWrittenAnswers[currentWrittenExamTitle][qId] = Object.assign({
        selected: selectedKey,
        isCorrect,
        ts: nowTs,
        firstCorrect,
        firstTs,
        attempts,
        mode: window.isExamMode ? 'exam' : 'practice'
    }, extraFields || {}, { isCorrect, ts: nowTs });

    if (currentWrittenExamTitle) {
        if (!window.completedExams[currentWrittenExamTitle]) {
            window.completedExams[currentWrittenExamTitle] = {};
        }
        window.completedExams[currentWrittenExamTitle].timestamp = nowTs;
        if (!window.completedExams[currentWrittenExamTitle].writtenAnswers) {
            window.completedExams[currentWrittenExamTitle].writtenAnswers = {};
        }
        Object.assign(window.completedExams[currentWrittenExamTitle].writtenAnswers, userWrittenAnswers[currentWrittenExamTitle]);
        window.completedExams[currentWrittenExamTitle].writtenAnswers[qId] = Object.assign({}, userWrittenAnswers[currentWrittenExamTitle][qId]);
        saveUserCloudData(currentWrittenExamTitle);
        if (typeof recordTodayQuestionAnswer === 'function') {
            recordTodayQuestionAnswer(currentWrittenExamTitle, qId, isCorrect);
        }
    }

    updateDashboardStats();
    submitUserScore();
    if (typeof window.kickLiquidGlass === 'function') setTimeout(window.kickLiquidGlass, 60);
}

function finishWrittenExam() {
    let readingCorrect = 0;
    // 动态统计所有客观题（有标准答案的题目，自适应涵盖单选、完形、语法填空、改错等）
    const objectiveQuestions = (currentWrittenQuestions || []).filter(q => 
        (q.answer !== undefined && q.answer !== '') || 
        (q.target !== undefined) || 
        (q.corr_type !== undefined)
    );
    const readingTotal = objectiveQuestions.length || 1;

    const secStatsMap = {};
    let firstWrongIdx = -1;

    const curLvl = window.currentExamLevel || 'cet4';
    const curExamIdx = getWrittenExamTrackIndex(currentWrittenExamTitle, curLvl);
    const safeExamIdx = curExamIdx >= 0 ? curExamIdx : 0;

    (currentWrittenQuestions || []).forEach((q, idx) => {
        const isObj = (q.answer !== undefined && q.answer !== '') || (q.target !== undefined) || (q.corr_type !== undefined);
        if (!isObj) return;
        const canAccessQ = window.ToyPermissions ? window.ToyPermissions.canAccessWrittenExam(safeExamIdx, idx, curLvl) : true;
        const record = userWrittenAnswers[currentWrittenExamTitle]?.[q.id];
        const isRight = (q.corr_type === 'correct') ? (!record || record._deleted || !!record.isCorrect) : !!(record && !record._deleted && record.isCorrect);
        if (isRight) {
            readingCorrect++;
        } else if (firstWrongIdx === -1 && canAccessQ) {
            firstWrongIdx = idx;
        }
        const rawSec = (q.section || '客观题').split('·')[0].trim();
        if (!secStatsMap[rawSec]) {
            secStatsMap[rawSec] = { label: rawSec, correct: 0, total: 0 };
        }
        secStatsMap[rawSec].total++;
        if (isRight) secStatsMap[rawSec].correct++;
    });

    window._firstWrongWrittenIdx = firstWrongIdx;
    const score = Math.round((readingCorrect / readingTotal) * 100);

    if (currentWrittenExamTitle) {
        const nowTs = Date.now();
        if (!window.completedExams[currentWrittenExamTitle]) {
            window.completedExams[currentWrittenExamTitle] = {};
        }
        window.completedExams[currentWrittenExamTitle].writtenScore = score;
        window.completedExams[currentWrittenExamTitle].writtenScoreTimestamp = nowTs;
        window.completedExams[currentWrittenExamTitle].timestamp = nowTs;
        if (!window.completedExams[currentWrittenExamTitle].writtenAnswers) {
            window.completedExams[currentWrittenExamTitle].writtenAnswers = {};
        }
        Object.assign(window.completedExams[currentWrittenExamTitle].writtenAnswers, userWrittenAnswers[currentWrittenExamTitle]);
        saveUserCloudData(currentWrittenExamTitle, true);

        // 仅在拥有对应试题权限且已关注 UP 主（可使用随刷随解）时，交卷后自动解锁并呈现改错、写作与翻译答案精析
        const lastQIdx = Math.max(0, (currentWrittenQuestions || []).length - 1);
        const canAccessFullExam = window.ToyPermissions ? window.ToyPermissions.canAccessWrittenExam(safeExamIdx, lastQIdx, curLvl) : true;
        const canPractice = (!window.ToyPermissions || typeof window.ToyPermissions.canUsePracticeMode !== 'function' || window.ToyPermissions.canUsePracticeMode());
        if (canAccessFullExam && canPractice) {
            revealedModelKeys['trans_' + currentWrittenExamTitle] = true;
            revealedModelKeys['writing_' + currentWrittenExamTitle] = true;
            revealedModelKeys['proofread_' + currentWrittenExamTitle] = true;
            (currentWrittenQuestions || []).filter(q => q.type === 'writing').forEach(wq => {
                revealedModelKeys['writing_' + currentWrittenExamTitle + '_' + wq.id] = true;
            });
            (currentWrittenQuestions || []).filter(q => q.type === 'translation_en_zh' || q.type === 'translation').forEach(tq => {
                revealedModelKeys['trans_' + currentWrittenExamTitle + '_' + tq.id] = true;
            });
        }
    }

    const modalExamName = document.getElementById('modal-exam-name');
    const modalScoreNum = document.getElementById('modal-score-num');
    const modalScoreDetail = document.getElementById('modal-score-detail');
    const scoreModal = document.getElementById('score-modal');
    const btnModalReview = document.getElementById('btn-modal-review');

    if (modalExamName) modalExamName.textContent = `${currentWrittenExamTitle} · 笔试真题`;
    if (modalScoreNum) modalScoreNum.textContent = `${score}分`;
    if (modalScoreDetail) {
        const secEntries = Object.values(secStatsMap);
        const secBadgesHtml = secEntries.length > 1
            ? `<div style="display:flex; flex-wrap:wrap; justify-content:center; gap:6px; margin-top:10px;">` +
              secEntries.map(s => `<span style="font-size:12px; font-weight:600; color:#475569; background:#f1f5f9; padding:3px 9px; border-radius:6px;">${s.label} ${s.correct}/${s.total}</span>`).join('') +
              `</div>`
            : '';
        modalScoreDetail.innerHTML = `<div>全卷客观题共 ${readingTotal} 题，答对 ${readingCorrect} 题</div>${secBadgesHtml}`;
    }
    if (btnModalReview) {
        if (firstWrongIdx >= 0 && currentWrittenQuestions[firstWrongIdx]) {
            btnModalReview.textContent = `🎯 复盘错题与全卷解析 (从 Q${currentWrittenQuestions[firstWrongIdx].id} 开始)`;
        } else {
            btnModalReview.textContent = '📋 回顾整卷与解析范文';
        }
    }
    if (scoreModal) scoreModal.classList.add('active');

    if (window.FeedbackEngine) {
        window.FeedbackEngine.playComplete();
    }
    launchGrandConfettiShow();
    updateDashboardStats();
    submitUserScore();
}

window.syncWrittenModeRevealedState = function(isExam) {
    if (isExam && window.ToyPermissions && typeof window.ToyPermissions.canUsePracticeMode === 'function' && !window.ToyPermissions.canUsePracticeMode()) {
        Object.keys(revealedModelKeys).forEach(k => delete revealedModelKeys[k]);
    }
    if (!currentWrittenExamTitle) return;
    const prefixTrans = 'trans_' + currentWrittenExamTitle;
    const prefixWriting = 'writing_' + currentWrittenExamTitle;
    const prefixProof = 'proofread_' + currentWrittenExamTitle;
    Object.keys(revealedModelKeys).forEach(k => {
        if (k.startsWith(prefixTrans) || k.startsWith(prefixWriting) || k.startsWith(prefixProof)) {
            if (isExam) {
                delete revealedModelKeys[k];
            } else if (revealedModelKeys[k] === false) {
                delete revealedModelKeys[k];
            }
        }
    });
    const passageCard = document.getElementById('written-passage-card');
    if (passageCard) passageCard._renderedPassageKey = '';
};

window.startWrittenExam = startWrittenExam;


window.renderWrittenQuestion = renderWrittenQuestion;
window.showPassageSwitchBanner = showPassageSwitchBanner;
window.checkIsCorrect = checkIsCorrect;
window.selectWrittenOption = selectWrittenOption;
window.finishWrittenExam = finishWrittenExam;


/* === js/ui_controller.js === */
/**
 * ==========================================================================
 * UI Controller & View Routing Engine (Navigation, Popover Menus, Shortcuts)
 * ==========================================================================
 */


let activeView = 'home';
try {
    Object.defineProperty(window, 'activeView', {
        get() { return activeView; },
        set(v) { activeView = v; },
        configurable: true
    });
} catch (e) {
    window.activeView = activeView;
}

window.enableHorizontalDragScroll = function(el, wrapperEl) {
    if (!el) return;
    const wrap = wrapperEl || el.parentElement || el;

    let isDown = false;
    let startX = 0;
    let scrollLeft = 0;
    let isDragging = false;

    function updateIndicators() {
        const maxScroll = el.scrollWidth - el.clientWidth;
        if (maxScroll <= 2) {
            wrap.classList.remove('can-scroll-left', 'can-scroll-right');
            return;
        }
        wrap.classList.toggle('can-scroll-left', el.scrollLeft > 4);
        wrap.classList.toggle('can-scroll-right', el.scrollLeft < (maxScroll - 4));
    }

    if (!el.dataset) el.dataset = {};
    if (!el.dataset.dragInit) {
        el.dataset.dragInit = 'true';

        el.addEventListener('mousedown', (e) => {
            isDown = true;
            isDragging = false;
            el.style.cursor = 'grabbing';
            startX = e.pageX - el.offsetLeft;
            scrollLeft = el.scrollLeft;
        });

        window.addEventListener('mouseup', () => {
            if (isDown) {
                isDown = false;
                el.style.cursor = 'grab';
                setTimeout(() => { isDragging = false; }, 60);
            }
        });

        el.addEventListener('mousemove', (e) => {
            if (!isDown) return;
            e.preventDefault();
            const x = e.pageX - el.offsetLeft;
            const walk = (x - startX) * 1.5;
            if (Math.abs(walk) > 3) {
                isDragging = true;
            }
            el.scrollLeft = scrollLeft - walk;
            updateIndicators();
        });

        el.addEventListener('click', (e) => {
            if (isDragging) {
                e.stopPropagation();
                e.preventDefault();
            }
        }, true);

        el.addEventListener('wheel', (e) => {
            if (Math.abs(e.deltaY) > 0) {
                e.preventDefault();
                el.scrollLeft += e.deltaY;
                updateIndicators();
            }
        }, { passive: false });

        el.addEventListener('scroll', updateIndicators, { passive: true });
    }

    setTimeout(() => {
        updateIndicators();
        const activePill = el.querySelector('.active');
        if (activePill && el.clientWidth > 0 && el.scrollWidth > el.clientWidth) {
            const pillCenter = activePill.offsetLeft + activePill.offsetWidth / 2;
            const targetScroll = Math.max(0, pillCenter - el.clientWidth / 2);
            el.scrollLeft = targetScroll;
            updateIndicators();
        }
    }, 40);
};

// History State Management for Android Physical Back & iOS Swipe Back
(function initHistoryNavigation() {
    try {
        if (window.history && window.history.replaceState) {
            window.history.replaceState({ view: 'home', step: 0 }, '');
            window.history.pushState({ view: 'home', step: 1 }, '');
        }
    } catch(e) {}

    let historyStep = 1;
    window._pushToyHistory = function(viewName) {
        try {
            if (!window.history || !window.history.pushState) return;
            historyStep++;
            window.history.pushState({ view: viewName, step: historyStep }, '');
        } catch(e) {}
    };
    window._replaceToyHistory = function(viewName) {
        try {
            if (!window.history || !window.history.replaceState) return;
            window.history.replaceState({ view: viewName, step: Math.max(1, historyStep) }, '');
        } catch(e) {}
    };
    window._resetToyHistory = function() {
        historyStep = 1;
    };
    window._getToyHistoryStep = function() {
        return historyStep;
    };

    window.addEventListener('popstate', (e) => {
        if (historyStep > 0) historyStep--;

        // 1. Check and dismiss any open drawers, modals, popovers, or audio settings masks
        let dismissedOverlay = false;
        const openOverlays = document.querySelectorAll('.drawer-mask.active, .modal-mask.active, .dict-settings-mask.active');
        if (openOverlays.length > 0) {
            openOverlays.forEach(el => el.classList.remove('active'));
            dismissedOverlay = true;
        }
        const activeDictDrawer = document.getElementById('dict-drawer-mask');
        if (activeDictDrawer && (activeDictDrawer.classList.contains('active') || activeDictDrawer.style.display === 'block' || activeDictDrawer.style.display === 'flex')) {
            if (typeof window.closeDictationDrawer === 'function') {
                window.closeDictationDrawer();
            } else {
                activeDictDrawer.classList.remove('active');
                activeDictDrawer.style.display = 'none';
            }
            dismissedOverlay = true;
        }
        const activeRegularDrawer = document.getElementById('drawer-mask');
        if (activeRegularDrawer && (activeRegularDrawer.classList.contains('active') || activeRegularDrawer.style.display === 'block')) {
            activeRegularDrawer.classList.remove('active');
            activeRegularDrawer.style.display = 'none';
            dismissedOverlay = true;
        }
        const settingsMask = document.getElementById('dict-audio-settings-mask');
        if (settingsMask && (settingsMask.classList.contains('active') || settingsMask.style.display === 'block')) {
            settingsMask.classList.remove('active');
            settingsMask.style.display = 'none';
            dismissedOverlay = true;
        }
        const popover = document.getElementById('popover-quiz-actions');
        if (popover && popover.classList.contains('show')) {
            popover.classList.remove('show');
            dismissedOverlay = true;
        }
        const rankModalOverlay = document.getElementById('rank-modal-overlay');
        if (rankModalOverlay && (rankModalOverlay.classList.contains('is-active') || rankModalOverlay.style.display === 'block')) {
            if (typeof window.closeRankModal === 'function') {
                window.closeRankModal();
            } else {
                rankModalOverlay.classList.remove('is-active');
                document.body.classList.remove('rank-modal-open');
            }
            dismissedOverlay = true;
        }
        if (!dismissedOverlay && window.HomeTabs && typeof window.HomeTabs.handleBack === 'function' && window.HomeTabs.handleBack()) {
            dismissedOverlay = true;
        }

        // If Back was pressed while a modal/drawer was open, only close the overlay and keep current view!
        if (dismissedOverlay) {
            try {
                historyStep++;
                window.history.pushState({ view: activeView, step: historyStep }, '');
            } catch(err) {}
            return;
        }

        // 2. Check if state specifies target view
        if (e.state && e.state.view && e.state.view !== activeView) {
            switchView(e.state.view, true);
            return;
        }

        // 3. Hierarchical backward navigation fallback
        if (activeView === 'quiz') {
            switchView('lobby', true);
        } else if (activeView === 'written-arena') {
            switchView('written-lobby', true);
        } else if (activeView === 'dictation-arena') {
            if (window._isDailyListening) switchView('daily-lobby', true);
            else switchView('dictation-lobby', true);
        } else if (activeView === 'lobby' || activeView === 'written-lobby' || activeView === 'dictation-lobby' || activeView === 'daily-lobby' || activeView === 'rank') {
            switchView('home', true);
        } else if (activeView === 'home') {
            // 4. Double-back exit guard on Home portal
            const now = Date.now();
            if (window._lastToyBackExitTime && (now - window._lastToyBackExitTime < 2500)) {
                if (window.toy && typeof window.toy.closeBrowser === 'function') {
                    window.toy.closeBrowser().catch(() => {});
                }
                return;
            }
            window._lastToyBackExitTime = now;
            try {
                historyStep++;
                window.history.pushState({ view: 'home', step: historyStep }, '');
            } catch(err) {}
            if (typeof showToyToast === 'function') {
                showToyToast('再次返回退出应用');
            }
        }
    });
})();

function switchView(viewName, isPopstate = false, isReplace = false) {
    window._navActionSeqId = (window._navActionSeqId || 0) + 1;
    if (!isPopstate && viewName !== activeView) {
        if (isReplace && typeof window._replaceToyHistory === 'function') {
            window._replaceToyHistory(viewName);
        } else if (typeof window._pushToyHistory === 'function') {
            window._pushToyHistory(viewName);
        }
    }

    // If navigating away from listening quiz arena, pause audio player
    if (activeView === 'quiz' && viewName !== 'quiz') {
        if (typeof pauseAudio === 'function') {
            pauseAudio();
        }
    }

    // If navigating away from dictation arena, pause audio player
    if (activeView === 'dictation-arena' && viewName !== 'dictation-arena') {
        if (typeof window.clearDictAutoAdvance === 'function') {
            window.clearDictAutoAdvance();
        }
        if (window.DictAudioEngine && typeof window.DictAudioEngine.stop === 'function') {
            window.DictAudioEngine.stop();
        }
        const audioPlayer = document.getElementById('dictation-audio-player');
        if (audioPlayer) audioPlayer.pause();
        if (viewName !== 'daily-lobby') {
            window._isDailyListening = false;
            window._currentDailyDay = 0;
        }
    }

    const previousView = activeView;
    const isLeavingArena = (
        (previousView === 'quiz' || previousView === 'written-arena' || previousView === 'dictation-arena') &&
        viewName !== previousView
    );
    if (isLeavingArena && typeof window.saveUserCloudData === 'function') {
        window.saveUserCloudData(null, true);
    }

    activeView = viewName;
    window.activeView = viewName;
    hideContextualPopover();
    if (typeof window.dismissProofreadPopovers === 'function') {
        window.dismissProofreadPopovers();
    }

    const viewHome = document.getElementById('view-home');
    const viewLobby = document.getElementById('view-lobby');
    const viewWrittenLobby = document.getElementById('view-written-lobby');
    const viewDictationLobby = document.getElementById('view-dictation-lobby');
    const viewDailyLobby = document.getElementById('view-daily-lobby');
    const viewQuiz = document.getElementById('view-quiz');
    const viewWrittenArena = document.getElementById('view-written-arena');
    const viewDictationArena = document.getElementById('view-dictation-arena');
    const viewRank = document.getElementById('view-rank');
    const viewsContainer = document.querySelector('.views-container');

    const VIEW_MAP = {
        'home': viewHome,
        'lobby': viewLobby,
        'written-lobby': viewWrittenLobby,
        'dictation-lobby': viewDictationLobby,
        'daily-lobby': viewDailyLobby,
        'quiz': viewQuiz,
        'written-arena': viewWrittenArena,
        'dictation-arena': viewDictationArena,
        'rank': viewRank
    };
    const LOBBY_GRID_IDS = {
        'lobby': 'exam-grid',
        'written-lobby': 'written-exam-grid',
        'dictation-lobby': 'dictation-exam-grid',
        'daily-lobby': 'daily-exam-grid'
    };
    if (!window._lobbyScrollMemory) window._lobbyScrollMemory = Object.create(null);

    const quizNavGroup = document.getElementById('quiz-nav-group');
    const writtenNavGroup = document.getElementById('written-nav-group');
    const dictationNavGroup = document.getElementById('dictation-nav-group');
    const bottomNavBar = document.querySelector('.bottom-nav-bar');

    const VIEW_DEPTH = {
        'home': 0,
        'lobby': 1,
        'written-lobby': 1,
        'dictation-lobby': 1,
        'daily-lobby': 1,
        'rank': 1,
        'quiz': 2,
        'written-arena': 2,
        'dictation-arena': 2
    };

    const prevView = previousView;
    const isSameView = (prevView === viewName);
    const oldDepth = (typeof prevView === 'string' && typeof VIEW_DEPTH[prevView] === 'number') ? VIEW_DEPTH[prevView] : 0;
    const newDepth = (typeof VIEW_DEPTH[viewName] === 'number') ? VIEW_DEPTH[viewName] : 0;

    // Capture outgoing scroll metrics BEFORE switching DOM or resetting scroll
    const prevWinY = (typeof window.scrollY === 'number') ? window.scrollY : (window.pageYOffset || 0);
    if (!isSameView && LOBBY_GRID_IDS[prevView] && newDepth > oldDepth) {
        const prevGridEl = document.getElementById(LOBBY_GRID_IDS[prevView]);
        window._lobbyScrollMemory[prevView] = {
            winY: prevWinY,
            gridY: prevGridEl ? prevGridEl.scrollTop : 0
        };
    } else if (!isSameView && LOBBY_GRID_IDS[viewName] && oldDepth === 0) {
        delete window._lobbyScrollMemory[viewName];
    }

    // Cancel any in-flight dual-layer or view transition classes cleanly
    if (window._dualTransCleanTimer) {
        clearTimeout(window._dualTransCleanTimer);
        window._dualTransCleanTimer = null;
    }
    if (viewsContainer && viewsContainer.classList) {
        viewsContainer.classList.remove('is-dual-transitioning');
    }
    const allViewEls = [viewHome, viewLobby, viewWrittenLobby, viewDictationLobby, viewDailyLobby, viewQuiz, viewWrittenArena, viewDictationArena, viewRank];
    allViewEls.forEach(v => {
        if (!v) return;
        if (v._viewAnimCleanTimer) {
            clearTimeout(v._viewAnimCleanTimer);
            v._viewAnimCleanTimer = null;
        }
        v.classList.remove(
            'active',
            'is-view-leaving',
            'view-leave-push',
            'view-leave-pop',
            'view-leave-fade',
            'view-anim-push',
            'view-anim-push-over',
            'view-anim-pop',
            'view-anim-pop-under',
            'view-anim-fade',
            'view-split-enter'
        );
        if (v.style && typeof v.style.removeProperty === 'function') {
            v.style.removeProperty('--leave-offset-top');
        }
    });

    // Determine single-layer transition direction (instant outgoing unmount prevents any cross-height ghosting)
    const isDesktopPhoneShellCross = Boolean(
        !isSameView &&
        (oldDepth === 0 || newDepth === 0) &&
        typeof window.innerWidth === 'number' &&
        window.innerWidth >= 640 &&
        document.body &&
        document.body.classList &&
        !document.body.classList.contains('is-landscape') &&
        !document.body.classList.contains('is-tablet-device')
    );

    let transitionClass = '';
    if (!isSameView) {
        if (isDesktopPhoneShellCross) {
            transitionClass = 'view-anim-fade';
        } else if (newDepth > oldDepth) {
            transitionClass = 'view-anim-push';
        } else if (newDepth < oldDepth) {
            transitionClass = 'view-anim-pop';
        } else {
            transitionClass = 'view-anim-fade';
        }
    }

    updateHeaderControlsForView(viewName);

    if (quizNavGroup) quizNavGroup.style.display = 'none';
    if (writtenNavGroup) writtenNavGroup.style.display = 'none';
    if (dictationNavGroup) dictationNavGroup.style.display = 'none';
    if (bottomNavBar) {
        const showNav = (viewName === 'quiz' || viewName === 'written-arena' || viewName === 'dictation-arena');
        bottomNavBar.style.display = showNav ? 'flex' : 'none';
        if (showNav && typeof window.kickLiquidGlass === 'function') {
            setTimeout(() => window.kickLiquidGlass(), 60);
        }
    }

    // Trigger or stop practice duration tracking
    if (viewName === 'quiz' || viewName === 'written-arena' || viewName === 'dictation-arena') {
        if (typeof startPracticeTimer === 'function') startPracticeTimer();
    } else {
        if (typeof stopPracticeTimer === 'function') stopPracticeTimer();
    }
    
    // Stop any playing dictation audio when leaving dictation arena
    if (viewName !== 'dictation-arena') {
        if (window.DictAudioEngine && typeof window.DictAudioEngine.stop === 'function') {
            window.DictAudioEngine.stop();
        }
        const dictAudio = document.getElementById('dictation-audio-player');
        if (dictAudio && !dictAudio.paused) {
            dictAudio.pause();
        }
        if (typeof updateZenAudioPlayState === 'function') {
            updateZenAudioPlayState(false);
        }
        if (typeof window.hideCustomVirtualKeyboard === 'function') {
            window.hideCustomVirtualKeyboard();
        }
    }
    
    document.body.dataset.view = viewName;

    const addActiveWithAnim = (el) => {
        if (!el) return;
        el.classList.add('active');
        if (transitionClass) el.classList.add(transitionClass);
    };

    if (viewName === 'home') {
        document.querySelectorAll('.exam-card.is-activating').forEach(c => c.classList.remove('is-activating'));
        document.body.classList.add('view-home-active');
        document.body.classList.remove('view-functional-active');
        addActiveWithAnim(viewHome);
        updateDashboardStats();
        if (window.HomeTabs && typeof window.HomeTabs.refreshActivePage === 'function') {
            setTimeout(() => window.HomeTabs.refreshActivePage(), 30);
        }
    } else {
        document.body.classList.remove('view-home-active');
        document.body.classList.add('view-functional-active');
    }
    
    if (viewName === 'lobby') {
        addActiveWithAnim(viewLobby);
        if (window.currentExamLevel === 'daily' || window.currentExamLevel === 'ielts' || window.currentExamLevel === 'kaoyan') {
            window.currentExamLevel = 'cet4';
        }
        let text = '四级';
        if (window.currentExamLevel === 'cet6') text = '六级';
        else if (window.currentExamLevel === 'gaokao') text = '高考';
        document.querySelectorAll('.level-tag-bind').forEach(el => el.textContent = text);

        if (typeof updateYearFilterVisibility === 'function') updateYearFilterVisibility(window.currentExamLevel);
        if (typeof syncLobbyLevelPillsUI === 'function') syncLobbyLevelPillsUI(false);
        renderLobbyGrid(window.currentListeningFilter || 'ALL');
        updateDashboardStats();
        const b = document.getElementById('year-filter-bar');
        if (b) updateSegmentedSlider(b, false);
    } else if (viewName === 'written-lobby') {
        addActiveWithAnim(viewWrittenLobby);
        if (window.currentExamLevel === 'daily' || window.currentExamLevel === 'ielts') {
            window.currentExamLevel = 'cet4';
        }
        let text = '四级';
        if (window.currentExamLevel === 'cet6') text = '六级';
        else if (window.currentExamLevel === 'gaokao') text = '高考';
        else if (window.currentExamLevel === 'kaoyan') text = (window.currentKaoyanSubjectFilter === 'ENG2') ? '考研英语(二)' : '考研英语(一)';
        document.querySelectorAll('.level-tag-bind').forEach(el => el.textContent = text);

        if (typeof updateYearFilterVisibility === 'function') updateYearFilterVisibility(window.currentExamLevel);
        if (typeof syncLobbyLevelPillsUI === 'function') syncLobbyLevelPillsUI(false);
        renderWrittenLobbyGrid(window.currentWrittenFilterRange || 'ALL');
        updateDashboardStats();
        const b = document.getElementById('written-year-filter-bar');
        if (b) updateSegmentedSlider(b, false);
    } else if (viewName === 'dictation-lobby') {
        document.querySelectorAll('.exam-card.is-activating').forEach(c => c.classList.remove('is-activating'));
        addActiveWithAnim(viewDictationLobby);
        if (window.currentExamLevel === 'daily' || window.currentExamLevel === 'kaoyan') {
            window.currentExamLevel = 'cet4';
        }
        let text = '四级';
        if (window.currentExamLevel === 'cet6') text = '六级';
        else if (window.currentExamLevel === 'gaokao') text = '高考';
        else if (window.currentExamLevel === 'ielts') text = '雅思';
        document.querySelectorAll('.level-tag-bind').forEach(el => el.textContent = text);
        if (typeof updateYearFilterVisibility === 'function') updateYearFilterVisibility(window.currentExamLevel);
        if (typeof syncLobbyLevelPillsUI === 'function') syncLobbyLevelPillsUI(false);
        if (typeof renderDictationLobbyGrid === 'function') renderDictationLobbyGrid(window.currentDictationFilter || 'ALL');
        updateDashboardStats();
        const b = document.getElementById('dictation-year-filter-bar');
        if (b) updateSegmentedSlider(b, false);
    } else if (viewName === 'daily-lobby') {
        document.querySelectorAll('.exam-card.is-activating').forEach(c => c.classList.remove('is-activating'));
        addActiveWithAnim(viewDailyLobby);
        window.currentExamLevel = 'daily';
        if (typeof syncLobbyLevelPillsUI === 'function') syncLobbyLevelPillsUI(false);
        if (typeof renderDailyLobbyGrid === 'function') renderDailyLobbyGrid();
        if (typeof updateDailyLobbyToggleUI === 'function') updateDailyLobbyToggleUI();
        updateDashboardStats();
    } else if (viewName === 'quiz') {
        addActiveWithAnim(viewQuiz);
        if (quizNavGroup) quizNavGroup.style.display = 'flex';
        if (writtenNavGroup) writtenNavGroup.style.display = 'none';
        if (dictationNavGroup) dictationNavGroup.style.display = 'none';
    } else if (viewName === 'written-arena') {
        addActiveWithAnim(viewWrittenArena);
        if (viewWrittenArena) viewWrittenArena.classList.add('view-split-enter');
        if (writtenNavGroup) writtenNavGroup.style.display = 'flex';
        if (quizNavGroup) quizNavGroup.style.display = 'none';
        if (dictationNavGroup) dictationNavGroup.style.display = 'none';
    } else if (viewName === 'dictation-arena') {
        addActiveWithAnim(viewDictationArena);
        if (quizNavGroup) quizNavGroup.style.display = 'none';
        if (writtenNavGroup) writtenNavGroup.style.display = 'none';
        if (typeof window.syncCustomVirtualKeyboardState === 'function') {
            window.syncCustomVirtualKeyboardState();
        } else if (dictationNavGroup) {
            dictationNavGroup.style.display = 'flex';
        }
    } else if (viewName === 'rank') {
        if (typeof window.openRankModal === 'function') {
            window.openRankModal();
            return;
        }
        addActiveWithAnim(viewRank);
        fetchAndRenderRankList();
    }

    const layoutSwitcher = document.getElementById('card-layout-switcher');
    if (layoutSwitcher) {
        layoutSwitcher.style.display = (viewName === 'home') ? 'flex' : 'none';
    }

    // Restore saved lobby scroll on back-pop, or reset cleanly to top on fresh navigation
    let targetWinY = 0;
    const savedLobbyScroll = (newDepth < oldDepth && LOBBY_GRID_IDS[viewName])
        ? window._lobbyScrollMemory[viewName]
        : null;
    if (LOBBY_GRID_IDS[viewName]) {
        const targetGridEl = document.getElementById(LOBBY_GRID_IDS[viewName]);
        if (targetGridEl) {
            const desiredGridY = savedLobbyScroll ? (savedLobbyScroll.gridY || 0) : 0;
            if (targetGridEl.style) targetGridEl.style.scrollBehavior = 'auto';
            targetGridEl.scrollTop = desiredGridY;
            if (targetGridEl.style) targetGridEl.style.scrollBehavior = '';
        }
    }
    if (savedLobbyScroll && typeof savedLobbyScroll.winY === 'number') {
        targetWinY = savedLobbyScroll.winY;
    }
    if (!isSameView) {
        try {
            window.scrollTo({ top: targetWinY, left: 0, behavior: 'instant' });
            const layoutEl = document.getElementById('app-layout');
            if (layoutEl) layoutEl.scrollTop = 0;
        } catch(e) {
            try { window.scrollTo(0, targetWinY); } catch (_) {}
        }
    }

    const activeViewEl = allViewEls.find(v => v && v.classList && v.classList.contains('active'));
    if (activeViewEl && (transitionClass || viewName === 'written-arena')) {
        const cleanViewAnim = () => {
            activeViewEl.classList.remove(
                'view-anim-push',
                'view-anim-push-over',
                'view-anim-pop',
                'view-anim-pop-under',
                'view-anim-fade',
                'view-split-enter'
            );
            activeViewEl._viewAnimCleanTimer = null;
        };
        if (typeof activeViewEl.addEventListener === 'function' && transitionClass) {
            activeViewEl.addEventListener('animationend', (ev) => {
                if (!ev || ev.target === activeViewEl) cleanViewAnim();
            }, { once: true });
        }
        activeViewEl._viewAnimCleanTimer = setTimeout(cleanViewAnim, 200);
    }
    if (viewName === 'home' && window.UXSegmentedGlider) {
        window.UXSegmentedGlider.sync('#home-training-mode-switcher', false);
        if (typeof requestAnimationFrame === 'function') {
            requestAnimationFrame(() => window.UXSegmentedGlider.sync('#home-training-mode-switcher', false));
        }
    }
}
window.switchView = switchView;

function triggerExamGridFilterTransition(gridOrId) {
    const grid = (typeof gridOrId === 'string') ? document.getElementById(gridOrId) : gridOrId;
    if (!grid || !grid.classList) return;
    if (grid._filterAnimTimer) clearTimeout(grid._filterAnimTimer);
    grid.classList.remove('grid-filter-switching');
    void grid.offsetWidth;
    grid.classList.add('grid-filter-switching');
    grid._filterAnimTimer = setTimeout(() => {
        grid.classList.remove('grid-filter-switching');
        grid._filterAnimTimer = null;
    }, 280);
}
window.triggerExamGridFilterTransition = triggerExamGridFilterTransition;

